(window.GIM_TS=window.GIM_TS||{})["Ketubot.6"]={"from":144,"a":[["\u0003משום ר' אליעזר אמרו\u0004 שאף בשהחזירה כשהיא קטנה וגדלה אצלו, הריהי \u0003חולצת ולא מתייבמת.\u0004 ולכאורה נראה שהמחלוקת היא האם בזמן היותה בוגרת הוא בועל אותה לשם קידושין גמורים, או שהוא סומך על קידושיו שנתקדשה לו בעודה קטנה, וקידושין אלה אינם קידושין גמורים. אם כן, \u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 ש\u0003כטעות אשה אחת דמי\u0004 \u0005[נחשב]\u0006 \u0003ופליגי\u0004 \u0005[ו\u0006הם \u0005חלוקים]!\u0006","ודוחים: אין זו המחלוקת אלא \u0003התם נמי בהא קמיפלגי\u0004 \u0005[שם גם כן בזה\u0006 הם \u0005חלוקים],\u0006 בשאלה אם יש כאן טעות: \u0003מר\u0004 \u0005[חכם זה,\u0006 תנא קמא\u0005]\u0006 \u0003סבר\u0004 ש\u0003אדם יודע שאין קידושי קטנה כלום, ו\u0004לכן כאשר גדלה \u0003גמר\u0004 בדעתו (החליט) \u0003ובעל לשם קידושין.\u0004 ולכן אם מת בעלה — מתייבמת. \u0003ומר\u0004 \u0005[וחכם זה,\u0006 ר' אליעזר\u0005]\u0006 \u0003סבר\u0004 ש\u0003אין אדם יודע שאין קידושי קטנה כלום, וכי קא בעל\u0004 \u0005[וכאשר\u0006 הוא \u0005בועל\u0006 אותה\u0005] —\u0006 \u0003אדעתא\u0004 \u0005[על דעת]\u0006 ה\u0003קידושין הראשונים\u0004 שאינם גמורים \u0003קא\u0004 \u0005[הוא]\u0006 ש\u0003בעל\u0004 ואינה נשואה לו מן התורה, ולכן אינה מתייבמת.","ומעירים: \u0003אתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 כשיטת רבה שאין מחלוקת בטעות אשה אחת, אלא לדעת הכל אינה צריכה ממנו גט, ש\u0003אמר רב אחא בר יעקב אמר ר' יוחנן: המקדש על תנאי ובעל\u0004 ולא ביטל את התנאי — \u0003דברי הכל אינה צריכה הימנו גט. איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא בר אחתיה\u0004 \u0005[בן אחותו]\u0006 של רב אחא בר יעקב, שנינו: \u0003חליצה מוטעת כשירה.\u0004 ושאלו: \u0003איזו היא חליצה מוטעת? אמר ריש לקיש: כל שאומר לו\u0004 ליבם \u0003\"חלוץ לה, ובכך,\u0004 על ידי החליצה, \u0003אתה כונסה\"\u0004 — אף שלא נתכוון לפוטרה כלל בחליצה זו, מכל מקום החליצה מועילה.","\u0003אמר ר' יוחנן, אני שונה\u0004 בהלכות חליצה: \u0003בין שנתכוון הוא\u0004 לפוטרה בחליצתו \u0003ולא נתכוונה היא\u0004 לשם כך, \u0003בין שנתכוונה היא ולא נתכוון הוא — חליצתה פסולה, עד שיתכוונו שניהם. ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 שבמקרה זה שכוונתו לכנוס \u0003חליצתה כשרה? אלא אמר ר' יוחנן\u0004 הכוונה היא: \u0003כל שאומר לו\u0004 ליבם \u0003\"חלוץ לה על מנת שתתן לך\u0004 בשכר זה \u0003מאתים זוז\",\u0004 והסכימה לתנאו, ולאחר מכן סירבה לתת לו, ואמרה שמתחילה רק הטעתה אותו.","ומכאן נלמד לענייננו: \u0003אלמא\u0004 \u0005[מכאן]\u0006 \u0003כיון דעבד\u0004 \u0005[שעשה]\u0006 \u0003מעשה, אחולי אחליה לתנאיה\u0004 \u0005[\u0006ביטל ו\u0005מחל על תנאו],\u0006 שאף שהתנה שאינו עושה זאת אלא על מנת שיקבל סכום כסף, אין ביטול התנאי מבטל את המעשה שעשה בפועל. ואם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בענייננו שקידש על תנאי, \u0003כיון\u0004 ש\u0003בעל, אחולי אחליה לתנאיה\u0004 \u0005[מחל את תנאו],\u0006 וקשה על רב אחא בר יעקב!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003בר בי\u0004 \u0005[בן בית]\u0006 ה\u0003רב,\u0004 תלמיד היושב בבית המדרש: האם \u0003שפיר קא אמרת\u0004 \u0005[יפה אמרת]?\u0006 — אין הדברים כפשוטם משום מחילת התנאי, \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003כל\u0004 דיני \u0003תנאי מהיכא גמרינן\u0004 \u0005[מהיכן אנו לומדים] —\u0006 \u0003מתנאי בני גד ובני ראובן\u0004 שהתנה משה איתם שאם לא יעברו חלוצים לפני העם — לא יקבלו נחלה בעבר הירדן, ולפיו אנו למדים מה הכללים החלים לגבי תנאים שונים, ובין השאר אפשר ללמוד משם כי","\u0003תנאה\u0004 \u0005[תנאי]\u0006 ש\u0003אפשר לקיומיה\u0004 \u0005[לקיימו]\u0006 \u0003על ידי שליח כי התם\u0004 \u0005[כמו שם]\u0006 שהרי נמסר הדבר ממשה ליהושע ולזקני העדה שיתנו להם את נחלתם, \u0003הוי תנאיה תנאה\u0004 \u0005[\u0006הרי \u0005תנאו הוא תנאי]\u0006 ותנאי כזה תופס. ותנאי \u0003דלא\u0004 \u0005[שאי]\u0006 \u0003אפשר לקיומיה\u0004 \u0005[לקיימו]\u0006 \u0003על ידי שליח כי התם\u0004 \u0005[כמו שם] —\u0006 \u0003לא הוי תנאה\u0004 \u0005[אינו תנאי].\u0006 ולכן, חליצה שאי אפשר לעשותה על ידי שליח, שהרי רק היבם בלבד יכול לחלוץ לאשת אחיו — אין תוקף לתנאי ומשום כך החליצה מועילה, ואין מכאן הוכחה לענייננו שכשבעל מוחל על התנאי.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ביאה\u0004 שבא אדם על אשה לשם קידושין \u0003דלא\u0004 \u0005[שאי]\u0006 \u0003אפשר לקיומיה\u0004 \u0005[לקיימה]\u0006 \u0003על ידי שליח כי התם\u0004 \u0005[כמו שם]\u0006 בתנאי בני גד ובני ראובן, \u0003וקא הוי תנאה\u0004 \u0005[והריהו תנאי],\u0006 שיכול אדם לומר לאשה שהוא בועלה לשם קידושין על מנת שיתקיים תנאי מסויים, ואם בטל התנאי — בטלים הקידושין!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 בקידושין יש טעם מיוחד, \u0003משום דאיתקוש\u0004 \u0005[שהוקשו,\u0006 הושוו\u0005]\u0006 ה\u0003הויות להדדי\u0004 \u0005[זו לזו]\u0006 ומכאן למדים שהווית הקידושין על ידי ביאה, כמוה כהווית הקידושין על ידי כסף ושטר, וכיון שהוויות אלה על ידי כסף ושטר נעשות על ידי שליח, אפשר לעשות בהן תנאי שהרי אף קידושי ביאה אפשר להתנות בהם.","\u0003אמר רב עולא בר אבא אמר עולא אמר ר' אלעזר: המקדש במלוה,\u0004 שקידשה בחוב שחייבת לו, ובכך קידשה \u0003ובעל\u0004 אף על פי שכרגיל אין קידושין במלוה תופסים, או המקדש \u0003על תנאי\u0004 (שלא נתקיים) \u0003ובעל,\u0004 או המקדש \u0003בפחות משוה פרוטה ובעל — דברי הכל צריכה הימנו גט.\u0004 שאף על פי שלא תפסו קידושין אלה כשלעצמם, כיון שבעל — הרי היא מקודשת בביאה זאת.","\u0003אמר רב יוסף בר אבא אמר ר' מנחם אמר ר' אמי: המקדש בפחות משוה פרוטה ובעל — צריכה הימנו גט.\u0004 מדוע? \u0003בהא\u0004 \u0005[בזה]\u0006 \u0003הוא דלא טעי\u0004 \u0005[שאינו טועה],\u0006 שיודע שאין קידושין חלים בפחות משוה פרוטה, ולכן, כשבועל — גומר בדעתו לשם קידושין. \u0003אבל בהנך טעי\u0004 \u0005[ב\u0006אלה ה\u0005אחרים,\u0006 במלוה ובתנאי, הוא \u0005טועה]\u0006 ובועל על דעת הקידושין הראשונים, ולכן אינה צריכה גט.","\u0003אמר רב כהנא משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא: המקדש על תנאי ובעל — צריכה הימנו גט,\u0004 וכדברי ר' אלעזר. ומסופר: \u0003זה היה מעשה\u0004 שקידש אדם על תנאי ובעל \u0003ולא היה כח בחכמים להוציאה בלא גט,\u0004 שלא יכלו להחליט בוודאות שלא חלו הקידושין כלל, ולכן הצריכו לתת לה גט.","ומעירים: ודבר זה בא \u0003לאפוקי מהאי תנא\u0004 \u0005[להוציא מ\u0006דבריו של \u0005תנא זה].\u0006 ש\u0003אמר רב יהודה אמר שמואל משום\u0004 (משמו של) \u0003ר' ישמעאל,\u0004 נאמר בסוטה: \u0003\"והוא לא נתפשה\"\u0004 (במדבר ה, יג), כלומר, לא נאנסה. וכיון שנבעלה לאחר מרצון — הרי היא \u0003אסורה\u0004 לבעלה. ומכאן נלמד: \u0003הא\u0004 \u0005[הרי]\u0006 זו ש\u0003נתפשה\u0004 באונס — \u0003מותרת\u0004 לבעלה. \u0003ויש לך אחרת שאף על פי שלא נתפשה\u0004 באונס, וברצון נבעלה, בכל זאת \u0003מותרת\u0004 ואינה נחשבת כסוטה. \u0003ואיזו זו? שקדושיה קידושי טעות, שאפילו בנה\u0004 שנולד מהנישואין הללו \u0003מורכב על כתיפה,\u0004"],["\u0003ממאנת והולכת לה.\u0004 שלדעתו, כיון שהיתה טעות בקידושין — לא חלו הנישואין כלל, למרות שהיתה פה בודאי בעילה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אשה שכאשר נתקדשה התנה עמה בעלה שהוא מקדשה על מנת שאין עליה נדרים, והיו עליה נדרים ו\u0003הלכה אצל חכם והתירה\u0004 — הרי היא \u0003מקודשת.\u0004 ואם התנה איתה שמקדש אותה על מנת שאין בה מומים, והלכה \u0003אצל רופא וריפא אותה\u0004 ממומיה — \u0003אינה מקודשת.\u0004 ומסבירים: \u0003מה בין חכם לרופא?\u0004 מדוע במקרה אחד מקודשת ובמקרה אחר לא? — \u0003חכם\u0004 כשמתיר את הנדר, \u0003עוקר את הנדר מעיקרו,\u0004 וכאילו לא נדרה כלל, ונמצא שבשעה שקידש אותה אכן לא היו עליה נדרים. \u0003ו\u0004אילו ה\u0003רופא אינו מרפא אלא מכאן ולהבא,\u0004 ובשעת הקידושין הלא היו בה מומים, בניגוד לתנאי, ולכן אינה מקודשת.","ומקשים, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא אחרת\u0005]:\u0006 הלכה \u0003אצל חכם והתירה,\u0004 או \u0003אצל רופא וריפא אותה — אינה מקודשת! אמר רבא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 — כשיטת \u0003ר' מאיר\u0004 היא, \u0003הא\u0004 \u0005[\u0006וברייתא \u0005זו]\u0006 — כשיטת \u0003ר' אלעזר\u0004 היא. ומסבירים: \u0003הא\u0004 \u0005[זו],\u0006 הברייתא האומרת שכאשר הלכה לחכם והתירה הריהי מקודשת — כשיטת \u0003ר' מאיר\u0004 ש\u0003אמר: אדם רוצה,\u0004 כלומר, מוכן, \u0003שתתבזה אשתו בבית דין,\u0004 ואינו מקפיד כשהולכת להתיר את נדרה. \u0003הא\u0004 \u0005[\u0006ו\u0005זו]\u0006 — כשיטת \u0003ר' אלעזר,\u0004 ש\u0003אמר: אין אדם רוצה שתתבזה אשתו בבית דין,\u0004 ומשום כך, גם כשהלכה אצל חכם והתיר לה הדיין, בעלה עדיין מקפיד עליה, שלא התכוון בעלה שתלך ותבייש עצמה בבית דין, ולכן גם לאחר ביטול הנדר אין הקידושין תופסים.","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 אותה הלכה יסודית שחולקים בה ר' מאיר ור' אלעזר? — \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003המוציא את אשתו משום נדר\u0004 שנדרה, ואחר כך התחרט ורוצה להחזירה — \u0003לא יחזיר.\u0004 וכן אם מוציא אותה \u0003משום שם רע\u0004 שיצא עליה — \u0003לא יחזיר,\u0004 שמא, כאשר ימצא חכם שיתיר את הנדר, או שיתברר שהשם הרע לא היה בו ממש יאמר שאילו היה יודע לא היה מגרשה, ונמצא שהוא מערער למפרע את תוקפו של הגט. ולכן מודיעים לו שאם מגרשה משום נדר או שם רע — אינו רשאי עוד להחזירה.","\u0003ר' יהודה אומר: כל נדר שידעו בו רבים,\u0004 שלפי הדין אין לו הפרה — \u0003לא יחזיר.\u0004 וכל נדר ש\u0003לא ידעו בו רבים,\u0004 אלא היה בינו ובינה — \u0003יחזיר. ר' מאיר אומר: כל נדר שצריך חקירת חכם,\u0004 כלומר, שאין הבעל יכול להפר אותו וצריך שהחכם ידקדק בדבר עד שימצא פתח להתיר אותו — \u0003לא יחזיר,\u0004 שהרי יכול לטעון שאילו ידע שיש התרה לנדר כזה לא היה מגרשה, ונמצא מערער על הגט שנתן לה. \u0003ושאינו צריך חקירת חכם\u0004 ויודע שיכול להפירו בעצמו — \u0003יחזיר.\u0004 שאין לחשוש לקלקול, שהרי ידע שיכול לבטל הנדר, ובכל זאת גמר בלבו לגרשה.","\u0003ר' אלעזר אומר: אחד\u0004 נדר ה\u0003צריך\u0004 חקירת חכם, \u0003ואחד\u0004 ש\u0003אינו צריך\u0004 חקירה — \u0003לא יחזיר. אמר ר' אלעזר\u0004 טעם לדבריו: \u0003לא אסרו\u0004 להחזירה לאחר שנאסרה בנדר ש\u0003צריך\u0004 חקירת חכם \u0003אלא מפני\u0004 נדר \u0003שאינו צריך.\u0004 ומסבירים את השיטות: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 האומר כי כל נדר שידעו בו רבים, אין לו הפרה? — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006"],["\u0003\"ולא הכום בני ישראל כי נשבעו להם נשיאי העדה\"\u0004 (יהושע ט, יח), הרי שאף שהיתה זו שבועה בטעות, שהרי הגבעונים הטעו את ישראל, מכל מקום כיון שנעשה הדבר ברבים — אין לו התרה. ושואלים: \u0003וכמה\u0004 הם \u0003רבים\u0004 לענין זה? \u0003רב נחמן בר יצחק אמר:\u0004 רבים הם \u0003שלשה,\u0004 וכן אמרו לענין הלכות נדה: \u0003\"ימים\"\u0004 סתם — הרי מיעוט ימים \u0003שנים,\u0004 וכיון שנאמר \u0003\"\u0004ימים \u0003רבים\"\u0004 — הריהם \u0003שלשה. ר' יצחק אמר:\u0004 רבים לענין נדר הוא \u0003עשרה,\u0004 כי בפרשת הגבעונים \u0003\"עדה\" כתיב בהו\u0004 \u0005[נאמר בהם]\u0006 (\"נשיאי העדה\") ולמדנו כבר כי אין \"עדה\" פחות מעשרה.","שנינו, \u0003ר' מאיר אומר:\u0004 המגרש את אשתו משום נדר, הרי \u0003כל נדר ש\u0004נמצא עליה ו\u0003צריך חקירת חכם\u0004 כדי להפירו, לפי שאין הבעל יכול להפר אותו — \u0003לא יחזיר. ר' אלעזר אומר: לא אסרו\u0004 להחזירה לאחר שנאסרה בנדר ש\u0003צריך\u0004 חקירת חכם \u0003אלא מפני\u0004 נדר \u0003שאינו צריך.\u0004 ומסבירים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005הם חלוקים]?\u0006 — \u0003ר' מאיר סבר: אדם רוצה,\u0004 כלומר, מוכן, \u0003שתתבזה אשתו בבית דין,\u0004 ואינו מקפיד כשהולכת להתיר את נדרה. ולכן יש לחשוש שיאמר הבעל שאילו היה יודע שיש היתר לנדר לא היה מגרשה, ובזה יערער את תוקף הגט. \u0003ר' אלעזר סבר: אין אדם רוצה שתתבזה אשתו בבית דין\u0004 כלל. ולכן, לא יוכל לערער את הגט. ולא אסרו להחזיר בנדר שצריך חקירת חכם אלא משום נדר שאינו צריך חקירה, שיכול הבעל לומר שלא ידע שיש דרך להפר את נדרו. ויבוא לבטל את גיטה.","\u0003רבא אמר:\u0004 אפשר לתרץ את הברייתא האומרת שאף אם הלכה לחכם והתירה אינה מקודשת, באופן אחר; \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003באשה חשובה עסקינן\u0004 \u0005[עוסקים אנו],\u0006 שמצד אחד אינו רוצה בה מפני שהיא נדרנית, ואולם מאחר והיא בת למשפחה חשובה גם אינו רוצה לגרשה, \u0003דאמר\u0004 \u0005[שאומר]:\u0006 \u0003לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לי דאיתסר\u0004 \u0005[שאהיה אסור]\u0006 \u0003ב\u0004כל \u0003קרובותיה,\u0004 שהוא מעונין להיות קשור בקשר נישואין עם משפחה חשובה זו, ואם יתפסו בה קידושיו, גם אם יגרשנה, ייאסר באמה ובאחותה, ולכן הוא מעדיף שהקידושין לאותה אשה לא יחולו מעיקרם.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003סיפא דקתני\u0004 \u0005[הסוף\u0006 של אותה ברייתא \u0005ששנה]\u0006 בה: \u0003אבל הוא\u0004 שקידש בתנאי שאין עליו נדרים או מום ו\u0003שהלך אצל חכם\u0004 שיתיר את נדריו \u0003והתירו,\u0004 או \u0003אצל רופא וריפא אותו\u0004 ממומיו — הרי היא \u0003מקודשת,\u0004 ולפי זה \u0003ליתני\u0004 \u0005[שישנה]\u0006 גם שם ש\u0003אינה מקודשת, ולימא\u0004 \u0005[ונאמר]\u0006 גם כן כי \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003באדם חשוב\u0004 ממשפחה חשובה \u0003עסקינן\u0004 \u0005[אנו עוסקים]\u0006 \u0003דאמרה\u0004 \u0005[שאומרת]:\u0006 \u0003לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לי דאיתסר בקריביה\u0004 \u0005[שאהיה אסורה בקרוביו]!\u0006","ומשיבים: יש הבדל בין איש לאשה, כי \u0003איהי\u0004 \u0005[היא,\u0006 אשה\u0005]\u0006, \u0003בכל\u0004 גבר \u0003דהו\u0004 \u0005[\u0006איזה \u0005שהוא]\u0006 \u0003ניחא\u0004 \u0005[נוח]\u0006 \u0003לה,\u0004 אפילו אם יש בו חסרון, \u0003כ\u0004דברי \u0003ריש לקיש.\u0004 ש\u0003אמר ריש לקיש:\u0004 אומרות הנשים \u0003\"טב למיתב טן דו מלמיתב ארמלו\u0004 \u0005[טוב לשבת ביחד בשניים מלשבת אלמנה,\u0006 ביחידות\u0005]\u0006 \u0003\". אביי אמר,\u0004 כך אומרות הנשים: \u0003דשומשמנא גברא כורסיה בי חראתא רמי לה\u0004 \u0005[\u0006זו \u0005שבעלה\u0006 קטן \u0005כנמלה, את כסאה היא שמה בין השרות]\u0006 שהיא מרגישה את עצמה חשובה מעצם היותה נשואה.","\u0003רב פפא אמר\u0004 פתגם אחר: \u0003דנפסא גברא, תיקרייה בסיפי בבא ותיתיב\u0004 \u0005[\u0006זו \u0005שבעלה\u0006 הוא \u0005מנפץ צמר,\u0006 שאומנותו בזויה, \u0005קוראה לו לשבת\u0006 עימה \u0005על סף הבית]\u0006 ומתגאה בו, ששמחה בכך שהיא נשואה. וכיוצא בו \u0003רב אשי אמר: דקלסא גברא לא בעי טלפחי לקידרא\u0004 \u0005[\u0006זו \u0005שבעלה\u0006 הוא \u0005בזוי אינה צריכה עדשים לקדירה]\u0006 שהיא מרוצה כל כך בעצם העובדה שהיא נשואה עד שמוכנה לוותר אפילו על מזונות ממנו. ומעירים: \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003וכולן,\u0004 כל הנשים הללו שנראות כנהנות כל כך מנישואין — כולן \u0003מזנות ותולות\u0004 את הוולדות \u0003בבעליהן,\u0004 שזהו טעם נוסף מדוע הן מעוניינות להיחשב כנשואות.","שנינו במשנה ש \u0003כל מומין שפוסלין\u0004 בכהנים פוסלים בנשים. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בתוספתא: \u0003הוסיפו עליהן\u0004 לגבי מומי נשים גם \u0003זיעה, ושומא\u0004 (יבלת) \u0003וריח הפה.\u0004 ושואלים: \u0003והני בכהני לא פסלי\u0004 \u0005[ו\u0006כי מומים \u0005אלה בכהנים אינם פוסלים]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 לגבי מומי הבהמות: \u0003הזקן, והחולה, והמזוהם. ותנן\u0004 \u0005[ושנינו\u0006 במשנה אחרת\u0005]\u0006 \u0003מומין אלו\u0004 שאמרו בבהמה, \u0003בין\u0004 שהם \u0003קבועין בין\u0004 שהם \u0003עוברין\u0004 לאחר זמן — \u0003פסולין באדם.\u0004 הרי שזוהמה וזיעה פוסלים גם בכהנים!","\u0003אמר ר' יוסי בר' חנינא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן\u0004 שאמרנו שאינם פוסלים בכהנים, הרי זה \u0003בזיעה עוברת,\u0004 שאפשר להתרחץ ולהעביר את הזיעה, ואילו \u0003כאן\u0004 שאומרים שהוא נחשב למום בכהנים, מדובר \u0003בזיעה שאינה עוברת.\u0004","\u0003רב אשי אמר:\u0004 עיקרה של השאלה אינו מבוסס, וכי \u0003זיעה\u0004 על \u0003מזוהם קא רמית\u0004 \u0005[אתה מטיל,\u0006 מראה סתירה\u0005]?\u0006 שמזוהם הוא שריחו רע תמיד, והוא פוסל בין בבהמה ובין באדם. והטעם שזיעה אינה נחשבת כמום בכהנים, כי \u0003התם גבי\u0004 \u0005[שם אצל]\u0006 \u0003כהנים אפשר לעברה\u0004 \u0005[להעביר אותה]\u0006 לפי שעה \u0003בקיוהא דחמרא\u0004 \u0005[בחומץ יין],\u0006 \u0003ומריח הפה נמי\u0004 \u0005[גם כן]\u0006 \u0003אפשר דנקט פילפלא בפומיה ועביד\u0004 \u0005[שיחזיק פלפל בפיו\u0006 שיבטל את ריח הפה לפי שעה \u0005ויעבוד]\u0006 \u0003עבודה\u0004 באותה שעה. \u0003אבל גבי\u0004 \u0005[אצל]\u0006 \u0003אשה\u0004 שנמצאת במחיצת בעלה כל הזמן \u0003לא\u0004 \u0005[אי]\u0006 \u0003אפשר\u0004 שכל הזמן תעשה כך, ולכן מום זה פוסל בנשים ולא בכהנים. שנינו בברייתא ששומא היא מום באשה.","ושואלים: \u0003האי\u0004 \u0005[זו]\u0006 ה\u0003שומא היכי דמיא\u0004 \u0005[כיצד היא בדיוק]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 זו שומה כזו \u0003דאית\u0004 \u0005[שיש,\u0006 שצומח\u0005]\u0006 \u0003בה שער\u0004 — \u0003הכא והכא פסלה\u0004 \u0005[כאן וכאן,\u0006 בנשים ובכהנים, היא \u0005פוסלת],\u0006 \u0003אי דלא אית\u0004 \u0005[אם שאין]\u0006 \u0003בה שער, אי\u0004 \u0005[אם]\u0006 \u0003שומא גדולה היא — הכא והכא פסלה\u0004 \u0005[כאן וכאן\u0006 היא \u0005פוסלת],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003שומא קטנה היא — הכא והכא לא פסלה\u0004 \u0005[כאן וכאן אינה פוסלת],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שומא שיש בה שער — הרי זה מום, אין בה שער,\u0004 אם היתה \u0003גדולה — הרי זה מום, קטנה — אין זה מום.\u0004 ושואלים: \u0003ואיזוהי גדולה? פירש רבן שמעון בן גמליאל: עד כ\u0004מטבע \u0003איסר האיטלקי,\u0004 ופחות מזה אינה נקראת שומה גדולה.","ומשיבים: \u0003אמר ר' יוסי בר' חנינא:\u0004 כאן מדובר \u0003ב\u0004שומה שהיתה \u0003עומדת על פדחתה\u0004 (מצחה), שלמרות שהיא קטנה, כיון שהיא במקום בולט היא מכערת אותה ביותר. ושואלים: אם היתה על \u0003פדחתה — ראה וניפייס\u0004 \u0005[והתפייס]\u0006 \u0003הוא,\u0004 שהרי זהו דבר הנראה, ואם הסכים לשאתה — אינו יכול לגרשה אחר כך משום כך! \u0003אמר רב פפא:\u0004 מדובר שם \u0003ב\u0004שומה ה\u0003עומדת לה תחת כפה של ראשה, וזימנין דמתחזיא וזימנין דלא מתחזיא\u0004 \u0005[ופעמים שהיא נראית ופעמים שאיננה נראית]\u0006 ולכן צריך היה לומר ששומה כזו היא מום.","\u0003אמר רב חסדא: הא מילתא מגברא רבה שמיע לי\u0004 \u0005[דבר זה\u0006 שאומר, \u0005מאדם גדול שמעתי אותו]\u0006 \u0003ומנו\u0004 \u0005[ומיהו]\u0006 אדם גדול זה — \u0003ר' שילא:\u0004 אשה ש\u0003נשכה כלב ונעשה מקומו\u0004 של הפצע \u0003צלקת — הרי זה מום.\u0004 ועוד \u0003אמר רב חסדא: קול עבה באשה — הרי זה מום, שנאמר: \"כי קולך ערב ומראך נאוה\"\u0004 (שיר השירים ב, יד). \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' נתן ביראה: בין דדי אשה טפח. סבר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא\u0004 כשהיה \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב אשי למימר\u0004 \u0005[לומר]\u0006 שהכוונה היא \u0003טפח למעליותא\u0004 \u0005[למעלה,\u0006 כשבח\u0005]\u0006 שאם יש בין השדיים מרחק טפח — הרי זה נוי לאשה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי: גבי מומין תניא\u0004 \u0005[שנויה]\u0006 ברייתא זו, והכוונה היא, שאם יש מרחק כזה — הרי זה נחשב למום. ושואלים: \u0003וכמה\u0004 רווח יהיה כדי שיהיה נחשב לנוי? \u0003אמר אביי: שלש אצבעות.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' נתן אומר: כל אשה שדדיה גסין\u0004 (גדולים) \u0003משל חברותיה — הרי זה מום.\u0004 ושואלים: \u0003וכמה\u0004 מהו השיעור של יתרון גודל זה? \u0003אמר ר' מיישא בר בריה\u0004 \u0005[בן בנו]\u0006 של \u0003רבי יהושע בן לוי משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יהושע בן לוי:\u0004 כשהם גדולים \u0003טפח\u0004 יותר מן הרגיל. ושואלים: \u0003ומי איכא כי האי גוונא\u0004 \u0005[והאם יש כגון זה]\u0006 שיהיו גדולים יותר כל כך? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003דאמר רבה בר בר חנה: אני ראיתי ערביא אחת שהפשילה דדיה לאחוריה והניקה את בנה,\u0004 הרי שייתכן שהשדיים יהיו גדולים ביותר בנשים מסויימות.","כיון שהוזכר דבר תורה בשמו של נכדו של ר' יהושע בן לוי, מביאים עוד דבר בשמו. נאמר: \u0003\"ולציון יאמר איש ואיש ילד בה והוא יכוננה עליון\"\u0004 (תהלים פז, ה). \u0003אמר ר' מיישא בר בריה\u0004 \u0005[בן בנו]\u0006 של \u0003ר' יהושע בן לוי: אחד הנולד בה\u0004 בציון, \u0003ואחד המצפה לראותה,\u0004 שניהם נחשבים כבני ציון. \u0003אמר אביי: וחד מינייהו עדיף כתרי מינן\u0004 \u0005[ואחד מהם,\u0006 מבני ארץ ישראל, \u0005עדיף\u0006 ושקול \u0005כשניים מאתנו,\u0006 מהבבליים\u0005].\u0006 \u0003אמר רבא,\u0004 יש להוסיף: \u0003וחד מינן כי סליק להתם\u0004 \u0005[ואחד מאתנו כשהוא עולה לשם,\u0006 לארץ ישראל\u0005] —\u0006 \u0003עדיף כתרי מינייהו\u0004 \u0005[כשניים מהם].\u0006 וראיה לדברי אביי \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003ר' ירמיה דכי הוה הכא\u0004 \u0005[שכאשר היה כאן,\u0006 בבבל\u0005]\u0006 \u0003לא הוה ידע\u0004 \u0005[היה יודע]\u0006 \u0003מאי קאמרי רבנן\u0004 \u0005[מה אומרים חכמים],\u0006 שלא היה חכם חשוב כלל, ואילו \u0003כי סליק להתם\u0004 \u0005[כאשר עלה לשם,\u0006 לארץ ישראל\u0005]\u0006 \u0003קרי לן \"בבלאי טפשאי\"\u0004 \u0005[היה קורא לנו \"בבליים טפשים\"].\u0006 משמע שהחכים ביותר בעלותו לארץ ישראל.","\u0003היו בה מומין ועודה בבית אביה\u0004 שעדיין לא נשאת — \u0003האב צריך להביא ראיה שמשנתארסה היו\u0004 (נוצרו) \u0003בה מומין הללו, ונסתחפה שדהו\u0004 של הארוס, שאירע הדבר כשהאשה היתה ברשותו, ולא נתבטלו הקידושין. אם כבר נשאת ו\u0003נכנסה לרשות הבעל\u0004 ונמצאו בה מומים — \u0003הבעל צריך להביא ראיה שעד שלא נתארסה היו בה מומין אלו, ו\u0004לכן \u0003היה מקחו מקח טעות.\u0004 כל אלו \u0003דברי ר' מאיר. וחכמים אומרים: במה דברים אמורים\u0004 שהבעל יכול לטעון שמצא מומים באשה ורוצה לבטל את הקידושין — \u0003במומין שבסתר,\u0004"],["\u0003אבל במומין שבגלוי — אינו יכול לטעון,\u0004 שבודאי ראה אותם לפני הקידושין וקיבל עליו. \u0003ואם יש מרחץ באותה העיר\u0004 בה היא גרה שכל הנשים באות לרחוץ בו — \u0003אף מומין שבסתר אינו יכול לטעון\u0004 שלא ידע עליהם, \u0003מפני שהוא בודקה בקרובותיו,\u0004 שמבקש מאחת מקרובותיו שתראה את הנערה שהוא עומד לשאת.","שנינו במשנה שאם היו בה מומים בעודה בבית אביה, צריך האב להביא ראיה שנולדו בה המומים לאחר האירוסין. ומדייקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 — \u0003דמייתי\u0004 \u0005[שמביא]\u0006 \u0003האב ראיה, הא\u0004 \u0005[הרי]\u0006 אם \u0003לא מייתי\u0004 \u0005[מביא]\u0006 \u0003האב ראיה\u0004 — אזי \u0003הבעל מהימן\u0004 (נאמן) לומר שהיו בה המומים עוד קודם לכן, והיה מיקחו מיקח טעות. \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 הלכה זו? כשיטת \u0003ר' יהושע היא\u0004 ש\u0003אמר\u0004 במשנה (לעיל כתובות יב, ב) כאשר האשה טוענת שנאנסה לאחר שנתארסה ובעלה טוען שהיה זה קודם לכן: \u0003לא מפיה אנו חיין,\u0004 שאין סומכים על טענתה של האשה, וצריכה להביא ראיה לדבריה.","וממשיכים: \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של משנתנו\u0005]:\u0006 \u0003נכנסה לרשות הבעל — הבעל צריך להביא ראיה.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 — \u0003דמייתי\u0004 \u0005[שמביא]\u0006 \u0003הבעל ראיה, הא\u0004 \u0005[הרי]\u0006 אם \u0003לא מייתי\u0004 \u0005[מביא]\u0006 \u0003הבעל ראיה — האב מהימן. אתאן\u0004 \u0005[הגענו]\u0006 איפוא \u0003ל\u0004שיטת \u0003רבן גמליאל\u0004 ש\u0003אמר\u0004 שהאשה \u0003נאמנת\u0004 לומר שאירע בה הפגם לאחר האירוסין. ואם כן יש סתירה בין תחילתה וסופה של המשנה! \u0003אמר ר' אלעזר: תברא\u0004 \u0005[שבורה]\u0006 היא המשנה, כלומר, אינה לפי שיטה אחת, ו\u0003מי ששנה זו\u0004 (את תחילתה) \u0003לא שנה זו\u0004 (את סופה).","\u0003אמר רבא: לא תימא\u0004 \u0005[אל תאמר]\u0006 ש\u0003ר' יהושע לא אזיל בתר\u0004 \u0005[אינו הולך אחר]\u0006 \u0003חזקה דגופא\u0004 \u0005[של הגוף,\u0006 חזקת הגוף\u0005]\u0006 \u0003כלל,\u0004 שלדעתו אין סומכים כלל על החזקה שהגוף נשאר במקומו ובשלימותו כבתחילה, ומשום כך סבור שם שאינה נאמנת לטעון \"משנתארסתי נאנסתי\", \u0003אלא\u0004 כך צריך לומר: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא אזיל\u0004 \u0005[הולך]\u0006 \u0003ר' יהושע בתר חזקה דגופא\u0004 \u0005[של הגוף],\u0006 זהו רק \u0003היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 \u0003חזקה דממונא\u0004 \u0005[של ממון]\u0006 שעומדת כנגד חזקת הגוף, כגון שם שבאה האשה להוציא ממון מן הבעל בתשלום הכתובה בטענה שנאנסה אחרי האירוסין ומגיעה לה כתובה כבתולה, שכיון שצריך להוציא ממון סבור הוא שאין חזקת הגוף בלבד מועילה כדי להוציא ממון.","\u0003אבל היכא דליכא\u0004 \u0005[במקום שאין]\u0006 \u0003חזקה דממונא\u0004 \u0005[של ממון],\u0006 כגון במשנה שלנו — \u0003אזיל\u0004 \u0005[הולך]\u0006 \u0003ר' יהושע בתר\u0004 \u0005[אחר]\u0006 \u0003חזקה דגופא\u0004 \u0005[של הגוף].\u0006 וראיה לדבר — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בדיני צרעת: \u0003אם\u0004 נגע ה\u0003בהרת\u0004 היה \u0003קודם לשער לבן —\u0004 הרי זה נגע \u0003טמא,\u0004 ו\u0003אם שער לבן\u0004 היה \u0003קודם לבהרת\u0004 — הרי זה נגע \u0003טהור,\u0004 ואם היה \u0003ספק,\u0004 שאין יודעים מה קדם — \u0003טמא. ור' יהושע אומר: כהה.\u0004 ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש הלשון\u0005]\u0006 \u0003\"כהה\"? אמר רבה: \"כהה\"\u0004 כוונתו \u0003טהור.\u0004 כאילו היה צבע הנגע כהה, שאינו טמא. הרי שמספק מעמידים את הגוף על חזקתו, וטהור.","\u0003רבא אמר:\u0004 את הסתירה במשנתנו אפשר לתרץ באופן אחר: \u0003רישא\u0004 \u0005[\u0006ב\u0005תחילתה]\u0006 ההנחה היא שכיון ש\u0003כאן נמצאו ו\u0004נודעו — \u0003כאן\u0004 גם \u0003היו\u0004 (נולדו, נוצרו). שכיון שנמצאו בה מומים בעודה בבית אביה יש להניח שהמומים הללו היו בה עוד קודם, ולכן האב צריך להביא ראיה שאחרי שנתארסה נולד בה המום. ו\u0003סיפא נמי\u0004 \u0005[\u0006ב\u0005סופה גם כן],\u0006 כיון שנמצאו המומים בבית הבעל, מניחים ש\u0003כאן נמצאו וכאן היו\u0004 ברשות הבעל, לאחר שנישאת, ולא קודם לכן.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 ממה ששנינו: \u0003נכנסה לרשות הבעל — הבעל צריך להביא ראיה שעד שלא תתארס\u0004 (התארסה) \u0003היו בה מומין אלו, והיה מקחו מקח טעות.\u0004 ונדייק: אם הביא ראיה שהיו בה \u0003עד שלא תתארס — אין\u0004 \u0005[כן],\u0006 אבל אם הביא ראיה שנמצאו המומים \u0003משתתארס — לא\u0004 נאמן, ואף על פי שהיתה עדיין בבית אביה, \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 שאף כי אין בידו ראיה אלא מזמן האירוסין והלאה \u0003לימא\u0004 \u0005[נאמר]:\u0006 \u0003כאן נמצאו וכאן היו,\u0004 ומן הסתם היו בה מומים אלה עוד בבית אביה, קודם האירוסין!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003משנתארסה\u0004 יש טעם אחר שאין מניחים שהיו בה מומים קודם, והוא: \u0003משום דאיכא למימר\u0004 \u0005[שיש\u0006 מקום \u0005לומר]:\u0006 \u0003חזקה אין אדם שותה בכוס אלא אם כן בודקו\u0004 לפני כן. כלומר, שאין אדם מארס אשה אלא אם כן בודקה תחילה אם אין בה מומים. \u0003והאי\u0004 \u0005[וזה]\u0006 בודאי \u0003ראה\u0004 שיש בה מומים \u0003וניפייס\u0004 \u0005[והתפייס]\u0006 \u0003הוא.\u0004 ואף שייתכן שהיו בה מומים קודם, כיון שנתארסה — חזקה שידע מהם והסכים.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שהביא ראיה שהיו בה מומים, אם כן \u0003עד שלא תתארס נמי\u0004 \u0005[גם כן]\u0006 היינו צריכים לסמוך על חזקה זו ולומר שלפני האירוסין ראה את מומיה וקיבל על עצמו! \u0003אלא אמרינן\u0004 \u0005[אומרים אנו]\u0006 שכנגד חזקה זו יש \u0003חזקה אין אדם מיפייס\u0004 \u0005[מתפייס]\u0006 \u0003במומין\u0004 וצריך להביא ראיה שראה והסכים. \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 לאחר האירוסין, \u0003חזקה אין אדם מיפייס\u0004 \u0005[מתפייס]\u0006 \u0003במומין!\u0004","\u0003אלא\u0004 צריך לפרש בצורה אחרת: אם הביא ראיה שהיו בה מומים \u0003משנתארסה,\u0004 אין סומכים על דבריו שכבר נולדו בה עוד לפני כן, \u0003משום דאיכא תרתי\u0004 \u0005[שיש שתי]\u0006 חזקות כנגדו: אחת — \u0003חזקה העמד הגוף על חזקתו\u0004 שלא היו בה מומים עד האירוסין, \u0003ו\u0004השניה — \u0003חזקה אין אדם שותה בכוס אלא אם כן בודקו, והאי\u0004 \u0005[וזה]\u0006 ודאי \u0003ראה\u0004 והכיר במומיה \u0003וניפייס\u0004 \u0005[והתפייס]\u0006 \u0003הוא. מאי אמרת\u0004 \u0005[מה אתה אומר]\u0006 כנגד זה — שיש \u0003חזקה\u0004 ש\u0003אין אדם מיפייס\u0004 \u0005[מתפייס]\u0006 \u0003במומין\u0004 — אם כן \u0003הוי\u0004 \u0005[\u0006הרי \u0005יש]\u0006"],["\u0003חדא\u0004 \u0005[\u0006חזקה \u0005אחת]\u0006 \u0003במקום תרתי\u0004 \u0005[שתיים]\u0006 שעומדות כנגדה, \u0003וחדא במקום תרתי לא אמרינן\u0004 \u0005[ואחת\u0006 שתקבע \u0005במקום שתיים אין אנו אומרים].\u0006 אבל אם הביא הבעל ראיה ש\u0003עד שלא תתארס\u0004 (נתארסה) היו בה כבר מומים — \u0003העמד הגוף על חזקתו לא איכא למימר\u0004 \u0005[אין לומר];\u0006 כי \u0003מאי איכא\u0004 \u0005[מה יש]\u0006 כאן לטובת האשה? רק \u0003חזקה\u0004 ש\u0003אין אדם שותה בכוס אלא אם כן בודקו, והאי\u0004 \u0005[וזה,\u0006 הבעל\u0005]\u0006 \u0003ראה וניפייס\u0004 \u0005[והתפייס]\u0006 \u0003הוא\u0004 — אם כן אפשר לומר \u0003אדרבה\u0004 (להיפך): \u0003חזקה אין אדם מיפייס\u0004 \u0005[מתפייס]\u0006 \u0003במומין, ו\u0004ממילא \u0003העמד ממון על חזקתו\u0004 ולא נחייב את הבעל בכתובתה.","\u0003רב אשי אמר:\u0004 את הסתירה בין ראשה וסופה של המשנה אפשר ליישב כך: \u0003רישא\u0004 \u0005[\u0006ב\u0005ראשה]\u0006 הרי זה כמקרה של טענה שמישהו טוען לחבירו: \u0003\"מנה לאבא\u0004 (של אבא) נמצא \u0003בידך\u0004 ואתה חייב לשלם לו \u0003\",\u0004 שהרי באותה שעה כאשר נמצאו המומים עדיין לא נשאה, וכסף כתובתה אינו בא לידי האשה אלא לידי אביה. \u0003וסיפא\u0004 \u0005[ו\u0006ב\u0005סוף]\u0006 מדובר כשנישאת שאז כסף הכתובה מגיע לה, והרי זו כאילו טוענת \u0003\"מנה לי בידך\"\u0004 וחזקת גופו של אדם מסייעת רק לו להוציא ממון מחבירו, ולא לאדם אחר.","\u0003איתיביה\u0004 \u0005[הקשה\u0006 לו\u0005]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא לרב אשי\u0004 ממה ששנינו בברייתא: \u0003מודה ר' מאיר במומין הראויין לבא עמה מבית אביה,\u0004 שאינם נראים כמומים חדשים שנוצרו לאחר הנישואין, \u0003שעל האב להביא ראיה\u0004 שלא היו בה קודם ואף על פי שכבר נישאה. \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 הוא מודה? הלא \u0003\"מנה לי בידך\" הוא\u0004 בצירוף חזקת הגוף, ועל הבעל להביא ראיה!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003ב\u0004שיש לה אצבע \u0003יתירת\u0004 (נוספת) ברגלה שודאי הוא מום מלידה. ותוהים: אם מדובר באצבע \u0003יתירת, מאי\u0004 \u0005[מה]\u0006 \u0003ראיה מייתי\u0004 \u0005[מביא]\u0006 האב, וכי יכול לומר שצמחה בה אצבע זו לאחר האירוסין? ומשיבים: האב מביא \u0003ראיה\u0004 שהבעל \u0003ראה\u0004 אצבע יתירה זו \u0003וניפייס\u0004 \u0005[והתפייס]\u0006 \u0003הוא.\u0004","\u0003אמר רב יהודה אמר שמואל: המחליף פרה בחמור\u0004 שלא היו במקום אחד, אלא שאחד האנשים משך בהמה אחת ונקנית השניה לחבירו בקנין חליפין על ידי משיכה זו, \u0003ומשך בעל החמור את הפרה, ולא הספיק\u0004 גם \u0003בעל הפרה למשוך את החמור, עד שמת החמור.\u0004 וטוען בעל הפרה שהחמור מת עוד לפני משיכת הפרה כשהוא עדיין ברשות בעליו הראשון ואם כן לא חל כאן קנין חליפין כלל — במקרה כזה \u0003על בעל החמור להביא ראיה שהיה חמורו קיים בשעת משיכת פרה,\u0004 ואם אינו יכול להביא ראיה — הפרה נשארת ברשות בעליה.","ומוסיף רב יהודה: \u0003ותנא תונא\u0004 \u0005[ושנה התנא שלנו]\u0006 ורמז הלכה זו ממש בדין \u0003כלה,\u0004 שמשם למד שמואל הלכה זו לענין קנין חליפין. ומבררים: \u0003הי\u0004 \u0005[איזו]\u0006 \u0003כלה,\u0004 כלומר, מאיזו הלכה בכלה מביא שמואל ראיה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006"],["\u0003כלה בבית אביה\u0004 שצריך האב להביא ראיה לדבריו, \u0003מי דמי\u0004 \u0005[האם דומה]\u0006 הדבר לענין החליפין? הרי \u0003התם\u0004 \u0005[שם] —\u0006 \u0003מייתי\u0004 \u0005[מביא]\u0006 ה\u0003אב ראיה ומפיק\u0004 \u0005[ומוציא]\u0006 כסף מן הבעל, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 במחליף פרה בחמור — הלא \u0003מייתי\u0004 \u0005[מביא]\u0006 \u0003בעל החמור ראיה ומוקים\u0004 \u0005[ומעמיד,\u0006 משאיר\u0005]\u0006 את הפרה ברשותו, ואולי במצב כזה אינו צריך להביא ראיה.","\u0003אמר ר' אבא:\u0004 הראיה היא מדין \u0003כלה בבית חמיה,\u0004 כלומר, שנכנסה לרשות הבעל. ומקשים: \u0003ואכתי לא דמי\u0004 \u0005[ועדיין אינו דומה],\u0006 כי \u0003התם\u0004 \u0005[שם]\u0006 — ה\u0003בעל מייתי\u0004 \u0005[מביא]\u0006 \u0003ראיה ומרע ליה לחזקיה\u0004 \u0005[את חזקתו]\u0006 של ה\u0003אב\u0004 (חזקת הגוף של הבת), ואילו \u0003הכא\u0004 \u0005[כאן] —\u0006 \u0003בעל החמור מייתי\u0004 \u0005[מביא]\u0006 \u0003ראיה ומוקים חזקיה בידיה\u0004 \u0005[ומעמיד\u0006 את \u0005החזקה,\u0006 חזקת הגוף של החמור, \u0005בידו],\u0006 ואם כן ייתכן שאינו צריך להביא ראיה.","\u0003אמר רב נחמן בר יצחק:\u0004 ראייתו של שמואל היא מדין \u0003כלה בבית אביה, ו\u0004לא מענין הכתובה אלא \u0003ל\u0004ענין כסף ה\u0003קדושין.\u0004 שצריך האב להביא ראיה כדי שישאר כסף הקידושין בידו.","\u0003ולא תימא אליבא דמאן דאמר\u0004 \u0005[ואל תאמר\u0006 שמדובר \u0005לפי שיטת מי שאומר]\u0006 בכלל כי \u0003קדושין לאו\u0004 \u0005[לא]\u0006 \u0003לטיבועין\u0004 (לטביעה, לאיבוד) \u0003ניתנו,\u0004 שכסף זה ניתן רק לצורך הקידושין, ואם הקידושין בטלים צריכה להחזיר את הכסף. \u0003אלא אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003קדושין לטיבועין ניתנו,\u0004 שכסף הקידושין שניתן לאשה שייך לה בכל מקרה — \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים ב\u0003קידושי ודאי,\u0004 שאפילו אם אחר כך מגרש אותה או מת אינה צריכה להחזיר את כסף הקידושין, \u0003אבל קידושי טעות, אי מייתי\u0004 \u0005[אם מביא]\u0006 האב \u0003ראיה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מחזיק האב בכסף, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא — לא.\u0004 ומכאן ראיה לשיטת שמואל, שבמקרה של ספק צריך להביא ראיה כדי להשאיר בידו את הכסף שמחזיק.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטת שמואל בדיני חזקה מענין אחר, ששנינו: \u0003מחט שנמצאת\u0004 (נמצאה) \u0003בעובי בית הכוסות\u0004 שבקיבת הבהמה, אם היתה המחט נעוצה רק \u0003מצד אחד\u0004 של בית הכוסות — הרי הבהמה \u0003כשרה.\u0004 ואם היתה \u0003משני צדדין,\u0004 שהיה הנקב מפולש ועובר את כל עובי הדופן — הרי זו \u0003טרפה.\u0004 ועוד: אם \u0003נמצא עליה\u0004 על המחט \u0003קורט\u0004 (משהו) \u0003דם\u0004 קרוש — \u0003בידוע שהוא,\u0004 הנקב, נעשה \u0003לפני שחיטה\u0004 והריהי טריפה, \u0003לא נמצא עליה קורט דם — בידוע שהוא לאחר שחיטה\u0004 וכשירה.","\u0003הוגלד פי המכה\u0004 (הפצע) באותו מקום — \u0003בידוע ששלשה ימים קודם שחיטה\u0004 אירע הדבר, ואם נמכרה הבהמה לאחר מכן יכול הקונה לטעון שהיה זה מיקח טעות, שלא רצה לקנות טריפה. \u0003לא הוגלד פי המכה\u0004 והמוכר טוען שהבהמה נפצעה ברשות הקונה־הטבח, והקונה־הטבח טוען שברשות המוכר נפצעה — \u0003המוציא מחבירו עליו הראיה. ו\u0004לפי כלל זה \u0003אי יהיב\u0004 \u0005[ואם נתן]\u0006 ה\u0003טבח\u0004 כבר \u0003דמי\u0004 \u0005[\u0006את \u0005הכסף]\u0006 — \u0003בעי לאיתויי\u0004 \u0005[צריך להביא]\u0006 \u0003ראיה ומפיק\u0004 \u0005[ומוציא]\u0006 את הכסף מיד המוכר.","ולשיטת שמואל: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 נאמר כך? ש\u0003בעל\u0004 ה\u0003בהמה,\u0004 המוכר, \u0003לייתי\u0004 \u0005[יביא]\u0006 \u0003ראיה ונוקים\u0004 \u0005[ויעמיד]\u0006 את המיקח במקומו כשם שבעל החמור צריך להביא ראיה כדי להשאיר את הפרה ברשותו, ומדוע תהיה חובת הראיה על הטבח?","ומשיבים: שם מדובר בש\u0003לא יהיב\u0004 \u0005[נתן]\u0006 \u0003טבחא דמי\u0004 \u0005[הטבח את הכסף]\u0006 אלא סמך עליו שישלם אחר כך, ובעל הבהמה הוא התובע מן הטבח, והוא הצריך להביא ראיה כדי לקיים את המיקח. ושואלים: \u0003מאי פסקא\u0004 \u0005[מה פסקת]\u0006 שמדובר דווקא במקרה כזה? שמלשון המשנה משמע שכל צד מביא ראיה ונוטל.","\u0003אלא\u0004 מכאן יש לדחות את דברי שמואל, ואכן \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רמי בר יחזקאל\u0004 מארץ ישראל לבבל, \u0003אמר: לא תצייתינהו להני כללי דכייל\u0004 \u0005[אל תצייתו\u0006 תשמעו \u0005לאותם כללים שכלל]\u0006 \u0003יהודה אחי משמיה\u0004 \u0005[משמו]\u0006 של \u0003שמואל.\u0004 אלא \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל: כל שנולד ספק ברשותו — עליו הראיה\u0004 ובמקרה זה על בעל הפרה להביא ראיה. \u0003ותנא תונא\u0004 \u0005[והתנא שלנו שנאה]\u0006 לדין זה ב\u0003כלה,\u0004 שאם היתה הכלה ברשות האב — על האב להביא ראיה, ואם הכלה ברשות הבעל — על הבעל להביא ראיה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003מחט שנמצאת בעובי בית הכוסות כו'\u0004 המוציא מחבירו עליו הראיה, \u0003ואי\u0004 \u0005[ואם]\u0006 עדיין \u0003לא יהיב\u0004 \u0005[נתן]\u0006 ה\u0003טבח דמי\u0004 \u0005[כסף]\u0006 \u0003בעל בהמה בעי לאיתויי\u0004 \u0005[צריך להביא]\u0006 \u0003ראיה ומפיק\u0004 \u0005[ומוציא\u0006 את הכסף\u0005],\u0006 \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 הלא \u0003ספיקא\u0004 \u0005[ספק]\u0006 זה \u0003ברשות\u0004 ה\u0003טבח איתייליד\u0004 \u0005[נולד],\u0006 ולפי דברי רמי בר יחזקאל צריך הוא להביא ראיה!","ומשיבים: מדובר שם באופן \u0003דיהיב\u0004 \u0005[שנתן]\u0006 ה\u0003טבח\u0004 כבר \u0003דמי\u0004 \u0005[כסף],\u0006 וכיון שהטבח רוצה להוציא את הכסף מיד בעל הבהמה, עליו להביא ראיה. ושואלים: \u0003ומאי פסקא\u0004 \u0005[ומה פסקת],\u0006 מניין לחלק בדברי התנא שמדובר דווקא במקרה זה? ומשיבים: \u0003סתמא דמילתא\u0004 \u0005[סתמו של דבר]\u0006 וכך מנהג העולם, כל \u0003כמה דלא יהיב איניש זוזי\u0004 \u0005[שאין אדם נותן זוזים,\u0006 כסף\u0005] —\u0006 \u0003לא יהיב\u0004 \u0005[נותן]\u0006 \u0003איניש חיותא\u0004 \u0005[איש\u0006 אחר את \u0005הבהמה]\u0006 לשחיטה, ולכן מן הסתם כבר שילם הטבח קודם השחיטה והוא התובע כספו בחזרה.","שנינו במשנה, \u0003וחכמים אומרים: במה דברים אמורים\u0004 שהבעל יכול לטעון על המומים ולומר שלא ידע עליהם בשעה שקידשה — \u0003במומין שבסתר,\u0004 אבל לא על מומים שבגלוי. \u0003אמר רב נחמן:\u0004"],["\u0003ונכפה\u0004 (חולה בחולי נפילה) — \u0003כמומין שבסתר דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 שייתכן שתהא נכפה ולא ידעו אחרים על כך. ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים רק באופן \u0003דקביע ליה\u0004 \u0005[שקבוע לו]\u0006 לחולי \u0003זמן,\u0004 שהתקף המחלה בא בזמנים קבועים, ולכן יכולים האשה ובני משפחתה להסתיר את העובדה שהיא חולה במחלה זו, \u0003אבל\u0004 אם \u0003לא קביע ליה\u0004 \u0005[קבוע לו]\u0006 זמן, אלא עשוי ההתקף לקרות בכל עת — \u0003כמומין שבגלוי דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 שלא ייתכן שהדבר לא יוודע לאחרים.","\u0003האיש שנולדו בו מומין\u0004 לאחר הנישואין — \u0003אין כופין אותו להוציא\u0004 (לגרש) את אשתו. \u0003אמר רבן שמעון בן גמליאל: במה דברים אמורים — במומין הקטנים,\u0004 שבכגון זה אין האיש חייב להוציא, \u0003אבל במומין הגדולים\u0004 אשר יבוארו בגמרא — \u0003כופין אותו להוציא.\u0004","\u0003רב יהודה תני\u0004 \u0005[שנה]\u0006 כאן, כגרסתנו: האיש ש\u0003נולדו\u0004 בו מומים לאחר שנשא אשה. ואילו \u0003חייא בר רב תני\u0004 \u0005[שנה]:\u0006 האיש ש\u0003היו\u0004 בו מומים עוד לפני שנשא אשה. ומסבירים את שיטותיהם: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 וגורס \u0003\"נולדו\u0004 בו מומים אין כופין אותו להוציא\u0003\"\u0004 —\u0003 כל שכן\u0004 שהוא הדין במקום ש\u0003היו\u0004 בו מומים. ומדוע — \u0003דקסברה\u0004 \u0005[שסברה]\u0006 \u0003וקיבלה\u0004 על עצמה מומים אלה כשהסכימה להינשא לו. אבל \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהגירסה היא \u0003\"היו\u0004 בו מומים\u0003\"\u0004 — דווקא בזה אין כופים אותו להוציא, \u0003אבל\u0004 אם \u0003נולדו\u0004 בו מומים לאחר הנישואין — \u0003לא,\u0004 מפני שעל דעת כן לא נישאה לו.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005],\u0006 \u0003אמר רבן שמעון בן גמליאל: במה דברים אמורים — במומין קטנים, אבל במומין גדולים — כופין אותו להוציא.\u0004 ושואלים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר\u0006 וגורס\u0005]\u0006 \u0003\"נולדו\" — היינו דשאני\u0004 \u0005[זהו ששונה\u0006 שיש הבדל\u0005]\u0006 \u0003בין\u0004 מומים \u0003גדולים לקטנים,\u0004 שרק מומים גדולים מבטלים את הנישואין. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר\u0006 וגורס\u0005]\u0006 \u0003\"היו\",\u0004 אם כן \u0003מה לי גדולים מה לי קטנים? הא\u0004 \u0005[הרי]\u0006 \u0003סברה וקיבלה\u0004 על עצמה את מומיו אלה, ומדוע במומים גדולים כופים אותו להוציא?","ומשיבים: אם היו אלה מומים גדולים יכולה היא לטעון ש\u0003כסבורה היא\u0004 שחשבה תחילה \u0003שיכולה לקבל\u0004 על עצמה, \u0003ועכשיו\u0004 שנישאה לו היא מגלה ש\u0003אין\u0004 היא \u0003יכולה לקבל.\u0004 ומבררים: \u0003ואלו הן מומין גדולים? פירש רבן שמעון בן גמליאל: כגון ניסמית\u0004 (נתעוורה) \u0003עינו,\u0004 או ש\u0003נקטעה ידו,\u0004 או ש\u0003נשברה רגלו.\u0004","\u0003אתמר\u0004 \u0005[נאמר],\u0006 \u0003ר' אבא בר יעקב אמר\u0004 בשם \u0003ר' יוחנן: הלכה כרבן שמעון בן גמליאל\u0004 שיש לחלק בענין זה בין מומים גדולים לקטנים. \u0003רבא אמר\u0004 בשם \u0003רב נחמן: הלכה כדברי חכמים\u0004 שאינם מחלקים בזה.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]\u0006 ופסק כי הלכה כרבן שמעון בן גמליאל? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רבה בר בר חנה אמר ר' יוחנן: בכל מקום ששנה רבן שמעון בן גמליאל במשנתנו — הלכה כמותו, חוץ מ\u0004שלושה דינים: בדין \u0003ערב, ו\u0004בדין שאמר ב\u0003צידן, ו\u0004מחלוקותיו עם חכמים בדיני \u0003ראיה\u0004 שאין הלכה כמותו ב\u0003אחרונה\u0004 שביניהן. ואם פוסק ר' יוחנן בכלל שהלכה כרבן שמעון בן גמליאל, לא היה צריך לפסוק הלכה מיוחדת במשנתנו. ומשיבים: \u0003אמוראי נינהו ואליבא\u0004 \u0005[\u0006מחלוקת \u0005אמוראים היא ולפי שיטת]\u0006 \u0003ר' יוחנן,\u0004 שלדעת ר' אבא בר יעקב לא קבע ר' יוחנן הלכה כללית, אלא פסק הלכה בכל מקום ומקום לעניינו.","\u0003ואלו\u0004 פגמים \u0003ש\u0004בגללם \u0003כופין אותו,\u0004 את הבעל, \u0003להוציא\u0004 (לגרש) את אשתו: אם היה \u0003מוכה שחין,\u0004 או שהיה \u0003בעל פוליפוס, ו\u0004כן \u0003המקמץ, והמצרף נחושת, והבורסי\u0004 (מעבד עורות שריחם רע). \u0003בין שהיו\u0004 בו פגמים אלו \u0003עד שלא\u0004 (לפני) ש\u0003נישאו ובין\u0004 אם \u0003משנישאו נולדו. ועל כולן אמר ר' מאיר: אף על פי שהתנה עמה\u0004 מראש שמלאכתו בכך או שיש בו מום זה, \u0003יכולה היא שתאמר: \"סבורה הייתי\u0004 לפני הנישואין \u0003שאני יכולה לקבל\u0004 ולהיות נשואה לו באופן זה, \u0003ו\u0004אולם \u0003עכשיו\u0004 עכשיו אני מגלה ש\u0003איני יכולה לקבל\".\u0004","\u0003וחכמים אומרים: מקבלת היא על כרחה\u0004 אם הסכימה לכך מראש, \u0003חוץ ממוכה שחין, מפני ש\u0004השחין \u0003ממקתו\u0004 (מרקיבה את בשרו). ועוד מספרים כתוספת: \u0003מעשה בצידון בבורסי אחד שמת\u0004 בלא בנים \u0003והיה לו אח בורסי\u0004 שהיה צריך לייבם את אשת האח שנפטר. \u0003אמרו חכמים: יכולה היא שתאמר \"לאחיך הייתי יכולה לקבל, ולך איני יכולה לקבל\",\u0004 ויצטרך לחלוץ לה.","נזכרו במשנה כמה מונחים בלתי ברורים ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"בעל פוליפוס\"? אמר רב יהודה אמר שמואל:\u0004 זה שיש לו \u0003ריח החוטם. במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 זה שיש לו \u0003ריח הפה. רב אסי מתני איפכא\u0004 \u0005[היה שונה להיפך]\u0006 ששמואל הוא הסבור שפוליפוס הוא ריח הפה. \u0003ומנח\u0004 \u0005[ונותן]\u0006 \u0003בה סימנא\u0004 \u0005[סימן]\u0006 לזכור שזו השיטה: \u0003שמואל לא פסיק פומיה\u0004 \u0005[פסק פיו]\u0006 \u0003מכוליה פירקין\u0004 \u0005[מכל פרקנו],\u0006 שעל ידי זה זוכרים שיש קשר בין פה לשמואל.","שנינו במשנה בין שאר המלאכות הבזויות בהן עוסק הבעל: \u0003\"והמקמץ\".\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מקמץ\"? אמר רב יהודה: זה המקבץ צואת כלבים\u0004 לצורך עיבוד עורות (בורסקאות). \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו בברייתא: \u0003\"מקמץ\" זה\u0004 עצמו \u0003בורסי!\u0004 ומשיבים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 \u0003תיקשי\u0004 \u0005[תקשה]\u0006 \u0003לך מתניתין\u0004 \u0005[משנתנו\u0006 עצמה\u0005]\u0006 שנאמר בה \u0003\"המקמץ והמצרף נחושת והבורסי\",\u0004 שמכאן רואים שהמקמץ והבורסי אינם אותה מלאכה!","ומסבירים: \u0003בשלמא מתניתין לא קשיא\u0004 \u0005[נניח משנתנו\u0006 עצמה \u0005אינה קשה],\u0006 שאפשר לומר כי \u0003כאן\u0004 שאמרו בורסי בנפרד ממקמץ, הרי זה \u0003בבורסי גדול,\u0004 שהוא עשיר ועוסק בעיבוד הרבה עורות, ואילו \u0003כאן\u0004 בברייתא שאמרו שמקמץ הוא בורסי, הרי זה \u0003בבורסי קטן,\u0004 שאינו מעבד אלא מעט עורות. \u0003אלא לרב יהודה קשיא\u0004 \u0005[קשה]!\u0006 ומשיבים: מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא\u0004 בזה, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"מקמץ\" זה בורסי, ויש אומרים: זה המקמץ\u0004 (מקבץ) \u0003צואת כלבים,\u0004 ור' יהודה סובר כאותם יש אומרים.","עוד שנינו במשנה בין אותן מלאכות: \u0003והמצרף נחושת והבורסי.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מצרף נחושת\"? רב אשי אמר: חשלי דודי\u0004 (המרדדים נחושת ועושים ממנה דודים), שעיסוקם בנחושת גורם להם לריח רע. \u0003רבה בר בר חנה אמר: זה המחתך\u0004 (חוצב) \u0003נחושת מעיקרו\u0004 מן האדמה. ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כמותו,\u0006 כשיטתו\u0005]\u0006 של \u0003רבה בר בר חנה: איזהו \"מצרף\"? זה המחתך נחושת מעיקרו.\u0004","כיון שהוזכרו במשנה מקרים בהם כופים את הבעל לגרש את אשתו, מביאים מקרה נוסף, \u0003אמר רב:\u0004 הבעל \u0003האומר \"איני זן ואיני מפרנס\u0004 את אשתי \u0003\"\u0004— \u0003יוציא\u0004 (יגרש) את אשתו, \u0003ויתן\u0004 לה \u0003כתובה. אזל\u0004 \u0005[הלך]\u0006 \u0003ר' אלעזר\u0004 ו\u0003אמרה לשמעתא קמיה\u0004 \u0005[להלכה\u0006 זו \u0005לפני]\u0006 \u0003שמואל. אמר\u0004 שמואל: \u0003אכסוה שערי\u0004 \u0005[האכילו שעורים]\u0006 \u0003לאלעזר\u0004 שהם מאכל בהמה, כלומר, דבר שטות אמר. כי, \u0003עד שכופין אותו להוציא\u0004 — מוטב ש\u0003יכפוהו לזון\u0004 את אשתו.","ושואלים: \u0003ורב\u0004 מה הוא משיב על כך? — לדעתו \u0003אין אדם דר עם נחש בכפיפה\u0004 (בסל) אחת, שאין אשה יכולה לשאת חיים משותפים עם בעל שזן אותה רק כשכופים אותו לכך בבית דין. מסופר: \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003ר' זירא\u0004 לארץ ישראל, \u0003אשכחיה\u0004 \u0005[מצאו]\u0006 \u0003לר' בנימין בר יפת דיתיב וקאמר לה\u0004 \u0005[שיושב ואומר אותה],\u0006 את ההלכה הזו של רב, \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003על דא אכסוה שערין\u0004 \u0005[על\u0006 דבר \u0005זה האכילו אותו שעורים]\u0006 \u0003לאלעזר בבבל.\u0004","ועוד בענין כפייה לגרש, \u0003אמר רב יהודה אמר רב אסי: אין מעשין\u0004 (כופים) את הבעל לגרש את אשתו — \u0003אלא לפסולות,\u0004 כאשר אדם נושא אשה הפסולה לו. \u0003כי אמריתה קמיה\u0004 \u0005[כאשר אמרתי אותה\u0006 הלכה \u0005לפני]\u0006 \u0003שמואל, אמר:\u0004 מה הן פסולות אלה — \u0003כגון אלמנה לכהן גדול,\u0004 או \u0003גרושה וחלוצה לכהן הדיוט,\u0004 או \u0003ממזרת\u0004 או \u0003נתינה\u0004 (מבנות הגבעונים) \u0003לישראל,\u0004 או \u0003בת ישראל\u0004 הנישאת \u0003לנתין ולממזר\u0004 — שבכל אלה יש איסור לא תעשה מן התורה. \u0003אבל\u0004 מי ש\u0003נשא אשה ושהה עמה עשר שנים ולא ילדה,\u0004 למרות שעובר עבירה בכך שאינו מקיים פריה ורביה — \u0003אין כופין אותו\u0004 לגרשה.","\u0003ורב תחליפא בר אבימי אמר\u0004 בשם \u0003שמואל: אפילו נשא אשה ושהה עמה עשר שנים ולא ילדה\u0004 — \u0003כופין אותו\u0004 לגרשה, שאף הוא עובר על מצות עשה כל עוד אינו מגרשה. ומבררים, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 \u0003אלו שכופין אותו להוציא: מוכה שחין ובעל פוליפוס.\u0004 ומעתה שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב אסי\u0004 אפשר לפרש כך: את אלה שכופים להוציא \u0003דרבנן קתני\u0004 \u0005[שמדברי סופרים שנה]\u0006 במשנה, ואלה \u0003דאורייתא\u0004 \u0005[שמן התורה],\u0006 כגון אלמנה לכהן גדול \u0003לא קתני\u0004 \u0005[שנה].\u0006 \u0003אלא לרב תחליפא בר אבימי, ליתני\u0004 \u0005[שישנה\u0006 במשנה גם כן\u0005]\u0006 \u0003נשא אשה ושהה עמה עשר שנים ולא ילדה — כופין אותו,\u0004 שהרי גם זה הוא מתקנת חכמים.","\u0003אמר רב נחמן: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמר רב תחליפא בר אבימי בשם שמואל שבשלא ילדה אשתו עשר שנים כופים אותו לגרשה, כפייה זו היא רק \u0003במילי\u0004 \u0005[במילים,\u0006 בדברים\u0005]\u0006 בלבד, שמדברים על לבו שיגרשה, ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאמר רב אסי שאין כופים אותו לגרשה הרי זה מדובר בכפיה בבית־דין \u0003בשוטי\u0004 \u0005[בשוטים].\u0006 \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' אבא:\u0004 וכי אפשר לקבוע דין כפיה במילים בלבד? והלא נאמר: \u0003\"בדברים לא יוסר עבד\"\u0004 (משלי כט, יט)! \u0003אלא אמר ר' אבא: הא והא\u0004 \u0005[זה וזה]\u0006 מדובר בכפיה \u0003בשוטי\u0004 \u0005[בשוטים],\u0006"],["\u0003התם\u0004 \u0005[שם]\u0006 במומים האמורים במשנתנו, \u0003כי אמרה \"הוינא בהדיה\"\u0004 \u0005[כאשר\u0006 היא \u0005אומרת\u0006 \"רוצה אני ש\u0005אהיה איתו\"]\u0006 — \u0003שבקינן\u0004 \u0005[מניחים אנו]\u0006 \u0003לה\u0004 ואין כופים אותו לגרשה. \u0003הכא, אף על גב דאמרה \"הוינא בהדיה\"\u0004 \u0005[כאן,\u0006 באשה שלא ילדה עשר שנים, \u0005אף על פי ש\u0006היא \u0005אומרת\u0006 \"רוצה אני ש\u0005אהיה איתו\"]\u0006 — \u0003לא שבקינן\u0004 \u0005[אין מניחים]\u0006 \u0003לה,\u0004 מפני שאין בעלה מקיים מצות פריה ורביה. ומקשים: \u0003והרי מוכה שחין דאף על גב דאמרה \"הוינא בהדיה\"\u0004 \u0005[שאף על פי ש\u0006היא \u0005אומרת\u0006 \"רוצה אני ש\u0005אהיה איתו\"]\u0006 — \u0003לא שבקינן\u0004 \u0005[אין מניחים]\u0006 \u0003לה. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003חוץ ממוכה שחין, מפני ש\u0004השחין \u0003ממקתו\u0004 (מרקיבה את בשרו). \u0003וקתני\u0004 \u0005[ושנה\u0006 אותה\u0005]\u0006 במשנה זו, ומשמע שלא זה הטעם! ומסבירים: בכל זאת יש לחלק ביניהם; \u0003התם כי אמרה \"דיירנא בהדיה בסהדי\"\u0004 \u0005[שם\u0006 במוכה שחין \u0005כאשר\u0006 היא \u0005אומרת\u0006 \"מוכנה אני \u0005לדור איתו בעדים\"],\u0006 שלא אתייחד עימו אבל אשאר אשתו — \u0003שבקינן\u0004 \u0005[מניחים אנו]\u0006 \u0003לה. הכא אף על גב דאמרה \"דיירנא בהדיה בסהדי\"\u0004 \u0005[כאן אף על פי ש\u0006היא \u0005אומרת \"אגור איתו בעדים\"]\u0006 — \u0003לא שבקינן\u0004 \u0005[אין אנו מניחים]\u0006 \u0003לה,\u0004 אלא כופים אותו לגרשה.","","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יוסי: שח לי זקן אחד מאנשי ירושלים: עשרים וארבעה\u0004 סוגים של \u0003מוכי שחין הן, וכולן אמרו חכמים\u0004 שה\u0003תשמיש קשה להן, ו\u0004סוג מוכי השחין הנקראים \u0003בעלי ראתן — קשה מכולן.\u0004 ושואלים: \u0003ממאי הוי\u0004 \u0005[ממה נעשה]\u0006 מום זה? ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מי ש\u0003הקיז דם ושימש\u0004 מיטתו מיד אחרי כן — \u0003הויין לו בנים ויתיקין\u0004 \u0005[יהיו לו בנים חלושים].\u0006 אם \u0003הקיזו שניהם\u0004 הבעל והאשה \u0003ושימשו\u0004 מיטתם מיד אחרי כן — \u0003הויין\u0004 \u0005[יהיו]\u0006 \u0003לו בנים בעלי ראתן. אמר רב פפא\u0004 על כך: \u0003לא אמרן\u0004 \u0005[אמרנו\u0006 דבר זה\u0005]\u0006 \u0003אלא\u0004 כש\u0003לא טעים מידי\u0004 \u0005[טעם דבר]\u0006 בין הקזת הדם והתשמיש, \u0003אבל\u0004 אם \u0003טעים מידי\u0004 \u0005[טעם דבר]\u0006 — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה,\u0004 שאין הדבר מזיק.","ושואלים: \u0003מאי סימניה\u0004 \u0005[מה סימניו]\u0006 של בעל ראתן? \u0003דלפן עיניה, ודייבי נחיריה, ואיתי ליה רירא מפומיה, ורמו דידבי עילויה\u0004 \u0005[דולפות עיניו, וזבים נחיריו, ויוצא לו ריר מפיו, ונחים זבובים עליו].\u0006 ושואלים: \u0003ומאי אסותיה\u0004 \u0005[ומה רפואתו]\u0006 של בעל ראתן? \u0003אמר אביי:\u0004 לוקחים \u0003פילא, ולודנא, גירדא דאגוזא, וגירדא דאשפא, וכליל מלכא, ומתחלא דדיקלא סומקא\u0004 \u0005[מיני עשבים, וקליפה מגוררת של אגוז, ו\u0006מה \u0005שגוררים מן העור, וכליל מלכא, ו\u0006את \u0005המתחל של דקל אדום].\u0006 \u0003ושליק להו בהדי הדדי, ומעייל ליה לביתא דשישא\u0004 \u0005[ומבשל אותם זה עם זה, ומכניס אותו\u0006 את האיש \u0005לבית של שיש]\u0006 שהוא אטום לגמרי. \u0003ואי לא איכא ביתא דשישא\u0004 \u0005[ואם אין בית של שיש] —\u0006 \u0003מעייל ליה לביתא דשב לבני ואריחא\u0004 \u0005[יכניס אותו לבית\u0006 שקירותיו בנויים בעובי \u0005שבע לבנים ואריח],\u0006","\u0003ונטיל ליה תלת מאה כסי על רישיה, עד דרפיא ארעיתא דמוחיה\u0004 \u0005[ושופך לו שלוש מאות כוסות\u0006 ממשקה זה \u0005על ראשו, עד שתתרפה גולגולת מוחו],\u0006 \u0003וקרע למוחיה ומייתי ארבע טרפי דאסא\u0004 \u0005[וקורע את מוחו ,\u0006 כלומר, את גולגלתו, \u0005ומביא ארבעה עלי הדס]\u0006 \u0003ומדלי כל חד כרעא ומותיב חד, ושקיל בצבתא וקלי ליה\u0004 \u0005[ומרים כל\u0006 פעם \u0005רגל אחת\u0006 של השרץ הנמצא שם \u0005ומניח\u0006 כל פעם עלה \u0005אחד\u0006 תחת רגל השרץ, \u0005ו\u0006אחר כך \u0005לוקח\u0006 אותו \u0005בצבת ושורף אותו].\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא\u0004 שורף אותו — \u0003הדר עילויה\u0004 \u0005[יחזור\u0006 השרץ \u0005עליו].\u0006 היה \u0003מכריז ר' יוחנן: הזהרו מזבובי של\u0004 (הנמצאים על) \u0003בעלי ראתן\u0004 שהם מעבירים את המחלה. \u0003ר' זירא לא הוה יתיב\u0004 \u0005[היה יושב]\u0006 \u0003בזיקיה\u0004 \u0005[ב\u0006מקום שנושבת בו \u0005רוח\u0006 מכיוון בעל ראתן\u0005].\u0006 \u0003ר' אלעזר לא עייל\u0004 \u0005[היה נכנס]\u0006 \u0003באהליה\u0004 \u0005[באהלו].\u0006 \u0003ר' אמי ור' אסי לא הוו אכלי\u0004 \u0005[היו אוכלים]\u0006 \u0003מביעי דההוא מבואה\u0004 \u0005[ביצים מאותו מבוי]\u0006 שגר בו בעל ראתן. ואילו \u0003ר' יהושע בן לוי מיכרך בהו ועסיק\u0004 \u0005[\u0006היה \u0005נכרך,\u0006 כלומר, נדבק \u0005בהם ועוסק]\u0006 \u0003בתורה. אמר,\u0004 נאמר על התורה: \u0003\"אילת אהבים ויעלת חן\"\u0004 (משלי ה, יט), \u0003אם חן מעלה על לומדיה — וכי אגוני לא מגנא\u0004 \u0005[אינה מגינה\u0006 עליהם\u0005]\u0006 מפני הפורענות?","","\u0003כי הוה שכיב\u0004 \u0005[כאשר נפטר]\u0006 ר' יהושע בן לוי, \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003למלאך המות: זיל, עביד ליה רעותיה\u0004 \u0005[לך, עשה לו\u0006 את \u0005רצונו]\u0006 שהוא צדיק גדול וצריכים לעשות את רצונו, שימות באופן הנוח לו. \u0003אזל איתחזי ליה\u0004 \u0005[הלך\u0006 מלאך המות ו\u0005נראה לו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהושע בן לוי למלאך המות: \u0003אחוי\u0004 \u0005[הראה]\u0006 \u0003לי דוכתאי\u0004 \u0005[\u0006את \u0005מקומי]\u0006 בגן עדן. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לחיי\u0004 \u0005[בסדר].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהושע בן לוי למלאך: \u0003הב\u0004 (תן) \u0003לי\u0004 את \u0003סכינך\u0004 שבו אתה הורג, \u0003דלמא מבעתת לי באורחא\u0004 \u0005[שמא תפחיד אותי בדרך].\u0006 \u0003יהבה נהליה\u0004 \u0005[נתנה לו].\u0006 \u0003כי מטא להתם דלייה\u0004 \u0005[כאשר הגיע לשם\u0006 לגן עדן \u0005הרים אותו\u0006 את ר' יהושע\u0005]\u0006 להראות לו את המקום, \u0003קא מחוי ליה\u0004 \u0005[\u0006ו\u0005הראה לו].\u0006 \u0003שוור נפל לההוא גיסא\u0004 \u0005[קפץ\u0006 ר' יהושע ו\u0005נפל לאותו צד]\u0006 לתוך גן העדן.","\u0003נקטיה בקרנא דגלימיה\u0004 \u0005[תפס אותו\u0006 מלאך המות \u0005בכנף של בגדו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהושע בן לוי: \u0003בשבועתא דלא אתינא\u0004 \u0005[בשבועה,\u0006 אני נשבע, \u0005שאינני בא\u0006 אליך\u0005].\u0006 \u0003אמר קודשא בריך הוא\u0004 (הקדוש ברוך הוא): \u0003אי איתשיל אשבועתא\u0004 \u0005[אם\u0006 בחייו פעם אחת \u0005נשאל על שבועתו\u0006 והפר אותה\u0005] —\u0006 \u0003ניהדר\u0004 \u0005[שיחזור]\u0006 למלאך המוות, שאף במקרה זה יוכל להפר שבועתו. \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 נשאל — ש\u0003לא ניהדר\u0004 \u0005[יחזור].\u0006 וכיון שלא נשאל מעולם על שבועתו, נשאר בגן עדן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 מלאך המות: על כל פנים \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי סכינאי\u0004 \u0005[\u0006את \u0005סכיני]\u0006 בחזרה. \u0003לא הוה קא יהיב ליה\u0004 \u0005[לא נתן לו],\u0006 שאמר מוטב שלא יהרוג עוד אנשים. \u0003נפקא בת קלא\u0004 \u0005[יצאה בת קול]\u0006 \u0003ואמרה ליה\u0004 \u0005[לו]\u0006 לר' יהושע: \u0003הב ניהליה, דמיתבעא לברייתא\u0004 \u0005[תן לו אותה,\u0006 שהיא \u0005נחוצה לבריות],\u0006 שהמות הוא חלק מדרך העולם. היה \u0003מכריז אליהו קמיה\u0004 \u0005[לפניו]:\u0006 \u0003פנו מקום לבר ליואי\u0004 \u0005[לבן לוי]!\u0006 \u0003פנו מקום לבר ליואי\u0004 \u0005[לבן לוי]!\u0006","\u0003אזל אשכחיה\u0004 \u0005[הלך\u0006 ר' יהושע בן לוי ו\u0005מצאו]\u0006 את \u0003ר' שמעון בן יוחאי\u0004 בגן העדן \u0003דהוה יתיב על תלת עשר תכטקי פיזא\u0004 \u0005[שהיה יושב על שלושה עשר מצעות זהב].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' שמעון בר יוחאי: \u0003את הוא בר ליואי\u0004 \u0005[אתה הוא בן לוי]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הן.\u0004 אמר לו ר' שמעון: האם \u0003נראתה קשת בימיך? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הן.\u0004 אמר לו ר' שמעון: \u0003אם כן, אי\u0004 \u0005[אין]\u0006 \u0003אתה בר ליואי\u0004 \u0005[בן לוי],\u0006 שהוא צדיק גמור וכשיש בדור צדיק גמור אין הקשת נראית בעולם. שהלא היא אות שראוי היה לבוא מבול לעולם בשל חטאי באי העולם, אולם זכות הצדיק מגינה על העולם מפניו. ומעירים: \u0003ולא היא, דלא הואי מידי\u0004 \u0005[ואין זה כן, כי\u0006 אכן \u0005לא היתה כלל\u0006 קשת בימיו\u0005],\u0006 \u0003אלא סבר\u0004 \u0005[חשב]\u0006 ר' יהושע בן לוי: \u0003לא אחזיק טיבותא לנפשאי\u0004 \u0005[טובה לעצמי],\u0006 שאני צדיק כל כך. כיוצא בזה מסופר: \u0003ר' חנינא בר פפא שושביניה הוה\u0004 \u0005[חבירו\u0006 של מלאך המות \u0005היה]\u0006 והיה מתראה איתו הרבה. \u0003כי הוה ניחא נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 ר' חנינא \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003למלאך המות: זיל עביד ליה רעותיה\u0004 \u0005[לך עשה לו\u0006 את \u0005רצונו].\u0006 \u0003אזל לגביה ואיתחזי ליה\u0004 \u0005[הלך אליו ונראה לו].\u0006 \u0003אמר ליה\u0004 \u0005לו\u0006 למלאך: \u0003שבקי תלתין\u0004 \u0005[הנח לי שלושים]\u0006 \u0003יום עד דנהדר תלמודאי\u0004 \u0005[שאחזור על לימודי].\u0006 \u0003דאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003אשרי מי שבא לכאן\u0004 לעולם העליון \u0003ותלמודו בידו. שבקיה, לבתר תלתין יומין אזל איתחזי ליה\u0004 \u0005[הניחו,\u0006 ו\u0005לאחר שלושים יום הלך\u0006 ו\u0005נראה לו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 למלאך המות: \u0003אחוי\u0004 \u0005[הראה]\u0006 \u0003לי דוכתאי\u0004 \u0005[\u0006את \u0005מקומי]\u0006 בגן עדן. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לחיי\u0004 \u0005[בסדר].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי\u0004 את \u0003סכינך דלמא מבעתת לי באורחא\u0004 \u0005[שמא תפחידני בדרך].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 מלאך המות: \u0003כחברך בעית למיעבד\u0004 \u0005[כמו חברך,\u0006 ר' יהושע, \u0005רוצה אתה לעשות]\u0006 \u0003לי\u0004 ולברוח? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חנינא למלאך המוות: \u0003אייתי\u0004 \u0005[הבא]\u0006 \u0003ספר תורה וחזי מי איכא מידי דכתיב ביה\u0004 \u0005[וראה האם יש דבר שנאמר בו]\u0006 ש\u0003לא קיימתיה\u0004 \u0005[קיימתיו],\u0006 ולכן ראוי אני להכנס בחיי, לא כמו ר' יהושע בן לוי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 מלאך המוות: \u0003מי איכרכת\u0004 \u0005[האם נכרכת,\u0006 נדבקת\u0005]\u0006 \u0003בבעלי ראתן ואיעסקת\u0004 \u0005[ועסקת]\u0006 \u0003בתורה\u0004 כמוהו? ומעירים: \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 שלא הגיע לאותה מעלה גדולה, \u0003כי נח נפשיה\u0004 \u0005[כאשר נחה נפשו,\u0006 נפטר\u0005]\u0006 \u0003אפסיק ליה עמודא דנורא בין דידיה לעלמא\u0004 \u0005[הפסיק לו,\u0006 חצץ \u0005עמוד אש בינו ובין הכל].\u0006 \u0003וגמירי\u0004 \u0005[ו\u0006אנו \u0005למודים]\u0006 \u0003דלא מפסיק עמודא דנורא\u0004 \u0005[שאין מפסיק,\u0006 חוצץ \u0005עמוד אש]\u0006 \u0003אלא לחד בדרא\u0004 \u0005[לאחד בדור]\u0006 \u0003או לתרין בדרא\u0004 \u0005[לשנים בדור].\u0006 כיון שהיה עמוד האש מפסיק לא יכלו לגשת אליו לטפל בקבורתו.","","","\u0003קרב לגביה\u0004 \u0005[ניגש אליו]\u0006 \u0003ר' אלכסנדרי, אמר: \"עשה\u0004 שיסתלק עמוד האש \u0003בשביל כבוד חכמים\". לא אשגח\u0004 \u0005[השגיח]\u0006 בו. והוסיף לבקש: \u0003\"עשה בשביל כבוד אביך\" — לא אשגח\u0004 \u0005[השגיח]\u0006 בו. \u0003\"עשה בשביל כבוד עצמך\"\u0004 — ואז \u0003איסתלק\u0004 \u0005[הסתלק]\u0006 עמוד זה. \u0003אמר אביי:\u0004 עמוד זה בא \u0003לאפוקי ממאן\u0004 \u0005[להוציא,\u0006 להבדיל בינו \u0005ממי]\u0006 ש\u0003לא קיים\u0004 את כל התורה כולה ו\u0003אפילו\u0004 לא חיסר אלא \u0003אות אחת\u0004 ממנה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר מתנא: לאפוקי ממר\u0004 \u0005[להוציא,\u0006 להבדיל, \u0005מאדוני]\u0006 \u0003דלא אית ליה\u0004 \u0005[שאין לו]\u0006 \u0003מעקה לאיגריה\u0004 \u0005[לגגו],\u0006 שתוך כדי הדברים אמר לו דברי מוסר אלה. ומעירים, \u0003ולא היא\u0004 \u0005[ואין זה כך],\u0006 שלא היה לו מעקה, אלא בכלל \u0003מיהוה הוה וההיא שעתא הוא דשדייה זיקא\u0004 \u0005[היה לו\u0006 מעקה אלא \u0005באותה שעה הפילו הרוח].\u0006","\u0003אמר ר' חנינא: מפני מה אין בעלי ראתן בבבל — מפני שאוכלין תרדין, ושותין שכר של היזמי\u0004 (של כישות). \u0003אמר ר' יוחנן: מפני מה אין מצורעין בבבל — מפני שאוכלין תרדין, ושותין שכר, ורוחצין במי פרת,\u0004 שכל אלה מבריאים את הגוף.",""],["\u0003האשה שנפלו לה נכסים\u0004 בירושה \u0003עד שלא\u0004 (לפני) ש\u0003תתארס,\u0004 ואחר כך נתארסה — \u0003מודים בית שמאי ובית הלל שמוכרת\u0004 נכסים אלה או \u0003נותנת\u0004 אותם במתנה כרצונה — \u0003וקיים\u0004 מה שמכרה או נתנה. \u0003נפלו לה\u0004 הנכסים \u0003משנתארסה\u0004 — \u0003בית שמאי אומרים: תמכור\u0004 כל עוד היא ארוסה, \u0003ובית הלל אומרים: לא תמכור. אלו ואלו מודים שאם מכרה ונתנה —\u0004 מה שעשתה \u0003קיים.\u0004","\u0003אמר ר' יהודה: אמרו חכמים לפני רבן גמליאל: הואיל וזכה באשה\u0004 גופה על ידי הקידושין, מדוע אם כן \u0003לא יזכה בנכסים\u0004 מזמן האירוסין? ומדוע אמרו שמכירתה קיימת? \u0003אמר להם: על החדשים,\u0004 על הנכסים שנפלו לה לאחר נישואין \u0003אנו בושים,\u0004 שלא ברור לנו הטעם מפני מה לא תמכור אותם, שהרי שלה הם, \u0003אלא שאתם\u0004 מוסיפים ו\u0003מגלגלין עלינו,\u0004 מבקשים לאסור למכור גם \u0003את הישנים\u0004 שזכתה בהם קודם לכן?!","\u0003נפלו לה\u0004 הנכסים \u0003משנשאת — אלו ואלו,\u0004 בית שמאי ובית הלל, \u0003מודים שאם מכרה\u0004 או \u0003נתנה\u0004 אותם לאחרים, \u0003שהבעל מוציא מיד הלקוחות.\u0004 נפלו לה נכסים \u0003עד שלא נשאת, ונשאת\u0004 לאחר מכן — \u0003רבן גמליאל אומר: אם מכרה\u0004 או \u0003נתנה\u0004 אותם — מה שעשתה \u0003קיים. אמר ר' חנינא בן עקביא, אמרו\u0004 חכמים \u0003לפני רבן גמליאל: הואיל וזכה באשה\u0004 על ידי הנישואין, מדוע \u0003לא יזכה בנכסים? אמר להם: על החדשים\u0004 שנפלו לה לאחר נישואיה \u0003אנו בושים, אלא שאתם מגלגלין עלינו\u0004 גם את \u0003הישנים\u0004 שבאו לידה טרם נישואיה?!","ואילו \u0003ר' שמעון חולק\u0004 (מחלק בדין) \u0003בין נכסים לנכסים,\u0004 ולדעתו, \u0003נכסים הידועין לבעל\u0004 — \u0003לא תמכור\u0004 משנישאת, \u0003ואם מכרה\u0004 או \u0003נתנה\u0004 — מה שעשתה \u0003בטל.\u0004 נכסים \u0003שאינן ידועין לבעל — לא תמכור, ואם מכרה\u0004 או \u0003נתנה — מה שעשתה קיים.\u0004","על תחילת המשנה שואלים: \u0003מאי שנא רישא\u0004 \u0005[\u0006ב\u0005מה שונה ההתחלה\u0006 של המשנה\u0005]\u0006 כשנפלו לה נכסים לפני שנתארסה ש\u0003לא פליגי\u0004 \u0005[נחלקו]\u0006 בית שמאי ובית הלל, \u0003ומאי שנא סיפא\u0004 \u0005[ו\u0006ב\u0005מה שונה הסוף]\u0006 כשנפלו לה משנתארסה \u0003דפליגי\u0004 \u0005[ש\u0006הם \u0005חלוקים]?\u0006 שאם חלוקים ביחס לזכותה בנכסים לאחר האירוסין, מדוע אם כן ישתנה הדין כאשר זכתה בהם טרם אירוסיה?","ומשיבים: \u0003אמרי דבי\u0004 \u0005[אמרו\u0006 חכמים \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי,\u0004 החילוק הוא זה: \u0003רישא\u0004 \u0005[\u0006ב\u0005תחילה],\u0006 במקרה שנפלו לה לפני שנתארסה — \u0003בזכותה\u0004 (ברשותה) \u0003נפלו,\u0004 ולכן לדעת הכל הריהי מוכרת ונותנת וקיים. ואילו \u0003סיפא\u0004 \u0005[\u0006ב\u0005סוף],\u0006 במקרה שנפלו לה לאחר שנתארסה — \u0003בזכותו\u0004 (ברשותו) \u0003נפלו.\u0004","ומקשים: \u0003אם\u0004 ברור לנו כי לאחר האירוסין \u0003בזכותו נפלו — אם כן כי\u0004 \u0005[כאשר]\u0006 \u0003מכרה ונתנה אמאי\u0004 \u0005[מדוע]\u0006 מה שעשתה \u0003קיים? אלא\u0004 יש להסביר כך: \u0003רישא\u0004 \u0005[\u0006ב\u0005תחילה]\u0006 כשנפלו לה לפני שנתארסה — \u0003ודאי בזכותה נפלו,\u0004 ואין ספק שהנכסים היו שלה לגמרי, ואילו \u0003סיפא\u0004 \u0005[\u0006ב\u0005סוף],\u0006 כשנפלו לה לאחר שנתארסה, \u0003אימר\u0004 \u0005[אמור]\u0006 \u0003בזכותה, אימר\u0004 \u0005[אמור]\u0006 \u0003בזכותו,\u0004 שלא ברור ברשות מי הנכסים, ומחמת ספק זה אמרו בית הלל: \u0003לכתחלה לא תמכור,\u0004 אבל \u0003אם מכרה ונתנה — קיים.\u0004","שנינו בראש המשנה: \u0003אמר ר' יהודה, אמרו לפני רבן גמליאל:\u0004 \"אם זכה באשה לא יזכה בנכסים\" וכו'. \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003ר' יהודה\u0004 שהביא שאלה זו ששאלו חכמים, על מה שמוכרת \u0003לכתחלה\u0004 התכוון? והשאלה היתה להבין את שיטת בית שמאי, מדוע לשיטתם אם נפלו לה הנכסים לאחר שנתארסה יכולה היא למוכרם, \u0003או\u0004 על המכירה ב\u0003דיעבד,\u0004 שאם מכרה ונתנה קיים, אפילו לדעת בית הלל, ועל זה היתה השאלה?"],["\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו בברייתא, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יהודה, אמרו לפני רבן גמליאל: הואיל וזו אשתו וזו אשתו,\u0004 בין ארוסה בין נשואה, מה \u0003זו\u0004 הנשואה \u0003מכרה בטל — אף זו\u0004 הארוסה צריך שיהיה \u0003מכרה בטל! אמר להן: על החדשים אנו בושים, אלא שאתם מגלגלים עלינו את הישנים? שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי על דין ב\u0003דיעבד קאמר\u0004 \u0005[אמר]\u0006 ר' יהודה, שהרי שאלו: מפני מה אין מכרה בטל. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמר ר' חנינא בן עקביא: לא כך השיבן רבן גמליאל לחכמים, אלא כך השיבן: לא אם אמרתם בנשואה\u0004 שיש לבעל זכויות יתירות בה — \u0003שכן בעלה זכאי במציאתה ובמעשה ידיה ובהפרת נדריה, תאמרו בארוסה שאין בעלה זכאי לא במציאתה ולא במעשה ידיה ולא בהפרת נדריה!\u0004","\u0003אמרו לו\u0004 חכמים: \u0003רבי,\u0004 אנחנו מקבלים את הטעם הזה כאשר \u0003מכרה לה\u0004 (בשביל עצמה) \u0003עד שלא נשאת,\u0004 אבל אם \u0003נשאת ואחר כך מכרה\u0004 נכסים אלו שנפלו לה קודם לכן, \u0003מהו? אמר להו\u0004 \u0005[להם]:\u0006 \u0003אף זו מוכרת ונותנת ו\u0004מה שעשתה \u0003קיים. אמרו לו: הואיל וזכה באשה, לא יזכה בנכסים\u0004 הבאים עימה?! \u0003אמר להם:\u0004 הלא \u0003על החדשים\u0004 שנפלו לה לאחר זמן \u0003אנו בושין, אלא שאתם מגלגלין עלינו את הישנים,\u0004 שאף על הנכסים שנפלו לה טרם נישואיה רוצים אתם לומר שלא תוכל למוכרם?!","ומקשים: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]\u0006 בנוסח אחר: באו הנכסים לרשותה \u0003עד שלא נשאת ונשאת, רבן גמליאל אומר: אם מכרה\u0004 או \u0003נתנה — קיים.\u0004 ואילו מלשון הברייתא נראה שמוכרת ונותנת לכתחילה!","\u0003אמר רב זביד: תני\u0004 \u0005[שנה]\u0006 ותקן במשנתנו כגירסה זו: \u0003מוכרת ונותנת וקיים. רב פפא אמר: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה].\u0006 כי \u0003הא\u0004 \u0005[זו]\u0006 משנתנו היא כדעת \u0003ר' יהודה אליבא\u0004 \u0005[על פי שיטת]\u0006 \u0003רבן גמליאל, הא\u0004 \u0005[זו]\u0006 בברייתא היא דעת \u0003ר' חנינא בן עקביא אליבא\u0004 \u0005[לשיטת]\u0006 \u0003רבן גמליאל.\u0004 ושואלים: \u0003ו\u0004אם כן נמצא כי \u0003ר' חנינא בן עקביא\u0004 סבור \u0003כ\u0004שיטת \u0003בית שמאי?\u0004 שהרי לשיטת בית הלל אפילו בעודה ארוסה אינה מוכרת לכתחילה, וכל שכן משנישאה! והרי ידוע שהלכה כבית הלל! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 ר' חנינא בן עקביא: \u0003לא נחלקו בית שמאי ובית הלל על דבר זה\u0004 בנכסים שנפלו לה לפני הנישואין, שלדעתו הכל מודים שמוכרת לכתחילה.","\u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 פסק זה: \u0003בין שנפלו לה נכסים עד שלא נתארסה, בין שנפלו לה נכסים משנתארסה, וניסת,\u0004 ואחר נישואיה מכרה או נתנה — \u0003הבעל מוציא מיד הלקוחות.\u0004","ושואלים: \u0003כמאן\u0004 \u0005[כמי]\u0006 אמרו דבר זה? ש\u0003לא כ\u0004דעת \u0003ר' יהודה ולא כ\u0004דעת \u0003ר' חנינא בן עקביא,\u0004 שלשיטת שניהם המיקח קיים! ומשיבים: \u0003אינהו דאמרי\u0004 \u0005[הם שאמרו]\u0006 \u0003כ\u0004שיטת \u0003רבותינו, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003רבותינו חזרו ונמנו\u0004 (והצביעו) בדיון על ענין זה, והחליטו: \u0003בין שנפלו לה עד שלא תתארס ובין שנפלו לה משנתארסה וניסת — הבעל מוציא מיד הלקוחות.\u0004","שנינו במשנה: אם נפלו לה נכסים \u0003משניסת\u0004 — \u0003אלו ואלו,\u0004 בית שמאי ובית הלל, \u0003מודים\u0004 שהבעל מוציא מיד הלקוחות. ומעירים: \u0003לימא תנינא\u0004 \u0005[\u0006האם \u0005נאמר\u0006 שכבר \u0005שנינו\u0006 במשנתנו\u0005]\u0006 \u0003לתקנת אושא?\u0004 ש\u0003אמר ר' יוסי בר' חנינא, באושא התקינו: האשה שמכרה בנכסי מלוג בחיי בעלה, ומתה — הבעל מוציא מיד הלקוחות.\u0004 ולכאורה הם הם הדברים האמורים במשנתנו!","ודוחים: אין הדבר כך, אלא \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 אומרת שהבעל מוציא מיד הלקוחות \u0003בחייה, ו\u0004הכוונה היא דווקא — \u0003לפירות.\u0004 שאף שמכרה את הקרקע הוא יכול להוציא מהם את הפירות שאכלו במשך הזמן, משום שפירות נכסי מלוג שייכים לו, אבל גוף הקרקע נשאר בידי הלוקח לגמרי. ואילו \u0003תקנת אושא\u0004 היא אפילו \u0003בגופה של קרקע\u0004 עצמה שהבעל מוציא מן הלקוחות \u0003ולאחר מיתה\u0004 של האשה, שהוא יורש אותה.","שנינו במשנה ש \u0003ר' שמעון חולק\u0004 (מחלק בדין) \u0003בין נכסים\u0004 הידועים לבעל ושאינם ידועים. ושואלים: \u0003אלו הן ידועין ואלו הן שאינן ידועין? אמר ר' יוסי בר' חנינא: ידועין\u0004 משמעו \u0003מקרקעי\u0004 \u0005[קרקעות],\u0006 שהם דברים שאי אפשר להסתיר אותם, וכיון שכך, ידע הבעל שנכסים אלה עתידים ליפול לה בירושה, ועל מנת לאכול מהם פירות נשא אותה. ואילו \u0003שאינן ידועין,\u0004 הם \u0003מטלטלין. ור' יוחנן אמר: אלו ואלו,\u0004 קרקעות ומטלטלים, נכסים \u0003ידועין הן. ואלו הן שאינן ידועין — כל שיושבת כאן ונפלו לה נכסים במדינת הים\u0004 (במדינה אחרת), שנכסים אלה לא הביא הבעל בחשבון בזמן הנישואין, ולכן אי אפשר לומר שחלה על האשה התחייבות שלא למוכרם.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אלו הן\u0004 נכסים \u0003שאינן ידועין — כל שיושבת\u0004 האשה \u0003כאן ונפלו לה נכסים במדינת הים.\u0004","מסופר: \u0003ההיא איתתא\u0004 \u0005[\u0006מעשה ב\u0005אותה אשה]\u0006 שהיתה גרושה או אלמנה ועמדה להינשא שוב, \u0003דבעיא דתברחינהו לנכסה מגברה\u0004 \u0005[שרצתה להבריח את נכסיה מבעלה]\u0006 ולא רצתה שיזכה הבעל בנכסיה, \u0003כתבתינהו לברתה\u0004 \u0005[כתבה אותם\u0006 את הנכסים \u0005לבתה]\u0006 במתנה לפני הנישואין והודיעה לעדים שאינה נותנת מתנה כלל ואינה עושה כן אלא כדי להבריח נכסים אלה מבעלה. ולבסוף \u0003אינסיבה ואיגרשה\u0004 \u0005[נישאה והתגרשה]\u0006 ורצתה שתחזיר לה הבת את הנכסים הללו, והבת טענה שהיתה זו מתנה גמורה."],["\u0003אתאי לקמיה\u0004 \u0005[באה לפני]\u0006 \u0003רב נחמן קרעיה\u0004 \u0005[קרעו]\u0006 \u0003רב נחמן לשטרא\u0004 \u0005[את שטר]\u0006 המתנה, כי הסכים לדעת האם שלא התכוונה להקנות לבתה בשטר זה. \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רב ענן לקמיה\u0004 \u0005[לפני]\u0006 \u0003מר עוקבא\u0004 ראש הגולה, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חזי מר\u0004 \u0005[יראה אדוני]\u0006 את \u0003נחמן חקלאה\u0004 \u0005[האיכר]\u0006 \u0003היכי מקרע שטרי דאינשי\u0004 \u0005[איך\u0006 הוא \u0005קורע שטרות של בני אדם],\u0006 שהתרעם עליו כיצד עשה מעשה וקרע שטר שהיה כתוב כהלכה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 מר עוקבא: \u0003אימא לי איזי, גופא דעובדא היכי הוה\u0004 \u0005[אמור לי בבקשה, גוף המעשה איך היה]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי והכי הוה\u0004 \u0005[כך וכך היה\u0006 המעשה\u0005]\u0006 וסיפר לו את כל הפרטים. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שטר מברחת קא אמרת\u0004 \u0005[אומר אתה]?\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב חנילאי בר אידי אמר שמואל: מורה הוראה אני\u0004 ומודיע הוראה זו לרבים: \u0003אם יבא שטר מברחת לידי\u0004 — \u0003אקרענו,\u0004 שברור ששטר כזה לא נועד לשם נתינה גמורה, ואינו אלא להברחה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן\u0004 כשראה שקרע את השטר: \u0003טעמא מאי\u0004 \u0005[מה הטעם\u0006 בדבר\u0005]?\u0006 — \u0003דלא שביק איניש נפשיה ויהיב לאחריני\u0004 \u0005[שאין אדם מניח\u0006 את \u0005עצמו ונותן\u0006 מתנה \u0005לאחרים],\u0006 ולכן אנו מניחים שלא היתה זו מתנה אמיתית, אולם \u0003הני מילי לאחריני, אבל לברתה יהיבא\u0004 \u0005[דברים אלה אמורים\u0006 דווקא כשנותן \u0005לאחרים,\u0006 לזרים, \u0005אבל לבתה\u0006 האם דווקא \u0005נותנת]!\u0006 אמר לו רב נחמן: \u0003אפילו הכי\u0004 \u0005[כך],\u0006 אפילו \u0003במקום ברתה\u0004 \u0005[בתה],\u0006 טובת \u0003נפשה\u0004 \u0005[עצמה]\u0006 \u0003עדיפא\u0004 \u0005[עדיפה]\u0006 \u0003לה,\u0004 לאם, ובודאי לא התכוונה לוותר על זכותה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003הרוצה שתבריח נכסיה מבעלה כיצד היא עושה?\u0004 — \u0003כותבת\u0004 נכסיה ב\u0003שטר פסים\u0004 (שטר של הסכם, שמקבלו מבטיח שלא ייפרע) \u0003לאחרים,\u0004 וכך אין הבעל יכול לשלוט בנכסיה, אלו \u0003דברי רבן שמעון בן גמליאל.\u0004","\u0003וחכמים אומרים:\u0004 תקנה זו אינה טובה, כי אם \u0003רצה\u0004 המקבל — \u0003מצחק בה,\u0004 שהרי אם השטר נכתב כדין יכול המקבל לצחוק עליה ולהחזיק בנכסים ואין לה תקנה. \u0003עד שתכתוב לו\u0004 שטר בנוסח שמתנה זו ניתנת לו \u0003מהיום ולכשארצה.\u0004 כך שבכל עת יכולה היא לומר שאינה רוצה, ולבטל את השטר.","ומדייק רבא: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005],\u0006 ש\u0003כתבה ליה הכי\u0004 \u0005[לו כך],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא כתבה ליה הכי\u0004 \u0005[לו כך] —\u0006 \u0003קננהי\u0004 \u0005[קנה אותם]\u0006 ה\u0003לוקח,\u0004 משמע ששטר מברחת יש בו ממש, ושלא כהוראת שמואל!","\u0003אמר ר' זירא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששטר מברחת מתבטל — \u0003בכולה,\u0004 שנכתב לגבי כל הנכסים, וברור שאין אדם נותן את כל נכסיו במתנה ואינו משייר לעצמו דבר. \u0003הא\u0004 \u0005[זה]\u0006 שאין השטר בטל — \u0003במקצתה\u0004 שכתבה השטר על מקצת הנכסים, שבאופן כזה צריך לעשות תקנה, שאם לא כן יקנה המקבל את המתנה לגמרי.","ומקשים: אם כן, כיון שכאשר כותב את הנכסים כולם אין השטר עושה קנין, על כן \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא קננהי\u0004 \u0005[קנה אותם]\u0006 ה\u0003לוקח — ניקנינהו\u0004 \u0005[שיקנה אותם]\u0006 ה\u0003בעל! אמר אביי: עשאום\u0004 את הנכסים הללו שנתנה במתנה \u0003כנכסים שאין ידועין לבעל, ואליבא\u0004 \u0005[ועל פי שיטת]\u0006 \u0003ר' שמעון\u0004 במשנתנו, שאם מכרה נכסים כאלה לאחר שנשאת, מכרה קיים. ואף אלה שנתנה במתנה, כיון שיש שטר עליהם — אין לבעל עוד שליטה בהם.","\u0003נפלו לה כספים\u0004 בירושה בזמן שהיא נשואה — \u0003ילקח\u0004 (ייקנה) \u0003בהן קרקע, והוא\u0004 (הבעל) \u0003אוכל\u0004 את \u0003פירות\u0004 הקרקע והקרן עצמה קיימת לה. נפלו לה \u0003פירות התלושין מן הקרקע\u0004 — דינם ככספים ו\u0003ילקח בהן קרקע, והוא אוכל פירות.\u0004","\u0003פירות המחוברים בקרקע\u0004 מה דינם? \u0003אמר ר' מאיר: שמין\u0004 (מעריכים) \u0003אותה\u0004 את הקרקע \u0003כמה היא יפה\u0004 (שווה) \u0003ב\u0004זמן שה\u0003פירות\u0004 בתוכה, \u0003וכמה היא יפה\u0004 לכשתהיה \u0003בלא פירות, ו\u0004ההבדל בין סכומים אלה שהוא ה\u0003מותר\u0004 שייך לאשה, ולכן \u0003ילקח בהן קרקע והוא אוכל פירות. וחכמים אומרים: המחוברים לקרקע — שלו,\u0004 והוא אוכל אותם, שהרי הבעל זוכה בפירות נכסיה. \u0003והתלושין מן הקרקע — שלה\u0004 הם, והם נחשבים כשאר כספים שמכניסה לו \u0003וילקח בהן קרקע והוא אוכל פירות.\u0004","\u0003ר' שמעון אומר: מקום שיפה כחו בכניסתה\u0004 (בנישואיה) — \u0003הורע כחו ביציאתה\u0004 (בגירושיה), ולהיפך: \u0003מקום שהורע כחו בכניסתה — יפה כחו ביציאתה. כיצד? פירות המחוברים לקרקע, בכניסתה,\u0004 כשהיא נישאת, והיו בנכסיה פירות כאלה — הרי הם נחשבים ל\u0003שלו,\u0004 כחכמים. \u0003וביציאתה\u0004 כשמגרשה, הפירות הללו כשהם מחוברים הם \u0003שלה\u0004 משום שהם נחשבים כחלק מן הנכסים. \u0003ו\u0004אילו \u0003התלושין מן הקרקע — בכניסתה\u0004 הם \u0003שלה, וביציאתה\u0004 פירות שנתלשו לפני שגירשה, הם \u0003שלו,\u0004 שהרי כבר זכה בפירות נכסיה.","שנינו במשנה שכאשר נפלו לאשה כספים, קונים בהם נכסים הנותנים פירות. ורוצים לברר מה עושים כאשר אין הבעל והאשה מסכימים אלו נכסים יקנו בהם. ועל כך אמרו: \u0003פשיטא\u0004 \u0005[פשוט\u0006 לנו\u0005]\u0006 אם אחד מהם אומר לקנות \u0003ארעא\u0004 \u0005[קרקע]\u0006 \u0003ו\u0004השני אומר \u0003בתי\u0004 \u0005[בתים] —\u0006 קונים \u0003ארעא\u0004 \u0005[קרקע],\u0006 שקיימת תמיד. \u0003בתי ודיקלי\u0004 \u0005[בתים\u0006 או \u0005דקלים] —\u0006 קונים \u0003בתי\u0004 \u0005[בתים].\u0006 \u0003דיקלי ואילני\u0004 \u0005[דקלים\u0006 או שאר \u0005אילנות] —\u0006 קונים \u0003דיקלי\u0004 \u0005[דקלים].\u0006 \u0003אילני וגופני\u0004 \u0005[אילנות\u0006 או \u0005גפנים] —\u0006 קונים \u0003אילני\u0004 \u0005[אילנות].\u0006 וכללו של דבר: קונים דבר שהוא מתקיים יותר, ולא דבר שכלה עם הזמן.","נפלו לאשה בירושה \u0003אבא\u0004 \u0005[יער]\u0006 של עצי סרק, \u0003זרדתא\u0004 \u0005[\u0006עץ \u0005עוזרד],\u0006 שאין פירותיו חשובים, או \u0003פירא דכוורי\u0004 \u0005[בריכת דגים],\u0006 נחלקו מה דינם, \u0003אמרי לה פירא\u0004 \u0005[יש אומרים\u0006 שכל אלה נחשבים כ\u0005פירות]\u0006 \u0003ואמרי לה קרנא\u0004 \u0005[ויש אומרים\u0006 שהם נחשבים כ\u0005קרן],\u0006 משום שאינם מתחדשים, ולבסוף הכל כלה. \u0003כללא דמילתא\u0004 \u0005[כללו של דבר]:\u0006 כל דבר שכאשר כורתים אותו ונוטלים אותו \u0003גזעו מחליף\u0004 וצומח מחדש — הרי הוא נחשב \u0003פירא\u0004 \u0005[פרי]\u0006 ודבר ש\u0003אין גזעו מחליף —\u0004 נחשב כ\u0003קרנא\u0004 \u0005[קרן].\u0006","\u0003אמר ר' זירא\u0004 ש\u0003אמר ר' אושעיא\u0004 ש\u0003אמר ר' ינאי ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003אמר ר' אבא\u0004 ש\u0003אמר ר' אושעיא\u0004 ש\u0003אמר ר' ינאי: הגונב\u0004"],["\u0003ולד\u0004 של \u0003בהמת מלוג,\u0004 שהבהמה עצמה היתה שייכת לאשה כנכסי מלוג, וכגון שנפלה לה בירושה, וילדה — \u0003משלם תשלומי כפל לאשה,\u0004 ולכאורה הטעם בזה שחובת התשלום לאשה ולא לבעל היא משום שלדעתו ולד זה אינו נחשב לפירות נכסים אלא כגוף הנכסים.","ומקשים: \u0003כמאן\u0004 \u0005[כמי]\u0006 אמר זאת? \u0003לא כרבנן\u0004 \u0005[כ\u0006שיטת \u0005חכמים]\u0006 \u0003ולא כ\u0004שיטת \u0003חנניה,\u0004 ומהן השיטות הללו? — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ולד בהמת מלוג —\u0004 שייך \u0003לבעל, ולד שפחת מלוג —\u0004 שייך \u0003לאשה, וחנניה בן אחי יאשיה אמר: עשו ולד שפחת מלוג כולד בהמת מלוג,\u0004 וגם הוא שייך לבעל. ומכל מקום בולד בהמה הכל מודים שהוא שייך לבעל, ומדוע ישלם הגנב תשלומי כפל לאשה?","ומשיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 ששיטת ר' ינאי היא כ\u0003דברי הכל,\u0004 יש לחלק בין שימוש בנכסים בדרך כלל לתשלומי כפל, כי \u0003פירא תקינו ליה רבנן\u0004 \u0005[\u0006אכילת \u0005פירות תיקנו לו חכמים\u0006 לבעל\u0005],\u0006 ואולם \u0003פירא דפירא\u0004 \u0005[פירי פירות]\u0006 \u0003לא תקינו ליה רבנן\u0004 \u0005[תיקנו לו חכמים],\u0006 והרי תשלומי כפל אלו אינם הולד עצמו, אלא פירות הבאים על ידי גניבת הולד, והוא בגדר פירי פירות.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003חנניה\u0004 שמשווה ולד שפחה לולד בהמה — \u0003היינו\u0004 \u0005[זהו]\u0006 הטעם, לפי ש\u0003לא חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003למיתה\u0004 של האם, ולכן רואים את האם כקרן ואת הולד כפרי הנכסים.","\u0003אלא רבנן\u0004 \u0005[חכמים]\u0006 \u0003אי חיישי\u0004 \u0005[אם\u0006 הם \u0005חוששים]\u0006 \u0003למיתה\u0004 של האם ולכן הם אומרים כי ולד השפחה לאשה — \u0003אפילו ולד בהמת מלוג נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יהיה דינו כפירות, אלא כקרן, שאם תמות הבהמה לא יישאר לאשה דבר, ולכן יש לתקן שיהא הולד במקום האם. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא חיישי\u0004 \u0005[חוששים\u0006 הם\u0005]\u0006 \u0003למיתה,\u0004 אם כן \u0003אפילו ולד שפחת מלוג נמי\u0004 \u0005[גם כן]\u0006 יהיה שייך לבעל כפירות נכסים, ומה טעם החלוקה?","ומשיבים: \u0003לעולם\u0004 צריך לפרש שהם \u0003חיישי\u0004 \u0005[חוששים]\u0006 \u0003למיתה, ושאני\u0004 \u0005[ו\u0006אולם \u0005שונה]\u0006 \u0003בהמה, דאיכא\u0004 \u0005[שיש,\u0006 שנשאר\u0005]\u0006 \u0003עורה\u0004 גם לאחר מיתה ואין הקרן כלה לגמרי, אפילו כשמתה הבהמה, מה שאין כן בשפחה שמשמתה לא נותר ממנה דבר, ולכך, לשיטתו, העמידו את ולדה ברשות האשה, כדי שבמות השפחה יוותר וולדה לאשה.","\u0003אמר רב הונא בר חייא אמר שמואל: הלכה כחנניה\u0004 שולד שפחה לבעל. \u0003אמר רבא אמר רב נחמן: אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003אמר שמואל הלכה כחנניה — מודה חנניה שאם נתגרשה\u0004 האשה — \u0003נותנת דמים ונוטלתן\u0004 את הוולדות, \u0003מפני שבח בית אביה,\u0004 שאין זה נאה שוולדות העבדים השייכים למשפחתה יהיו בידי אחר.","\u0003אמר רבא אמר רב נחמן: הכניסה לו\u0004 האשה לבעל בנדונייתה (נכסי מלוג), \u0003עז לחלבה\u0004 (עז חולבת) \u0003ורחל לגיזתה\u0004 (כבשה לגזוז את צמרה), \u0003ותרנגולת לביצתה, ודקל לפירותיו\u0004 — הבעל \u0003אוכל והולך\u0004 מן הפירות \u0003עד שתכלה הקרן,\u0004 ואין אומרים שבסופו של דבר לא יישאר דבר בעל ערך בידי האשה. וכיוצא בזה \u0003אמר רב נחמן:\u0004 אם \u0003עיילא ליה גלימא\u0004 \u0005[הכניסה לו גלימה]\u0006 כנכסי מלוג — השימוש בה \u0003פירא הוי\u0004 \u0005[פירות הן],\u0006 ולכן \u0003מכסי ביה ואזיל\u0004 \u0005[מתכסה בה והולך]\u0006 \u0003עד דכליא\u0004 \u0005[ש\u0006היא \u0005כלה].\u0006","ומעירים: \u0003כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 היא שיטה זו? — \u0003כי האי תנא\u0004 \u0005[כ\u0006שיטת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 אם הכניסה האשה בנדונייתה מקום על שפת הים שממנו כורים את \u0003המלח והחול\u0004 — כל מה שכורים שם \u0003הרי זה פירות.\u0004 הכניסה לו \u0003פיר\u0004 (חפירה) \u0003של גפרית,\u0004 או \u0003מחפורת\u0004 (מכרה) \u0003של צריף\u0004 (אלום), \u0003ר' מאיר אומר:\u0004 דברים אלה נחשבים ל\u0003קרן,\u0004 שהרי בסופו של דבר כלה כל מה שבמכרה. \u0003וחכמים אומרים:\u0004 מה שכורים משם \u0003פירות\u0004 הוא ומקום המכרה הוא הקרן וכשיטת חכמים פסק רב נחמן לגבי גלימה.","שנינו במשנה ש\u0003ר' שמעון אומר: מקום שיפה כחו\u0004 בכניסתה — הורע כוחה ביציאתה וכו'. ושואלים: שיטת \u0003ר' שמעון\u0004 הלא \u0003היינו\u0004 \u0005[זוהי]\u0006 שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 שלא הוסיף ולא שינה כלל מדברי חכמים? \u0003אמר רבא:\u0004 בענין פירות \u0003מחוברין בשעת יציאה\u0004 (גירושין) \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 למעשה; חכמים שלא פירשו מה דינם, סוברים שכאשר מגרשה הם שלו, ואילו ר' שמעון אומר שביציאתה הריהם שלה.","\u0003נפלו לה עבדים ושפחות זקנים — ימכרו וילקח\u0004 (ייקנה) \u0003מהן קרקע, והוא\u0004 (הבעל) \u0003אוכל פירות\u0004 קרקע זו. \u0003רבן שמעון בן גמליאל אומר:\u0004 עבדים ושפחות אלה רשאית היא ש\u0003לא תמכור, מפני שהן שבח בית אביה,\u0004 ובזיון הוא לה שיימכרו לאחרים. וכן אם \u0003נפלו לה זיתים וגפנים זקנים — ימכרו וילקח בהן קרקע והוא אוכל פירות. ר' יהודה אומר: לא תמכור, מפני שהן שבח בית אביה.\u0004","\u0003אמר רב כהנא אמר רב: מחלוקת\u0004 זו בזיתים וגפנים היא דווקא באופן \u0003שנפלו\u0004 כשהם \u0003בשדה שלה,\u0004 שבכל הנחלה כולה יש שבח בית אביה, ולכן אמר ר' יהודה שלא תמכור. \u0003אבל\u0004 אם נפלו לה \u0003בשדה שאינה שלה,\u0004 וכגון באופן שקנה אביה עצי זיתים בלא קרקע על מנת שיהיו בקרקע המוכר והוא יאכל את פירותיהם עד שייבשו, ומשמת האב ירשתם היא — \u0003דברי הכל תמכור, משום דקא כליא קרנא\u0004 \u0005[שכלה הקרן].\u0006 שהרי סופם של עצים אלה שימעטו במתן פירות, וסופם להיעקר, ואין איפוא בהם עצמם משום שבח בית אביה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף: הרי עבדים ושפחות\u0004 זקנים, \u0003דכי\u0004 \u0005[שכמו]\u0006 \u0003שדה שאינה שלה דמי\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 שהרי לכשימותו יכלה הקרן לגמרי \u0003ופליגי\u0004 \u0005[ונחלקו]\u0006 בכך! \u0003אלא\u0004 יש לחזור מן הדברים שאמרנו, ו\u0003אי איתמר הכי איתמר\u0004 \u0005[אם נאמר כך נאמר]:\u0006 \u0003אמר רב כהנא אמר רב: מחלוקת\u0004 בזיתים וגפנים העומדים \u0003בשדה שאינה שלה, אבל בשדה שלה — דברי הכל לא תמכור, מפני שבח בית אביה.\u0004","\u0003המוציא הוצאות על נכסי אשתו\u0004 להשביחם, אם \u0003הוציא הרבה\u0004 הוצאות \u0003ואכל\u0004 מהם פירות \u0003קימעא\u0004 (מעט) ולא הספיק עד שנתגרשה, או הוציא \u0003קימעא ואכל הרבה — מה שהוציא הוציא ומה שאכל אכל\u0004 ואין מחזירים זה לזה. אבל אם \u0003הוציא\u0004 ממון על הנכסים \u0003ולא אכל\u0004 מהם כלל — \u0003ישבע כמה הוציא, ויטול\u0004 את הוצאותיו.","ושואלים: \u0003וכמה\u0004 היא \u0003קימעא,\u0004 מה שיעורו של דבר? \u0003אמר ר' אסי: אפילו\u0004 אכל \u0003גרוגרת אחת, והוא שאכלה דרך כבוד.\u0004 כלומר, אכל אותה כדרך שאדם אוכל מפירות נכסיו, ולא בחטיפה. \u0003אמר\u0004"],["\u0003ר' אבא, אמרי בי\u0004 \u0005[אמרו\u0006 ב\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003רב: אפילו\u0004 אכל \u0003שיגרא דתמרי\u0004 \u0005[קבוצת תמרים\u0006 דבוקות יחד\u0005].\u0006 \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב ביבי:\u0004 אם אכל \u0003חובצא דתמרי\u0004 \u0005[עיסת תמרים]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005],\u0006 האם נחשבת היא אכילה בדרך כבוד? לשאלה זו לא נמצאה תשובה והרי היא \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ושאלו: אם \u0003לא אכלה דרך כבוד מאי\u0004 \u0005[מה],\u0006 כלומר, מהו השיעור שייחשב כאכילה? \u0003אמר עולא: פליגי בה תרי אמוראי במערבא\u0004 \u0005[נחלקו בכך שני אמוראים בארץ ישראל],\u0006 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 שאכל \u0003ב\u0004שיעור של \u0003כאיסר, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: בכדינר.\u0004","\u0003אמרי\u0004 \u0005[אמרו]\u0006 \u0003דייני דפומבדיתא: עבד\u0004 \u0005[עשה]\u0006 \u0003רב יהודה עובדא\u0004 \u0005[מעשה]\u0006 \u0003בחבילי זמורות\u0004 (ענפים) שלקח הבעל מנכסי האשה והאכילם לבהמתו, אף שאין זה מדרך הבהמה לאוכלם, והחשיב לו זאת כאכילה מנכסיה. ומעירים: \u0003רב יהודה לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 בענין אחר, ש\u0003אמר רב יהודה:\u0004 אדם שהחזיק באחוזת קרקע ו\u0003אכלה,\u0004 שאכל מיבול אותה אחוזה כשהיו אילנותיה \u0003ערלה,\u0004 או \u0003שביעית,\u0004 או \u0003כלאים,\u0004 שהפירות אסורים — \u0003הרי זו\u0004 נחשבת לקנין \u0003חזקה\u0004 בקרקע, כיון שיכול היה ליהנות מן הזמורות המותרות.","\u0003אמר רב יעקב אמר רב חסדא: המוציא הוצאות על נכסי אשתו קטנה\u0004 שהשיאו לו אותה אמה או אחיה — \u0003כמוציא על נכסי אחר דמי\u0004 \u0005[נחשב],\u0006 ואם מיאנה בו כשגדלה, ובטלו הנישואין — נוטל את מה שהשביח. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003עבדו\u0004 \u0005[עשו]\u0006 \u0003בה רבנן תקנתא\u0004 \u0005[חכמים תקנה]\u0006 שיהיה דינו כאריס המוציא הוצאות על שדה של אחר, \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא ניפסדינהו\u0004 \u0005[יפסיד אותם,\u0006 את הנכסים הללו\u0005],\u0006 שאם אינו בטוח שיקבל את שכר הוצאותיו אם תמאן — פעמים שלא ישביחם כלל, ויגרום שייפסדו.","מסופר: \u0003ההיא איתתא\u0004 \u0005[אשה אחת]\u0006 ש\u0003נפלו לה\u0004 בירושה \u0003ארבע מאה זוזי\u0004 \u0005[מאות זוזים]\u0006 ב\u0003בי חוזאי,\u0004 שהוא מקום רחוק מבבל, \u0003אזיל גברא אפיק שית מאה אייתי ארבע מאה\u0004 \u0005[הלך האיש,\u0006 הבעל, ו\u0005הוציא שש מאות\u0006 משלו להוצאות הדרך ו\u0005הביא ארבע מאות].\u0006 \u0003בהדי דקאתי איצטריך ליה חד זוזא ושקל מנייהו\u0004 \u0005[בעוד שבא\u0006 חזרה \u0005הוצרך לו דינר אחד ולקח מהם]\u0006 מאותם כספים שהביא. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' אמי\u0004 לשאול מה הדין? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מה שהוציא הוציא, ומה שאכל אכל.\u0004 ונמצא שבדינר זה שאכל מן המעות הרי הוא נהנה מהם, ושש מאות שהוציא — הוציא.","\u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לר' אמי: הני מילי היכא דקאכיל פירא\u0004 \u0005[דברים אלה\u0006 היו אמורים \u0005כאשר\u0006 הוא \u0005אוכל\u0006 מ\u0005פירות\u0006 נכסי האשה\u0005],\u0006 \u0003הא קרנא קאכיל\u0004 \u0005[זה\u0006 מן \u0005הקרן אכל]\u0006 \u0003והוצאה היא\u0004 שהוציא בלבד. אמר להם: \u0003אם כן הוה ליה\u0004 \u0005[הרי זה]\u0006 מקרה של \u0003הוציא ולא אכל,\u0004 והלכה היא שאז \u0003ישבע כמה הוציא, ויטול.\u0004","שנינו במשנה שאם הוציא הוצאות ולא אכל כלל — \u0003ישבע כמה הוציא ויטול\u0004 את כל הוצאותיו. \u0003אמר ר' אסי: והוא\u0004 דווקא באופן \u0003שיש שבח\u0004 (רווח ותוספת ערך) בנכסים \u0003כנגד הוצאה.\u0004 ושואלים: \u0003למאי הלכתא\u0004 \u0005[לאיזו הלכה]\u0006 נאמר הדבר? האם כדי להחמיר עליו ולומר שכאשר הרווח פחות אינו נוטל את כל ההוצאה, או שאם השבח מרובה אינו צריך שבועה? \u0003אמר אביי: שאם היה\u0004 ה\u0003שבח יתר על\u0004 ה\u0003הוצאה — נוטל את ההוצאה בלא שבועה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אם כן\u0004 אתה אומר, \u0003אתי לאיערומי\u0004 \u0005[יבוא להערים],\u0006 שבכל מקרה יאמר שהוציא קצת פחות מהשבח, ויקבל סכום זה בלא שבועה ובלא ראיה! \u0003אלא אמר רבא:\u0004 מה שאמר ר' יוסי הרי זה להחמיר עליו ולומר \u0003שאם היתה הוצאה יתירה על השבח — אין לו אלא הוצאה\u0004 כדי \u0003שיעור שבח,\u0004 ולא יותר מזה, \u0003ו\u0004בכל מקרה מה שנוטל, אינו נוטל אלא \u0003בשבועה.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003בעל שהוריד אריסין תחתיו,\u0004 שהשכיר או החכיר להם את נכסי אשתו, \u0003מהו\u0004 דינם? האם \u0003אדעתא\u0004 \u0005[על דעת]\u0006 ה\u0003בעל נחית\u0004 \u0005[ירדו\u0006 לנכסים\u0005]\u0006 ולכן כאשר \u0003איסתליק ליה\u0004 \u0005[הסתלק לו]\u0006 ה\u0003בעל\u0004 מהנכסים, כגון שאכל מהפירות וגירשה, הרי \u0003איסתליקו להו\u0004 \u0005[הסתלקו להם\u0006 ממילא האריסים\u0005]\u0006 ואינם מקבלים שכרם, כיון שבאו מכוחו, \u0003או דלמא אדעתא דארעא נחית וארעא כי קיימא לאריסי קיימא\u0004 \u0005[שמא על דעת הקרקע ירדו, והקרקע כאשר\u0006 היא \u0005עומדת, לאריסים\u0006 היא \u0005עומדת],\u0006 שהם מעבדים את השדה בכל מקרה, ואין זה חשוב מי היה האיש שעשה איתם את ההסכם, ולכן הם נשארים בקרקע?","\u0003מתקיף לה\u0004 \u0005[מקשה על כך],\u0006 על שאלה זו מעיקרה \u0003רבא בר רב חנן: מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 דבר זה \u0003מהיורד לתוך שדה חבירו ונטעה שלא ברשות,\u0004 ש\u0003שמין לו\u0004 את מה שהוציא להשבחת הקרקע ואת מה שהשביח, \u0003וידו על התחתונה,\u0004 שלעולם נוטלים את הסכום הקטן יותר, בין שהוא דמי ההוצאות או השבח, וגם אם נאמר שהאריסים יושבים בקרקע זו שלא ברשות, מדוע לא נדון אריסים אלה כמי שירד לקרקע חבירו שלא ברשות?","ומשיבים: אין להשוות, כי \u0003התם ליכא איניש דטרח\u0004 \u0005[שם,\u0006 כשיורד לשדה בור, \u0005אין אדם\u0006 אחר \u0005שיטרח]\u0006 ולכן יש מקום לומר שיקבל המשקיע בדבר לפחות את הוצאותיו, או את השבח, לפי הפחות שבהם, ואולם \u0003הכא איכא\u0004 \u0005[כאן יש]\u0006 \u0003בעל דטרח\u0004 \u0005[שטורח]\u0006 והאריסים הם כממלאי מקומו בלבד, ואין להם זכות ישיבה בקרקע אלא מכוחו, ולכן יכולה האשה לומר להם שלא הועילו לה כלום במה שעסקו בהשבחת קרקעותיה, שאם לא הם היה עושה זאת הבעל, ואין כל סיבה אם כן שיקבלו דבר, ואף אין להם בקרקעות זכות כלשהי לאחר שנסתלק הבעל.","ושואלים: אם כן \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]\u0006 על בעיה זו? \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: חזינן\u0004 \u0005[רואים אנו]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003בעל\u0004 זה \u0003אריס הוא,\u0004 שיודע בטיב הטיפול בקרקעות ויכול היה לעבדן בעצמו — כאשר \u0003איסתלק ליה\u0004 \u0005[הסתלק לו]\u0006 ה\u0003בעל אסתלקו להו\u0004 \u0005[הסתלקו להם\u0006 גם האריסים\u0005],\u0006 שהרי הם עובדים בשדה רק כממלאי מקומו. \u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 ה\u0003בעל לאו\u0004 \u0005[לא]\u0006 \u0003אריס הוא,\u0004 אם כן נמצא ש\u0003ארעא לאריסי קיימא\u0004 \u0005[הקרקע\u0006 היתה \u0005עומדת לאריסים]\u0006 בין כה וכה, שהרי הבעל לא היה עובד בה, וכיון שצריכה הקרקע לאריסים, אין הם באים מכוחו, ולא הפסידו חלקם.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו: ה\u0003בעל שמכר קרקע\u0004 נכסי מלוג של אשתו \u0003לפירות,\u0004 כלומר, שיעבוד אדם אחר את הקרקע ויקבל את פירותיה, \u0003מהו\u0004 הדין? \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]\u0006 כי \u0003מאי דקני לה אקני\u0004 \u0005[מה שקנוי לו\u0006 הוא \u0005שהקנה\u0006 לאחרים\u0005],\u0006 וכיון שפירות הנכסים הם שלו יכול להקנותם לאחרים, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כי תקינו ליה רבנן\u0004 \u0005[כאשר תיקנו לו חכמים]\u0006 \u0003פירות לבעל\u0004"],["\u0003משום רווח ביתא\u0004 \u0005[רווחת הבית]\u0006 תיקנו לו, וכאשר מביא את הפירות לביתו יש מזונות יתירים בבית, \u0003אבל לזבוני\u0004 \u0005[למכור] —\u0006 \u0003לא\u0004 תיקנו שיהיו שלו?! בפתרון בעיה זו היו שתי דעות, \u0003יהודה מר בר\u0004 \u0005[בן]\u0006 \u0003מרימר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר: מה שעשה, עשוי. רב פפא אמר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: לא עשה ולא כלום.\u0004","\u0003אמר רב פפא: הא\u0004 \u0005[זה]\u0006 שאמר \u0003יהודה מר בר\u0004 \u0005[בן]\u0006 \u0003מרימר לאו\u0004 \u0005[לא]\u0006 \u0003בפירוש אתמר\u0004 \u0005[נאמר],\u0006 ששמע כך את הדברים מרבא, \u0003אלא מכללא אתמר\u0004 \u0005[מכלל\u0006 הדברים \u0005נאמר],\u0006 שהסיק זאת מתוך מעשה שהיה. \u0003דההיא איתתא דעיילה ליה לגברא תרתי אמהתא\u0004 \u0005[שאשה אחת הכניסה לו לבעלה\u0006 בנדונייתה \u0005שתי שפחות],\u0006 \u0003אזל גברא נסיב איתתא אחריתי\u0004 \u0005[הלך האיש נשא אשה אחרת],\u0006 \u0003עייל לה חדא מנייהו\u0004 \u0005[הכניס,\u0006 נתן, \u0005לה,\u0006 לאשתו השניה, \u0005אחת מהן]\u0006 מן השפחות האלה כדי שתשמש אותה.","\u0003אתאי לקמיה\u0004 \u0005[באה\u0006 האשה הראשונה \u0005לפני]\u0006 \u0003רבא, צווחה\u0004 על העוול שנעשה לה ו\u0003לא אשגח\u0004 \u0005[השגיח]\u0006 \u0003בה\u0004 רבא, שאמר שאין לה מקום להתערב בדבר. \u0003מאן דחזא סבר\u0004 \u0005[מי שראה חשב]\u0006 שטעמו של רבא היה \u0003משום\u0004 ש\u0003סבר מה שעשה עשוי,\u0004 שיכול הבעל למכור נכסי מלוג של אשתו ולהשתמש בפירותיהם כרצונו. \u0003ולא היא\u0004 \u0005[ואין הדבר כן],\u0006 אלא כיון שתיקנו חכמים שייהנה הבעל מפירות נכסי האשה שכן יש בכך \u0003משום רווח ביתא\u0004 \u0005[רווחת הבית]\u0006 \u0003והא קא רווח\u0004 \u0005[והרי\u0006 אף באופן כזה יש \u0005רווחה]\u0006 בבית, שהרי בסופו של דבר השפחה הזו עושה מלאכה גם בשביל הבית.","ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003בעל שמכר קרקע\u0004 נכסי מלוג של אשתו לאחר \u0003לפירות — לא עשה ולא כלום.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הלכה זו? \u0003אביי אמר: חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא תכסיף\u0004 (תיפחת, תפגע) הקרקע עצמה במשך הזמן, שמתוך שהקונה רק נוטל ממנה פירות ואין הקרקע שלו, שמא לא יטפל בה כראוי. \u0003רבא אמר: משום\u0004 שאין כאן \u0003רווח ביתא\u0004 \u0005[רווחת הבית].\u0006","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 למעשה אם זה או זה הטעם? ומסבירים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה, כגון שהיתה \u0003ארעא דמקרב למתא\u0004 \u0005[קרקע שקרובה לעיר]\u0006 שיכול לבדוק בכל עת אם מטפלים בקרקע כראוי, \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 שה\u0003בעל אריס הוא\u0004 המעבד בעצמו את הקרקע, אלא שמכר את הנאת הפירות לאחר, והבעל בתור אריס גם הוא מקבל חלק מן הפירות, וכיון שהוא המטפל בקרקע, ידאג שלא תיפסד. \u0003אי נמי, זוזי וקא עביד בהו עיסקא\u0004 \u0005[או גם כן, זוזים,\u0006 כסף שמקבל הבעל בשכר הפירות \u0005ועושה בהם עסק],\u0006 שנמצא שבסופו של דבר יש רווח לבית בכך.","\u0003שומרת יבם\u0004 (אשה שמת בעלה בלא ילדים, והיא עתה ממתינה ליבם שיחלוץ או ייבם אותה) \u0003שנפלו לה נכסים\u0004 בירושה — \u0003מודים בית שמאי ובית הלל שמוכרת\u0004 או \u0003נותנת\u0004 אותם לאחרים, \u0003ו\u0004מה שעשתה \u0003קיים.\u0004","\u0003מתה\u0004 שומרת יבם, \u0003מה יעשו בכתובתה ובנכסים הנכנסין והיוצאין עמה,\u0004 כלומר, בנכסי מלוג שלה? \u0003בית שמאי אומרים:\u0004 כיון שהיא רק שומרת יבם ואינה נשואה ליבם עדיין \u0003יחלקו יורשי הבעל עם יורשי האב\u0004 בכל הרכוש הזה. \u0003ובית הלל אומרים:\u0004 ה\u0003נכסים\u0004 נשארים \u0003בחזקתן, ו\u0004משום כך, \u0003כתובה — בחזקת יורשי הבעל,\u0004 שהרי הם צריכים להוציא משלהם ולתת כתובה, ובינתיים כסף זה הוא בחזקתם, ולא חייבו אותם להוציאו. ואילו \u0003נכסים הנכנסים והיוצאים עמה\u0004 (נכסי מלוג) — \u0003בחזקת יורשי האב\u0004 של האשה, שהרי הם שייכים לאשה.","\u0003הניח אחיו\u0004 המת \u0003מעות\u0004 בתוך נכסיו — \u0003ילקח\u0004 (ייקנה) \u0003בהן קרקע\u0004 שתהיה משועבדת לכתובתה, \u0003והוא,\u0004 האח המייבם אותה, \u0003אוכל\u0004 את \u0003פירות\u0004 הקרקע. וכן אם הניח \u0003פירות התלושין מן הקרקע — ילקח בהן קרקע, והוא,\u0004 האח המייבם אותה, \u0003אוכל פירות.\u0004","אם הניח פירות \u0003המחוברין בקרקע, אמר ר' מאיר: שמין אותן\u0004 את הנכסים \u0003כמה הן יפין\u0004 (שווים) \u0003ב\u0004עוד ה\u0003פירות\u0004 מחוברים להם, \u0003וכמה הן יפין בלא פירות, והמותר,\u0004 כלומר, ההפרש שהוא שווי הפירות — \u0003ילקח בהן קרקע והוא אוכל פירות.\u0004","\u0003וחכמים אומרים: פירות המחוברין בקרקע — שלו\u0004 הם, ואין קונים בהם קרקע אלא היבם אוכלם. ואילו פירות \u0003התלושין מן הקרקע\u0004 שאינם משועבדים לכתובתה — \u0003כל הקודם\u0004 בהם \u0003זכה בהן;\u0004 אם \u0003קדם הוא\u0004 ולקחם — \u0003זכה\u0004 ועושה בהם מה שירצה, ואם \u0003קדמה היא\u0004 — הרי הם כשאר נכסיה ו\u0003ילקח בהן קרקע והוא אוכל פירות.\u0004","לאחר ש\u0003כנסה\u0004 היבם \u0003הרי היא כאשתו לכל דבר,\u0004 ויש רק הבדל אחד: ו\u0003בלבד שתהא כתובתה על נכסי בעלה הראשון.\u0004 שהשעבוד עבור הכתובה שלה הוא מנכסי הבעל הראשון, ולא מנכסי היבם.","\u0003לא יאמר לה\u0004 היבם \u0003\"הרי כתובתיך מונחת על השלחן\",\u0004 שיש סכום כסף מוכן לתשלום זה, \u0003אלא כל נכסיו\u0004 של בעלה הראשון \u0003אחראין לכתובתה\u0004 כל זמן שלא גירש אותה, ויש לה שעבוד עליהם. \u0003וכן\u0004 בכלל: \u0003לא יאמר אדם לאשתו \"הרי כתובתיך מונחת על השלחן\", אלא כל נכסיו אחראין לכתובתה.\u0004","\u0003גירשה\u0004 את שומרת היבם לאחר שכנס אותה — \u0003אין לה\u0004 עוד זכות בשאר הנכסים ואינה נוטלת \u0003אלא כתובה.\u0004 אם \u0003החזירה\u0004 אחר כך לאחר גירושיה — \u0003הרי היא ככל הנשים, ואין לה אלא כתובה בלבד,\u0004 אבל אין לה עוד שעבוד על נכסי בעלה הראשון.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003שומרת יבם שמתה, מי קוברה\u0004 (מי חייב בהוצאות הקבורה)? \u0003יורשי הבעל קברי לה\u0004 \u0005[יורשים אותה]\u0006 משום \u0003דקא ירתי\u0004 \u0005[ש\u0006הם \u0005יורשים]\u0006 את ה\u0003כתובה, או דלמא\u0004 \u0005[שמא]\u0006 \u0003יורשי האב קברי לה, דקא ירתי\u0004 \u0005[קוברים אותה,\u0006 משום \u0005ש\u0006הם \u0005יורשים]\u0006 \u0003נכסים הנכנסין והיוצאין עמה\u0004 (נכסי מלוג)? \u0003אמר רב עמרם: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שומרת יבם שמתה\u0004 —"],["\u0003יורשיה\u0004 שהם \u0003יורשי כתובתה חייבין בקבורתה,\u0004 משמע שחובת קבורתה מוטלת על יורשי הבעל שהם היורשים את הכתובה. \u0003אמר אביי: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 דין זה במקום אחר, ששנינו: \u0003אלמנה ניזונת מנכסי יתומין\u0004 שירשו מהאב \u0003ומעשה ידיה שלהן, ואין\u0004 הם \u0003חייבין בקבורתה. יורשיה יורשי כתובתה חייבין בקבורתה. ו\u0004נברר \u0003איזוהי אלמנה שיש לה שני יורשין,\u0004 שצריך להדגיש שמדובר ביורשי כתובתה דווקא? \u0003הוי אומר: זו שומרת יבם,\u0004 שהיבם הוא יורש את כתובתה.","\u0003אמר רבא: ולימא\u0004 \u0005[ושיאמר\u0006 היבם\u0005]:\u0006 \u0003אח אני יורש.\u0004 כלומר, כתובה זו מגיעה לי מכוח ירושה של אחי, בתורת קרוב, אבל \u0003אשתו אין אני קובר,\u0004 שאין לי כל קשר עימה ואין עלי חובה לקוברה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: משום\u0004 ש\u0003באין עליו משני צדדין,\u0004 בשתי טענות מתחלפות: \u0003אם\u0004 את \u0003אחיו\u0004 הוא \u0003יורש\u0004 — הרי הוא צריך לרשת לא רק את זכויותיו אלא גם את חובותיו, ולכן \u0003יקבור את אשתו.\u0004 ו\u0003אם אינו קובר את אשתו\u0004 של אחיו, שאינו רוצה לבוא במקום אחיו — אם כן \u0003יתן כתובתה,\u0004 שלא יירש אותה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003הכי קא אמינא\u0004 \u0005[כך אני אומר],\u0006 כלומר, כך הוא תוכן הטענה: \u0003אח אני יורש, את אשתו אין אני קובר,\u0004 משום שעלי אין חובה זו מוטלת. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003משום\u0004 תביעת \u0003כתובה — לא ניתנה כתובה לגבות מחיים.\u0004 שהרי אין כתובה ניתנת אלא כאשר מת הבעל, וכיון שאני במקום הבעל (שהרי מוכן הוא לייבמה) — לא היתה זכאית לכתובה, ולכן אין לי שום התחייבות כלפיה. הנחה זו שלא ניתנה כתובה להגבות מחיים נובעת מדקדוק בלשון הכתובה, שנאמר בה \"כשתנשאי לאחר תטלי כתובה זו\", ומכאן מובן שכאשר אין האשה יכולה להינשא לאחר (כאשר הבעל חי) — אין הכתובה מגיעה לה.","אולם מקשים: \u0003מאן שמעת ליה\u0004 \u0005[מי שמעת אותו]\u0006 \u0003דאית ליה\u0004 \u0005[שיש לו,\u0006 שסבור הוא\u0005]\u0006 שיש \u0003מדרש כתובה,\u0004 כלומר, שאפשר ללמוד מדיוק הלשון שבכתובה כדרך שמדייקים בלשונות של תורה — \u0003בית שמאי\u0004 הם (במסכת יבמות קיז, א). \u0003ו\u0004הרי \u0003שמעינן להו\u0004 \u0005[שמענו אותם]\u0006 את \u0003בית שמאי דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]\u0006 בכלל: \u0003שטר העומד לגבות כגבוי דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 ואף כאן נחשב כאילו גבתה כבר את שטר הכתובה, ואינו יכול לומר \"אח אני יורש\"!","וראיה לדבר \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מתו בעליהן\u0004 של נשים שהבעל קינא להן שחשד שהן סוטות \u0003עד שלא שתו\u0004 מן המים המרים, ולא התברר אם סטו או לא סטו — \u0003בית שמאי אומרים: נוטלות כתובה ולא שותות, ובית הלל אומרים: או שותות או לא נוטלות כתובה.\u0004","ותחילה תוהים על הלשון: \u0003או שותות?!\u0004 כיצד יכולות הן לשתות? הרי \u0003\"והביא האיש את אשתו אל הכהן\"\u0004 (במדבר ה, טו), \u0003אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 \u0003וליכא\u0004 \u0005[ואין כאן]\u0006 איש! \u0003אלא\u0004 כך צריך להבין את דברי בית הלל: \u0003מתוך שלא שותות,\u0004 שהרי אין כאן בעל היכול להשקותן — \u0003לא נוטלות כתובה\u0004 מפני הספק, שמא זנו.","\u0003בית שמאי אומרים: נוטלות כתובה ולא שותות. ו\u0004לכאורה \u0003אמאי\u0004 \u0005[מדוע]\u0006 נוטלות? הלא \u0003ספיקא\u0004 \u0005[ספק]\u0006 \u0003הוא: ספק זנאי\u0004 \u0005[זנתה]\u0006 \u0003ספק לא זנאי\u0004 \u0005[זנתה],\u0006 שאם זנתה — אין לה כתובה, ואם כן זכות האשה בכתובה אינה בתורת ודאי, \u0003ו\u0004בכל זאת לשיטת בית שמאי \u0003קאתי\u0004 \u0005[באה]\u0006 טענת \u0003ספק\u0004 של האשה \u0003ומוציא מידי ודאי\u0004 של היורשים, שהרי הם זכאים ללא ספק לרשת את אביהם.","ולכן צריך לומר כי \u0003קסברי\u0004 \u0005[סבורים]\u0006 \u0003בית שמאי\u0004 ש\u0003שטר העומד לגבות\u0004 (להיגבות) — \u0003כגבוי דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 ומשום כך רואים את דמי הכתובה כאילו היו כבר בחזקת האשה, והיורשים שאינם רוצים לשלם הם הבאים להוציא ממנה, ומשום הספק אינם יכולים להוציא ממנה.","ושואלים: גם אם אין דורשים את לשון הכתובה, הרי פשט לשון הכתובה מורה שאינה יכולה לגבות כתובתה בחיי היבם, שכן \u0003והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 שיתקיים האמור בכתובה: \u0003\"כשתנשאי לאחר תטלי מה שכתוב ליכי\u0004 (לך) \u0003\", וליכא\u0004 \u0005[ואין כאן],\u0006 שהרי קודם חליצה לא יכלה היבמה להינשא לאחר ואין לה איפוא כל זכות בכתובה, ואם כן איך באים על היבם משני צדדים להפקיע ממנו את הכתובה אם אינו קוברה?","\u0003אמר רב אשי: יבם נמי\u0004 \u0005[גם כן]\u0006 \u0003כאחר דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006 ודינה כאילו עמדה להינשא לאחר, ויש לה איפוא זכות בכתובה. עד כאן היה המשא והמתן בין אביי ורבא כאשר היו שניהם יחד ועסקו בסוגיה זו.","לאחר זמן \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רבא לאביי ביד רב שמעיה בר זירא\u0004 את הקושיה הבאה בענין זה: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003נתנה כתובה\u0004 של יבמה \u0003לגבות מחיים?\u0004","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אבא אומר שאלתי את סומכוס:\u0004 יבם \u0003הרוצה שימכור בנכסי אחיו\u0004 המת לאחר שכנס את אלמנתו ואינו יכול לעשות זאת משום שכל נכסי האח משועבדים לכתובתה, \u0003כיצד הוא עושה?\u0004 אמר לו: \u0003אם כהן הוא\u0004 שאינו יכול לגרש את האשה ולהחזירה — \u0003יעשה סעודה\u0004 לאשתו, \u0003ו\u0004בתוך הסעודה \u0003יפייס\u0004 אותה שתמחול על חלק מזכותה לנכסי האח האחראים לכתובתה, ותרשה לו למכור אותם. ו\u0003אם ישראל הוא\u0004 שמותר לו לחזור ולשאת את גרושתו כל עוד לא נישאה לאחר, יש לו דרך אחרת — \u0003מגרש\u0004 את היבמה \u0003בגט,\u0004 ואז אינו חייב לה אלא את דמי כתובה, ואין לה עוד שעבוד על שאר הנכסים, ובינתיים ימכרם \u0003ויחזיר\u0004 אותה לאחר מכן, ובנישואין אלה אין לה כל שיעבוד על נכסי בעלה הראשון."],["\u0003ואי סלקא דעתין\u0004 \u0005[ואם עולה על דעתנו]\u0006 לומר ש\u0003נתנה כתובה לגבות מחיים,\u0004 אם כן למה לו כל זה? \u0003נייחד\u0004 \u0005[שייחד]\u0006 \u0003לה\u0004 חלק מן הנכסים כדי \u0003שיעור כתובה, והשאר ליזבין\u0004 \u0005[שימכור]!\u0006 ענה לו: \u0003ולטעמיך, ולותבה ממתניתין\u0004 \u0005[ולטעמך,\u0006 לשיטתך, עד שאתה מקשה מברייתא, \u0005שיקשה\u0006 קושיה זו \u0005ממשנתנו].\u0006 ששנינו: \u0003לא יאמר לה\u0004 ליבמה \u0003הרי כתובתיך מונחת ליך\u0004 (לך) \u0003על השלחן, אלא כל נכסיו אחראין לכתובתה,\u0004 ומדוע לא ייחד לה שיעור כתובה וימכור את השאר?!","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 במשנה \u0003עצה טובה קא משמע לן\u0004 \u0005[השמיע לנו],\u0006 שאין המשנה אומרת שאינו יכול לעשות כן, אלא זוהי עצה טובה שלא יעשה כן לכתחילה, כדי שלא יאבד הסכום המיועד לכתובה ותצטרך כתובה חדשה. \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 שזו רק בגדר עצה טובה, אם כן \u0003סיפא דקתני\u0004 \u0005[סוף\u0006 המשנה \u0005ששנה\u0006 שם\u0005]:\u0006 \u0003וכן לא יאמר אדם לאשתו \"הרי כתובתיך מונחת ליך על השלחן\", אלא כל נכסיו אחראין לכתובת אשתו\u0004 — וכי \u0003אי בעי ליה לזבוני, הכא נמי דלא מצי מזבין\u0004 \u0005[אם רוצה הוא למכור, כאן גם כן אינו יכול למכור]?!\u0006 \u0003אלא\u0004 ודאי \u0003עצה טובה קא משמע לן\u0004 \u0005[השמיע לנו],\u0006 אם כן אפשר לומר כי \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 ביבמה רק \u0003עצה טובה קא משמע לן\u0004 \u0005[השמיע לנו].\u0006","ושואלים: ו\u0003אלא\u0004 אם כן חוזרת קושיה זו, ומה שאמר \u0003ר' אבא\u0004 בשם סומכוס \u0003קשיא\u0004 \u0005[קשה]\u0006 מדוע מגרשה כאשר יכול לייחד לה שיעור כתובתה? ומשיבים: הלכה זו שאמר \u0003ר' אבא נמי לא קשיא\u0004 \u0005[גם כן אינה קשה],\u0006 שהטעם שעושה כן אינו משום שאי אפשר לייחד שיעור כתובה, אלא \u0003משום איבה.\u0004 שאם מייחד לה רק חלק מסויים מן הנכסים לשם כתובתה, הריהי רואה בכך איום מתמיד ורצון להפטר ממנה, והוא גרוע יותר מאשר מגרשה ומחזירה, שאז היא רואה שעשה זאת רק כדי למכור מהנכסים.","מסופר: \u0003ההוא גברא\u0004 \u0005[אדם אחד]\u0006 ש\u0003נפלה ליה\u0004 \u0005[לו,\u0006 לפניו\u0005]\u0006 \u0003יבמה\u0004 לייבום \u0003ב\u0004עיר \u0003פומבדיתא, בעי אחוה למפסלה לה בגיטא מיניה\u0004 \u0005[רצה אחיו לפסול אותה בגט ממנו],\u0006 שכן לפי הדין אם אחד היבמים נותן גט ליבמה, שוב אינה יכולה להתייבם גם לאח אחר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 האח שרצה לייבם: \u0003מאי דעתיך\u0004 \u0005[מה דעתך]\u0006 שאתה רוצה לעשות זאת — \u0003משום נכסי\u0004 \u0005[הנכסים]\u0006 שאתה מקנא בי בגללם, שכן האח המייבם את האשה מקבל גם את נכסי האח המת, ואילו כאשר אחד מן האחים חולץ או נותן גט — כל האחים מתחלקים בהם בשווה. \u0003אנא בנכסי פליגנא\u0004 \u0005[אני בנכסים אחלוק]\u0006 \u0003לך,\u0004 איתך, והנח לי ליבם. ולבסוף, כאשר כנס את האשה לא רצה לתת דבר לאחיו והגיע הדבר לבית הדין.","\u0003אמר רב יוסף: כיון דאמור רבנן\u0004 \u0005[שאמרו חכמים]\u0006 ש\u0003לא ליזבין\u0004 \u0005[ימכור]\u0006 בנכסי שומרת יבם לפני שכנסה, \u0003אף על גב דזבין\u0004 \u0005[אף על פי שמכר] —\u0006 \u0003לא הוה זביניה זביני\u0004 \u0005[אין מכירתו מכירה],\u0006 וכן הבטחתו לתת חצי מן הנכסים לאחיו (שהיא לענין זה כמכר) אינה חלה כלל. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מי שמת והניח שומרת יבם, והניח נכסים במאה מנה, אף על פי שכתובתה\u0004 של אותה יבמה \u0003אינה אלא מנה — לא ימכור\u0004 היבם מנכסיו כלל, \u0003שכל נכסיו\u0004 של המת \u0003אחראין לכתובתה.\u0004 וכיון שאסרו עליו חכמים למכור, גם אם מכר — אין מכירתו מכירה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003וכל היכא דאמור רבנן\u0004 \u0005[מקום שאמרו חכמים]\u0006 ש\u0003לא ליזבין\u0004 \u0005[ימכור]\u0006 האם \u0003אף על גב דזבין לא הוה זביניה זביני\u0004 \u0005[אף על פי שמכר אין מכירתו מכירה]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 לעיל בענין אחר: אשה שנפלו לה נכסים לאחר שנתארסה ורוצה למוכרם או ליתנם במתנה — \u0003בית שמאי אומרים תמכור, ובית הלל אומרים לא תמכור, אלו ואלו מודים שאם מכרה\u0004 או \u0003נתנה\u0004 אותם במתנה — מה שעשתה \u0003קיים.\u0004 הרי שגם לדעת בית הלל למרות שמכרה באיסור — המכר קיים! וערער איפוא אביי על פסק דינו של רב יוסף. \u0003שלחוה,\u0004 את הבעיה, \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003ר' חנינא בר פפי, שלחה,\u0004 שלח תשובה: הלכה \u0003כ\u0004דעת \u0003רב יוסף.\u0004","\u0003אמר אביי\u0004 כנגד זה: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003ר' חנינא בר פפא כיפי\u0004 \u0005[נזמים]\u0006 \u0003תלה לה\u0004 וכי יפה את קביעתו? הלא לא נימק את דבריו ולא הוסיף דבר, ומה שפסק שהלכה כרב יוסף, בלא טעם מסויים פסק כן, ואין אני מקבל את דבריו. \u0003שלחוה,\u0004 את השאלה, \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב מניומי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחומי, שלחה,\u0004 שלח תשובה וכתב: הלכה \u0003כ\u0004דעת \u0003אביי ואי אמר\u0004 \u0005[ואם יאמר]\u0006 \u0003בה רב יוסף טעמא אחרינא\u0004 \u0005[טעם אחר]\u0006 \u0003שלחו לי\u0004 את הטעם ואשוב ואעיין בדבר.","\u0003נפק\u0004 \u0005[יצא]\u0006 \u0003רב יוסף דק ואשכח\u0004 \u0005[דקדק\u0006 ועיין במשניות \u0005ומצא\u0006 מקור לדבריו\u0005];\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהיה נושה באחיו\u0004 ממון, \u0003ומת\u0004 האח המלווה \u0003והניח\u0004 אשה \u0003שומרת יבם, לא יאמר\u0004 האח היבם: \u0003הואיל ושאני יורש\u0004 ברכוש של אחי מכוח היבמה — \u0003החזקתי\u0004 גם בחוב, ואינני צריך להחזיר אותו ליורשים האחרים, \u0003אלא מוציאין מיבם\u0004 את מה שהיה חייב לאחיו, \u0003ויקח בהן\u0004 בסכום הזה \u0003קרקע\u0004 עבור כתובת האשה \u0003והוא אוכל פירות.\u0004 ומכאן ראיה לשיטתו שאין היבם יכול למכור את נכסי אחיו המת כל עוד עומדת התחייבותו לאחיו האחר, או להחזיק בחוב שהיה חייב לאחיו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003דלמא דטבא ליה עבדו ליה\u0004 \u0005[שמא\u0006 מה \u0005שטוב לו עשו לו],\u0006 כלומר, מה שאמרו לו שיקנה קרקע בכסף זה ויאכל פירות, הוא רק בגדר של עצה טובה, כיצד ינהג בכסף שנפל לידו שלא יאבד כסף זה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: ה\u0003תנא תני\u0004 \u0005[שנה]\u0006 \u0003מוציאין,\u0004 כלומר, בעל כורחו, \u0003ואת אמרת דטבא ליה עבדו ליה\u0004 \u0005[ואתה אומר\u0006 שמה \u0005שטוב לו עשו לו]?\u0006 שהרי מן הלשון משמע שהוא ענין של כפייה, ולא ענין של עצה טובה.","\u0003הדור\u0004 \u0005[חזרו]\u0006 ו\u0003שלחוה\u0004 את התשובה הזו \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב מניומי בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחומי. אמר להו\u0004 \u0005[להם]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב יוסף בר מניומי אמר רב נחמן:\u0004 ברייתא \u0003זו אינה משנה,\u0004 אינה מקובלת כברתסמכא ואין להביא ממנה ראיה.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אנו שוללים את מהימנותה של ברייתא זו לגמרי? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דהוו להו מטלטלי\u0004 \u0005[שהרי הם\u0006 הכספים שהוא חייב נחשבים \u0005מטלטלים]\u0006 שהרי אין הכסף הזה קיים כאן, \u0003ומטלטלי\u0004 \u0005[והמטלטלים]\u0006 \u0003לכתובה לא משעבדי\u0004 \u0005[משתעבדים],\u0006 שאין משתעבדים לחוב הכתובה אלא קרקעות בלבד — טענה זו אינה מבטלת את הברייתא, שהרי אפשר לומר כי \u0003דלמא\u0004 \u0005[שמא]\u0006 כשיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר\u0004 בכלל: \u0003מטלטלי משעבדי\u0004 \u0005[מטלטלים משתעבדים]\u0006 \u0003לכתובה.\u0004","\u0003ואלא\u0004 הטעם לפקפק בברייתא הוא אחר — \u0003משום דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]\u0006 \u0003לה,\u0004 ליבמה: \u0003את לאו\u0004 \u0005[לא]\u0006 \u0003בעלת דברים דידי\u0004 \u0005[שלי]\u0006 \u0003את,\u0004 כלומר, לפי שעה אין בינינו כל מקום להתדיינות, ואין את צד בנושא זה, שאיני חייב את הכסף לך, אלא כיון שמאחי לוויתי — לאחי נתחייבתי. ואין היא יכולה לבוא אליו בתביעה שהכסף משועבד לכתובתה."],["\u0003דלמא\u0004 \u0005[שמא]\u0006 כשיטת \u0003ר' נתן היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' נתן אומר: מנין ל\u0004מי שהיה \u0003נושה בחבירו מנה\u0004 (מאה זוז) שהוא חייב לו, \u0003וחבירו\u0004 נושה \u0003בחבירו, מנין שמוציאין מזה,\u0004 מן הלווה האחרון, \u0003ונותנין לזה\u0004 למלווה הראשון, ואין צורך שיתבעו זה את זה, אלא אפשר לקצר את התהליך — \u0003תלמוד לומר: \"ונתן לאשר אשם לו\"\u0004 (במדבר ה, ז), כלומר, שהלווה נותן למי שבעל החוב שלו חייב לו (\"אשם לו\"), ואף על פי שלא התחייב לו במישרין, מכל מקום הרי הוא צד בענין. והברייתא יכולה איפוא להיות מוסברת כשיטה זו, שכיון שהאח הוא בעל חוב לבעלה ובעלה חייב לה את תשלום כתובתה, הרי מדינו של ר' נתן מוטלת חובת תשלום חוב כתובתה במישרין על האח.","\u0003אלא,\u0004 הטעם לשלילת הברייתא הוא אחר: \u0003לא אשכחן\u0004 \u0005[מצאנו]\u0006 \u0003תנא\u0004 ש\u0003מחמיר תרי חומרי\u0004 \u0005[שתי חומרות]\u0006 אלה \u0003בכתובה, אלא אי\u0004 \u0005[או]\u0006 \u0003כ\u0004חומרת \u0003ר' מאיר\u0004 שמטלטלים משתעבדים לכתובה \u0003אי\u0004 \u0005[או]\u0006 \u0003כ\u0004חומרת \u0003ר' נתן,\u0004 אבל אין מי שמצרף את שתי השיטות יחד. ואילו ברייתא זו אין להסבירה אלא בצירוף השיטות יחד, ומשום כך יש לדחותה ולומר שאיננה מהימנה.","\u0003אמר רבא: אם כן, היינו דשמענא ליה\u0004 \u0005[זהו ששמעתי אותו]\u0006 את \u0003אביי\u0004 ש\u0003אמר: \"זו אינה משנה\", ולא ידענא מאי\u0004 \u0005[ידעתי מה]\u0006 \u0003היא\u0004 ומה טעם אינה משנה, ועכשיו יודע אני מה הענין.","בדומה לכך מסופר: \u0003ההוא גברא\u0004 \u0005[איש אחד]\u0006 ש\u0003נפלה ליה\u0004 \u0005[לו,\u0006 לפניו\u0005]\u0006 לייבום \u0003יבמה ב\u0004עיר \u0003מתא מחסיא. בעא אחוה למיפסלה בגיטא מיניה\u0004 \u0005[רצה אחיו לפסול אותה בגט ממנו],\u0006 שלא יוכל לכונסה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 היבם: \u0003מאי דעתיך\u0004 \u0005[מה דעתך],\u0006 מדוע אתה חושב כך, \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום נכסי\u0004 \u0005[הנכסים]\u0006 של האח המת — \u0003אנא בנכסי פליגנא\u0004 \u0005[אני בנכסים אחלוק]\u0006 \u0003לך,\u0004 איתך. \u0003אמר ליה\u0004 \u0005[לו]\u0006 האח: \u0003מסתפינא דעבדת\u0004 \u0005[מפחד אני שתעשה]\u0006 \u0003לי כדעביד\u0004 \u0005[כמו שעשה]\u0006 \u0003פומבדיתאה רמאה\u0004 \u0005[הפומבדיתאי,\u0006 בן העיר פומבדיתא \u0005הרמאי]\u0006 במעשה שהזכרנו שהיה בפומבדיתא, שהבטיח לחלוק, ולבסוף חזר בו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 היבם: \u0003אי בעית\u0004 \u0005[אם רוצה אתה] —\u0006 \u0003פלוג\u0004 \u0005[חלוק]\u0006 \u0003לך מהשתא\u0004 \u0005[מעכשיו],\u0006 כלומר, אני מוכן שתיקח כבר עכשיו, אף כי הקנין לא יחול אלא לאחר שאכנוס את היבמה.","\u0003אמר מר בר רב אשי: אף על גב דכי אתא\u0004 \u0005[אף על פי שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן: האומר לחבירו \"לך ומשוך פרה זו ולא תהיה קנויה לך אלא לאחר שלשים יום\",\u0004 הרי על ידי משיכה זו \u0003לאחר שלשים יום קנה, ואפילו\u0004 הפרה \u0003עומדת\u0004 אז, לאחר שלושים הימים \u0003באגם,\u0004 באחו, במקום שאינו שייך לקונה הפרה, וזאת מהטעם כי המשיכה של עכשיו מועילה לאחר זמן, מכל מקום יש להבדיל בין המקרים:","\u0003התם\u0004 \u0005[שם]\u0006 במשיכת הפרה — הלא כיון ש\u0003בידו\u0004 של המוכר היא, ובאפשרותו למסור אותה כבר עכשיו, יכול גם לדחות את חלות הקנין עד לאחר זמן. אבל \u0003הכא לאו\u0004 \u0005[כאן לא]\u0006 \u0003בידו\u0004 האפשרות לחלוק את הנכסים, שהרי עדיין לא ייבם ואין נכסי האח שייכים לו, ואינו יכול להקנותם כלל עכשיו.","לגופם של דברי ר' יוחנן שואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן:\u0004 האומר \"משוך פרה ותהיה קנויה לך לאחר שלושים יום\" — \u0003לא קני\u0004 \u0005[קנה]!\u0006 והרי זו סתירה בדברי ר' יוחנן עצמו. ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[\u0006מקרה \u0005זה],\u0006 שקנה, הוא דווקא באופן ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"קני\u0004 \u0005[קנה]\u0006 \u0003מעכשיו\",\u0004 שכאשר יעברו שלושים יום תהיה קנויה לך מעכשיו, ואילו \u0003הא\u0004 \u0005[זה]\u0006 שאינו קונה, הרי זה באופן ש\u0003לא אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"קני\u0004 \u0005[קנה]\u0006 \u0003מעכשיו\",\u0004 ואם לא חלה תחילת הקנין מעכשיו, שוב אינה יכולה לחול לאחר זמן.","\u0003בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 \u0003מעולא\u0004 שאלה זו: אם \u0003יבם\u0004 אשה \u0003ואחר כך חילק\u0004 בנכסים, שהבטיח לחלק עם אחיו, \u0003מהו?\u0004 אמר להם: \u0003לא עשה ולא כלום.\u0004 ועוד שאלו: \u0003חילק\u0004 בנכסים \u0003ואחר כך יבם מהו?\u0004 ענה להם: \u0003לא עשה ולא כלום.\u0004","על סגנון הדברים הללו \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב ששת: השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 אם \u0003יבם ואחר כך חילק\u0004 כאשר כבר היו הנכסים ברשותו, אמר להם עולא ש\u0003לא עשה ולא כלום,\u0004 אם כן כאשר \u0003חילק ואחר כך יבם מבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שאין למעשה זה תוקף, ומה המשיכו לשאול?! ומשיבים: עולא לא נשאל שתי שאלות אלה בבת אחת אלא \u0003שני מעשים\u0004 נפרדים \u0003הוו\u0004 \u0005[היו]\u0006 שבאו לפני עולא ועל כל אחד ענה לעצמו.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ריש לקיש: בין יבם ואחר כך חילק, בין חילק ואחר כך יבם — לא עשה ולא כלום.\u0004 ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 למעשה היא: \u0003לא עשה ולא כלום.\u0004","עתה חוזרים לפירוש המשנה. שנינו בה, \u0003וחכמים אומרים:\u0004 אם הותיר האח המת \u0003פירות המחוברים לקרקע —\u0004 הרי הם \u0003שלו,\u0004 של היבם. ומקשים: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003כל נכסיו אחראין וערבאין\u0004 \u0005[וערבים]\u0006 \u0003לכתובתה! אמר ריש לקיש: תני\u0004 \u0005[שנה]\u0006 ותקן כך: פירות המחוברים — \u0003שלה.\u0004","עוד שנינו במשנה: \u0003כנסה,\u0004 היבם את אשת אחיו המת — \u0003הרי היא כאשתו.\u0004 ושואלים: \u0003למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 נאמר הדבר? \u0003אמר ר' יוסי בר' חנינא: לומר שמגרשה בגט ו\u0004כן אם אינו כהן אף \u0003מחזירה\u0004 אם רוצה בכך לאחר שגירשה ואין בכך איסור. ושואלים: \u0003מגרשה בגט פשיטא\u0004 \u0005[פשוט],\u0006 וכי באיזו דרך אחרת יגרשנה?","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003\"\u0004ולקחה לו לאשה \u0003ויבמה\"\u0004 (דברים כה, ה) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה],\u0006 \u0003ועדיין\u0004 תורת \u0003יבומין הראשונים עליה\u0004 ודינה ככל יבמה, ולכן \u0003לא תיסגי\u0004 \u0005[יספיק]\u0006 \u0003לה\u0004 לצאת \u0003בגט אלא\u0004 תצא \u0003בחליצה\u0004 עם הגט, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין צורך בחליצה, אלא כיון שכנסה דינה ככל אשה ויכול לפוטרה בגט בלבד.","על מה שאמר ר' יוסי בר' חנינא בפירוש דברי המשנה שמוציאה ו\u0003מחזירה\u0004 אם רוצה, תוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שרשאי להחזירה!"],["\u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי את ה\u0003מצוה דרמא רחמנא עליה\u0004 \u0005[שהטילה התורה עליו]\u0006 הלא \u0003עבדה\u0004 \u0005[עשה אותה]\u0006 על ידי הייבום, \u0003ו\u0004כיון שגירשה \u0003השתא תיקום עליה\u0004 \u0005[עכשיו תעמוד עליו\u0006 שוב\u0005]\u0006 \u0003באיסור אשת אח\u0004 כפי שהיתה קודם לכן, לפני שחלה עליו מצוות היבום, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאינו כן, ומכיון שייבמה פקע ממנה איסור אשת אח לגמרי.","ושואלים לגופו של דבר: \u0003ואימא הכי נמי\u0004 \u0005[ואמור שכך הוא גם כן]\u0006 שבאמת יחזור עליה איסור אשת אח! ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ולקחה לו לאשה\"\u0004 (דברים כה, ה), לומר: \u0003כיון שלקחה — נעשית כאשתו\u0004 גמורה, לכל ענין.","שנינו במשנה: \u0003בלבד שתהא\u0004 חובת פרעון \u0003כתובתה\u0004 של היבמה \u0003על נכסי בעלה הראשון.\u0004 ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003אשה הקנו לו מן השמים,\u0004 שכיון שלא הוא בחר אותה, אלא היא נופלת לפניו מכוח מצוות התורה, אף אין עליו חובה לייחד לה כתובה משלו, וסומך על הכתובה שנתן אחיו.","ומוסיפים: \u0003ואי לית\u0004 \u0005[ואם אין]\u0006 \u0003לה\u0004 כתובה \u0003מראשון,\u0004 וכגון שלא היו לו נכסים, \u0003אית\u0004 \u0005[יש]\u0006 \u0003לה משני\u0004 מאותו טעם שנתנו לכתובת אשה בכלל: \u0003כדי שלא תהא קלה בעיניו להוציאה.\u0004","שנינו במשנה: \u0003לא יאמר לה\u0004 היבם ליבמה \u0003\"הרי כתובתיך\u0004 מונחת על השולחן \u0003\",\u0004 וכן לא יאמר אדם כן לאשתו, אלא כל נכסיו אחראים לכתובתה. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 לשון \u0003\"וכן\"\u0004 שייכת כאן? הרי לכאורה מדובר באותו דין עצמו!","ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 ביבמה יש לומר כן משום ש\u0003לא כתב לה\u0004 היבם כתובה, וממילא אף לא כתב לה שכל הנכסים \u0003\"דקנאי ודקנינא\"\u0004 \u0005[\"שקניתי ושאקנה\"]\u0006 משועבדים לכתובה, ולכן אמרו שאינו יכול לומר לה כך, \u0003אבל הכא\u0004 \u0005[כאן\u0006 באשת איש\u0005]\u0006 ש\u0003כתב לה\u0004 כתובה ובה כתוב במפורש \u0003\"דקנאי ודקנינא\"\u0004 \u0005[\"שקניתי ושאקנה\"],\u0006 ואם כן \u0003אימא סמכה\u0004 \u0005[אמור שסומכת]\u0006 \u0003דעתה\u0004 על מה שמייחד לה, ואין צורך באחריות נכסים שלימה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדבר כן.","שנינו במשנה: אם כנסה היבם ולאחר מכן \u0003גרשה — אין לה אלא כתובתה\u0004 ושוב אין נכסי בעלה הראשון משועבדים לה, ויכול למוכרם. ומדייקים: \u0003גרשה — אין\u0004 \u0005[כן],\u0006 \u0003לא גרשה — לא, קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 איפוא התנא ברמז \u0003כ\u0004דברי \u0003ר' אבא\u0004 בברייתא (לעיל כתובות פא, א), שאין דרך שתהיה לו שליטה גמורה בכל הנכסים אלא כאשר מגרש אותה.","עוד שנינו במשנה: \u0003החזירה\u0004 לאחר שגירשה — \u0003הרי היא ככל הנשים, ואין לה אלא כתובתה\u0004 הראשונה שנתן לה בעלה הראשון. ושואלים: \u0003החזירה מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בכך: הלא כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 בענין \u0003המגרש את האשה ומחזירה\u0004 \u0003על מנת כתובה ראשונה\u0004 הוא \u0003מחזירה,\u0004 ואינו צריך לכתוב לה כתובה חדשה! ומדוע צריך להדגיש דין זה ביבמה?","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003אשתו הוא דאיהו\u0004 \u0005[שהוא]\u0006 \u0003כתב לה כתובה מיניה\u0004 \u0005[ממנו]\u0006 ולכן כאשר הוא מחזיר אותה נעשה הדבר על דעת כתובה ראשונה, \u0003אבל יבמתו\u0004 ש\u0003לא איהו\u0004 \u0005[הוא]\u0006 \u0003כתב לה\u0004 כתובה אלא אחיו, \u0003היכא\u0004 \u0005[במקום]\u0006 ש\u0003גרשה ואהדרה\u0004 \u0005[והחזירה]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 שתהא \u0003כתובתה מיניה\u0004 \u0005[ממנו],\u0006 שיכתוב לה הוא עצמו כתובה חדשה מנכסיו שלו, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין צורך בדבר.","כיון שהזכרנו פה פרטי דיני כתובות, מביאים את ההלכה העיקרית. \u0003אמר רב יהודה: בראשונה היו כותבין לבתולה מאתים\u0004 זוז \u0003ולאלמנה מנה\u0004 (מאה זוז), והיו תובעים שיחזיקו את כסף הכתובה בכספים בפועל, \u0003והיו\u0004 אנשים \u0003מזקינין ולא היו נושאין נשים,\u0004 שלא כל אדם יכול היה לצבור סכום זה בכסף, \u0003עד שבא שמעון בן שטח ותיקן\u0004 שאינו צריך לתת כסף בפועל, אלא ש\u0003כל נכסיו אחראין לכתובתה.\u0004","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנינו\u0006 בברייתא \u0005גם כן כך]:\u0006 \u0003בראשונה היו כותבין לבתולה מאתים ולאלמנה מנה, והיו מזקינין ולא היו נושאין נשים,\u0004 שחששו הנשים שמא יתבזבז כסף הכתובה או יאבד, ואין להן בטחון בגבייתה, ולכן \u0003התקינו שיהיו מניחין אותה\u0004 את דמי הכתובה \u0003בבית אביה\u0004 ואז היתה מובטחת שישמר כסף זה. \u0003ועדיין\u0004 היה הדבר גורם לתקלה אחרת: \u0003כשהוא כועס עליה,\u0004 על אשתו, \u0003אומר לה: \"לכי אצל כתובתיך\"\u0004 והיו ממהרים להתגרש, \u0003התקינו שיהיו מניחין אותה בבית חמיה\u0004 (כלומר, בבית בעלה), ו\u0003עשירות עושות אותה,\u0004 את כסף הכתובה, \u0003קלתות\u0004 (סלים) \u0003של כסף ושל זהב, עניות היו עושות אותה עביט של מימי רגלים,\u0004 משום שהיה זה סכום מועט ולא היה די אלא לכלי קטן ולא חשוב,","","\u0003ועדיין כשכועס עליה אומר לה \"טלי כתובתיך וצאי\". עד שבא שמעון בן שטח ותיקן\u0004 שאינו נותן לה את דמי הכתובה בפועל, אלא \u0003שיהא כותב לה: כל נכסי אחראין לכתובתה,\u0004 ואין הכתובה מיוחדת במקום או בחפץ מסויים, וכיון שאין מעות הכתובה מיוחדות ונשמרות, אם רוצה לגרשה צריך למכור מרכושו, ובתוך כך נמלך בדעתו ומתחרט.",""],["\u0003הכותב לאשתו\u0004 תנאי מיוחד: \u0003\"דין ודברים אין לי בנכסיך\",\u0004 שמתנה אתה שהוא מוותר על זכותו בנכסיה — בכל זאת \u0003הרי זה אוכל פירות\u0004 הנכסים \u0003בחייה, ואם מתה — יורשה. אם כן,\u0004 כיון שבכל זאת יש בידו את כל הזכות הזו \u0003למה,\u0004 מה המשמעות, במה ש\u0003כתב לה \"דין ודברים אין לי בנכסיך\"?\u0004 — המשמעות המעשית של תנאי זה היא, \u0003שאם מכרה\u0004 או \u0003נתנה\u0004 מנכסיה לאחר — מה שעשתה \u0003קיים\u0004 ואינו יכול להוציא.","ואם \u0003כתב לה \"דין ודברים אין לי בנכסיך ובפירותיהן\" — הרי זה אינו אוכל פירות בחייה, ואם מתה — יורשה,\u0004 שהרי לא סילק את עצמו מן הירושה. \u0003ר' יהודה אומר: לעולם,\u0004 אף על פי שויתר על זכותו בפירות עצמם, מכל מקום נעשים הפירות עצמם כנכסי מלוג שלה ולכן הריהו \u0003אוכל פירי פירות.\u0004 ואינו מסולק לגמרי מאכילת פירות \u0003עד שיכתוב לה \"דין ודברים אין לי בנכסיך ובפירותיהן ובפירי פירותיהן עד עולם\",\u0004 כלומר, פירי פירי פירות וכן הלאה.","\u0003כתב לה \"דין ודברים אין לי בנכסיך ובפירותיהן ובפירי פירותיהן בחייך ובמותך\" — אינו אוכל פירות בחייה, ואם מתה אינו יורשה. רבן שמעון בן גמליאל אומר: אם מתה — יירשנה, מפני שמתנה על מה שכתוב בתורה,\u0004 שלדעתו מדין תורה הבעל יורש את אשתו, \u0003וכל המתנה על מה שכתוב בתורה\u0004 לבטלו — \u0003תנאו בטל.\u0004","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: \"האומר לאשתו\",\u0004 ולא שנה \"הכותב\", שאף באמירה בלבד בלא כתיבת שטר מועיל תנאי זה.","על עיקר ההלכה שואלים: \u0003וכי כתב\u0004 \u0005[וכאשר\u0006 הוא \u0005כותב]\u0006 או אומר \u0003לה הכי\u0004 \u0005[כך],\u0006 \u0003מאי הוי\u0004 \u0005[מה יהיה]?\u0006 כלומר, כיצד תועיל כתיבה או אמירה זו? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר לחבירו\u0004 שהוא שותף בנכסיו, בין באמירה בעל פה ובין בהודעה בכתב \u0003\"דין ודברים אין לי על שדה זו\",\u0004 או \u0003\"ואין לי עסק בה\",\u0004 או \u0003\"וידי מסולקת הימנה\" — לא אמר כלום,\u0004 שאין תוקף לויתור בנוסח זה שאיננו נוסח של מתנה!","\u0003אמרי דבי\u0004 \u0005[אמרו\u0006 החכמים \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ינאי:\u0004 במשנתנו מדובר \u0003בכותב לה ועודה ארוסה,\u0004 שכאשר כותב נוסח זה, עדיין אין הנכס ברשותו ולכן יכול הוא לסלק עצמו, ו\u0003כ\u0004דברי \u0003רב כהנא,\u0004 ש\u0003אמר רב כהנא: נחלה הבאה לאדם ממקום אחר,\u0004 שאינה ירושה ישירה, אלא מכוח אשתו, או על ידי מתנה — \u0003אדם מתנה עליה שלא יירשנה.\u0004 שבכגון זה תנאו קיים, למרות שאיננו יכול לוותר על נחלה שכבר הגיעה לו! \u0003וכ\u0004דברי \u0003רבא,\u0004 ש\u0003אמר רבא: האומר \"אי אפשי\u0004 (אין רצוני) \u0003בתקנת חכמים כגון זו\" — שומעין לו.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 \u0003\"כגון זו\"?\u0004 ומסבירים: \u0003כ\u0004דברי \u0003רב הונא אמר רב,\u0004 ש\u0003אמר רב הונא אמר רב: יכולה אשה שתאמר לבעלה \"איני ניזונת\u0004 משלך \u0003ואיני עושה\u0004 מלאכה עבורך\u0003\",\u0004","שכיון שתקנה זו נעשתה לטובת האשה, יכולה היא לומר שהיא מוותרת עליו. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אם מקבלים את שיטת רבא שאדם יכול לוותר על זכות שיש לו מכוח תקנת חכמים שנעשתה לטובתו, \u0003אפילו\u0004 בכותב לה \"דין ודברים אין לי בנכסיך\" בזמן שכבר \u0003נשואה נמי\u0004 \u0005[גם כן]\u0006 יש תוקף לתנאי שעושה, וכדין האשה שאומרת \"איני ניזונת\". ומדוע הוצרך ר' ינאי להסביר את משנתנו בארוסה דווקא?","\u0003אמר אביי: נשואה, ידו\u0004 (זכותו ורשותו בנכסים) — \u0003כידה\u0004 והריהו כשותף בנכסיה. ולכן, כיון שאנו אומרים שמכוח הנישואין יש לו קנין מסויים בנכסי אשתו — אין הקנין הזה מסולק על ידי נוסח ויתור שאין לו תוקף משפטי. \u0003רבא אמר:\u0004 אשה נשואה — \u0003ידו עדיפא מידה,\u0004 שבעצם זכותו בנכסיה גדולה מזכותה בהם. ומסבירים: \u0003נפקא מינה\u0004 \u0005[יוצא מזה]\u0006 הבדל מעשי בין שיטת רבא לשיטת אביי \u0003ל\u0004ענין \u0003שומרת יבם,\u0004 שאם אנו אומרים שבנשואה ידו כידה, אם היתה רק שומרת יבם שיש לו רק איזה זיקה אך אינה נשואה — הרי ידה־זכותה, עדיפה מידו. אבל אם אנו אומרים שבנשואה ידו עדיפה מידה — בשומרת יבם שניהם שווים.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 בענין הדינים שנאמרו בברייתא: אם \u0003קנו מידו, מהו?\u0004 כלומר, אם לא רק כתב לחבירו שהוא מוותר על הנכסים (שכפי שאמרנו כתיבה זו איננה מועילה) אלא גם עשו קנין על כך, מה הדין? \u0003אמר רב יוסף: מדין ודברים קנו מידו,\u0004 שאין דין קנין חל על מה שאינו אלא הבטחה בלבד, ואין לקנין שנעשה כדי לחזק הבטחה, תוקף רב יותר מאשר להבטחה עצמה. \u0003רב נחמן אמר: מגופה של קרקע קנו מידו.\u0004 כלומר, הקנין הזה באמת חל על גופה של הקרקע, והרי זה כנתינת הקרקע עצמה. \u0003אמר אביי: מסתברא מילתא\u0004 \u0005[מסתבר הדבר]\u0006 שאמר \u0003רב יוסף\u0004"],["\u0003בעורר,\u0004 שמיד כאשר בא השותף לקחת את החלק שהובטח לו, מערער הנותן ואומר שלא כתב אלא כדי להימנע ממריבה. \u0003אבל בעומד,\u0004 שכבר החזיק השותף בקרקע זו, והנותן מתחרט ורוצה להוציאו ממנה, אומרים אנו כי \u0003מגופה של קרקע קנו מידו,\u0004 ואינו יכול עכשיו לחזור בו.","\u0003אמר אמימר: הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 \u0003מגופה של קרקע קנו מידו. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר:\u0004 האם דבריך נאמרו \u0003ב\u0004יחס ל\u0003עורר או ב\u0004יחס ל\u0003עומד? למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 משאלה זו — \u0003לכ\u0004 דברי \u0003רב יוסף,\u0004 אבל לרב נחמן בכל מקרה הקנין הוא מגופה של קרקע. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אמימר: \u0003לא שמיע\u0004 \u0005[נשמע]\u0006 \u0003לי\u0004 מה שאמר רב יוסף. ומסבירים, \u0003כלומר: לא סבירא לי\u0004 \u0005[איני סבור\u0006 כן\u0005],\u0006 שאיני מקבל את דברי רב יוסף.","שנינו במשנה שאם כתב לה \"דין ודברים אין לי בנכסיך\", לא סילק את עצמו לא מן הפירות ולא מן הירושה. ומסבירים: \u0003אם כן, למה כתב לה וכו'\u0004 — רק כדי לתת לה רשות למכור את הנכסים אם תרצה. ושואלים: כיון שיש תוקף לויתור זה של הבעל, \u0003ותימא ליה\u0004 \u0005[ותאמר לו\u0006 האשה\u0005]:\u0006 \u0003מכל מילי\u0004 \u0005[דבר]\u0006 \u0003סליקת נפשך\u0004 \u0005[סלקת עצמך],\u0006 שהרי נוסח זה הוא כללי, ואפשר להבינו כויתור על כל הזכויות! \u0003אמר אביי,\u0004 נוקטים אנו בכלל: \u0003יד בעל השטר על התחתונה.\u0004 שאנו מפרשים כל שטר באופן כזה שההתחייבות בו תהיה הקטנה ביותר. ואף כאן אנו מפרשים את ויתורו של הבעל לדבר הפחות ביותר.","ושואלים: אם כך, \u0003ואימא\u0004 \u0005[ואמור]\u0006 שסילק עצמו \u0003מפירי\u0004 \u0005[מפירות],\u0006 שהרי מתנה או מכירה של הקרקע כולה היא דבר גדול וביחס לזה הפירות הם רק סכום קטן, ומדוע לא נאמר שדווקא מן הפירות סילק את עצמו? \u0003אמר אביי:\u0004 משל הוא בפי האנשים: \u0003\"בוצינא\u0004 \u0005[קישוא]\u0006 הנמצא ביד \u0003טב מקרא\u0004 \u0005[טוב מדלעת]\u0006 שתבוא לאחר זמן\u0003\",\u0004 ולכן אנו מניחים שזכותו בפירות עכשיו חשובה לו יותר מאשר אפשרות של מכירה שעשויה לבוא רק בעתיד.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 ש\u0003מירושה\u0004 רוצה לסלק את עצמו, שהוא הפחות, שהרי ייתכן שימות עוד לפניה! \u0003אמר אביי: מיתה שכיחא\u0004 \u0005[מצויה],\u0006 אבל \u0003מכירה לא שכיחא\u0004 \u0005[אינה מצויה],\u0006 שאין אדם נוהג למכור ירושת אבותיו, \u0003וכי מסליק איניש נפשיה\u0004 \u0005[וכאשר מסלק אדם עצמו]\u0006 אנו מפרשים שהוא מסלק עצמו \u0003ממילתא דלא שכיחא\u0004 \u0005[מדבר שאינו מצוי],\u0006 אבל \u0003ממילתא דשכיחא לא מסליק איניש נפשיה\u0004 \u0005[מדבר שמצוי אין אדם מסלק עצמו].\u0006 \u0003רב אשי אמר\u0004 טעם אחר, שאנו מדייקים בלשון השטר, שאמר בו \"דין ודברים אין לי \u0003בנכסייך\"\u0004 — משמע \u0003ולא בפירותיהן,\u0004 וכן \u0003\"בנכסייך\"\u0004 משמע בחייך שהם שייכים לך — \u0003ולא לאחר מיתה.\u0004","שנינו במשנה שאם כתב לה \"בנכסיך ובפירותיהן\" — אינו אוכל פירות. ואילו \u0003ר' יהודה אומר: לעולם הוא אוכל פירי פירות.\u0004 ועל זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אלו הן פירות ואלו הן פירי פירות?\u0004 דוגמא: \u0003הכניסה לו קרקע ועשתה\u0004 הקרקע \u0003פירות — הרי הן פירות. מכר פירות\u0004 שהיו לה \u0003ולקח\u0004 (קנה) \u0003מהן קרקע, ועשתה\u0004 קרקע זו \u0003פירות — הרי הן פירי פירות.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003ל\u0004דעת \u0003ר' יהודה\u0004 שהנוסח של סילוק גמור הוא כשכותב \"בפירותיהן ובפירי פירותיהן עד העולם\", האם הביטוי \u0003\"פירי פירות\" דוקא\u0004 \u0005[\u0006הוא \u0005המדוייק]\u0006 ובעצם די בנוסח זה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003\"עד עולם\" דוקא\u0004 \u0005[\u0006הוא \u0005המדוייק],\u0006 \u0003או דלמא תרוייהו\u0004 \u0005[שמא שניהם]\u0006 \u0003דוקא\u0004 (במדוייק) נאמרו, ואם לא אמר את שניהם — לא סילק את עצמו לגמרי?","ומבררים: \u0003אם תמצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 כי \u0003\"פירי פירות\"\u0004 הוא \u0003דוקא\u0004 (במדוייק), אם כן תוספת לשון זו שנקטה המשנה \u0003\"עד עולם\" למה לי?\u0004 ואפשר לפרש: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 התנא ש\u0003כיון\u0004 ש\u0003כתב לה \"פירי פירות\"\u0004 הרי זה \u0003כמאן דכתב\u0004 \u0005[כמי ש\u0006היה \u0005כותב]\u0006 \u0003לה \"עד עולם\" דמי\u0004 \u0005[נחשב],\u0006 אבל באמת אין זה מעכב אם לא הוסיף מילים אלו.","\u0003ו\u0004מן הצד האחר \u0003אם תמצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 ש\u0003\"עד עולם\" דוקא\u0004 הוא הלשון המדוייקת \u0003\"פירי פירות\" למה לי?\u0004 — על כך יש להסביר כי \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]:\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003כתב לה \"פירי פירות\", אי\u0004 \u0005[אם]\u0006 \u0003כתב לה\u0004 והוסיף \u0003\"עד עולם\" — אין\u0004 \u0005[כן],\u0006 הרי זה סילוק גמור, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 כתב כן — \u0003לא\u0004 סילק עצמו לגמרי, אלא אוכל פירי פירי פירות.","\u0003ואם תמצי\u0004 \u0005[ואם תרצה]\u0006 \u0003לומר\u0004 כי \u0003תרוייהו\u0004 \u0005[שניהם]\u0006 \u0003דוקא\u0004 (במדוייק), \u0003תרתי\u0004 \u0005[שניהם]\u0006 שני ביטויים \u0003למה לי?\u0004 על כך מסבירים: \u0003צריכא\u0004 \u0005[צריך]\u0006 לכתוב אותם, \u0003דאי כתב\u0004 \u0005[שאם\u0006 היה \u0005כותב]\u0006 \u0003לה\u0004 רק \u0003\"פירי פירות\" ולא כתב\u0004 \u0005[\u0006היה \u0005כותב]\u0006 \u0003לה \"עד עולם\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003פירי פירות הוא דלא אכיל\u0004 \u0005[שאינו אוכל]\u0006 \u0003אבל פירא דפירי פירות אכיל\u0004 \u0005[פירות של פירי פירות אוכל] —\u0006 \u0003להכי איצטריך\u0004 \u0005[ל\u0006שם \u0005כך הוצרך\u0006 לומר\u0005]\u0006 גם \u0003\"עד עולם\",\u0004 לומר שכל דבר שהוא שמקורו בנכסים אלה בכלל זה. \u0003ואי כתב\u0004 \u0005[ואם\u0006 היה \u0005כותב]\u0006 \u0003לה\u0004 רק \u0003\"עד עולם\", ולא כתב\u0004 \u0005[\u0006היה \u0005כותב]\u0006 \u0003לה \"פירי פירות\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003לעולם\u0004 על ה\u0003פירות קאי\u0004 \u0005[\u0006הוא \u0005עומד,\u0006 מתייחס\u0005],\u0006 שכוונתו שבפירות אין לו לעולם דין ודברים, אבל בפירי פירות יש לו עדיין זכות, \u0003להכי איצטריך\u0004 \u0005[ל\u0006שם \u0005כך הוצרך\u0006 לכתוב\u0005]\u0006 גם \u0003\"פירי פירות\".\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 ללומדים שאלה זו, \u0003כתב לה\u0004 בנוסח זה: \u0003\"דין ודברים אין לי בנכסייך ובפירי פירות\", מהו שיאכל פירות\u0004 עצמם? וצדדי השאלה: האם \u0003מפירי פירות סליק נפשיה\u0004 \u0005[סילק\u0006 את \u0005עצמו],\u0006 ואילו \u0003מפירי\u0004 \u0005[מפירות\u0006 עצמם\u0005]\u0006 \u0003לא סליק נפשיה\u0004 \u0005[סילק עצמו],\u0006 שהרי לא הזכירם, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003מכל מילי\u0004 \u0005[דבר]\u0006 \u0003סליק נפשיה\u0004 \u0005[סילק עצמו]?\u0006 ש\"פירי פירות\" כוללים גם את הפירות עצמם.","ומשיבים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 ש\u0003מכל מילי\u0004 \u0005[דבר]\u0006 \u0003סליק נפשיה, דאי אמרת\u0004 \u0005[שאם אומר אתה]\u0006 שרק \u0003מפירי פירות סליק נפשיה\u0004 \u0005[סילק\u0006 את \u0005עצמו],\u0006 ואילו \u0003מפירי\u0004 \u0005[מפירות\u0006 עצמם\u0005]\u0006 \u0003לא סליק נפשיה\u0004 \u0005[מסלק עצמו],\u0006 \u0003כיון דאכלינהו\u0004 \u0005[ש\u0006הוא \u0005אוכל]\u0006 את ה\u0003פירות, פירי פירות מהיכא\u0004 \u0005[מהיכן\u0006 יהיו\u0005]?\u0006","ודוחים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 שסילק את עצמו מהפירות — \u0003הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]\u0006 ש\u0003ר' יהודה אומר: לעולם הוא אוכל פירי פירות\u0004 עד שיכתוב לה \"ומפירות פירותיהן עד עולם\". אפשר להקשות באותו אופן: \u0003כיון דאכלינהו לפירי\u0004 \u0005[שאוכל\u0006 הוא עצמו \u0005את הפירות],\u0006 כשלא נסתלק מהם, אם כן \u0003פירי פירות מהיכא\u0004 \u0005[מהיכן]\u0006 יש לו? \u0003אלא\u0004 צריך לומר \u0003בדשיירא\u0004 \u0005[ב\u0006זמן \u0005ששיירה]\u0006 היא מן הפירות ולא השתמשה בהם ומן המותר הזה קנו קרקע, ומפירות קרקע זו הוא אוכל פירי פירות, אם כן \u0003הכא נמי בדשייר\u0004 \u0005[כאן גם כן\u0006 מדובר \u0005ב\u0006אופן \u0005ששייר]\u0006 מן הפירות, ומכרו שיור זה וקנה קרקע ובפירי פירות אלה אין לו זכות. ואם כן לא נפתרה השאלה.","שנינו במשנה ש \u0003רבן שמעון בן גמליאל אומר\u0004 שאף על פי שכתב לה \"דין ודברים אין לי בנכסיך ובפירותיהן בחייך ובמותך\" — מכל מקום יורשה, משום שתנאו בטל, מפני שמתנה על דברי תורה. \u0003אמר רב: הלכה\u0004 למעשה \u0003כרבן שמעון בן גמליאל\u0004 שהבעל יורש את אשתו, \u0003ולא מטעמיה\u0004 \u0005[מטעמו],\u0006 כלומר, לא מפני הטעם שאמר רבן שמעון בן גמליאל.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003הלכה כרבן שמעון בן גמליאל ולא מטעמיה\u0004 \u0005[מטעמו]?\u0006 מה היא סברתו של רב בענין זה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי \u0003הלכה כרבן שמעון בן גמליאל\u0004 ש\u0003אמר\u0004 ש\u0003אם מתה יירשנה, ולאו מטעמיה\u0004 \u0005[ולא מטעמו];\u0006 ש\u0003אילו רבן שמעון בן גמליאל סבר\u0004 \u0005[סבור]\u0006 שה\u0003מתנה על מה שכתוב בתורה — תנאו בטל, ורב סבר\u0004 \u0005[סבור]\u0006 ש\u0003תנאו קיים. ו\u0004אולם, \u0003קסבר\u0004 \u0005[סבור]\u0006 רב כי \u0003ירושת הבעל\u0004 איננה מן התורה אלא \u0003דרבנן\u0004 \u0005[מדברי\u0006 \u0005סופרים]\u0006 היא, \u0003ו\u0004דווקא משום כך התנאי בטל, כי \u0003חכמים עשו חיזוק לדבריהם יותר משל תורה,\u0004 וגזרו שלא תתבטל ירושת הבעל כלל."],["\u0003וסבר\u0004 \u0005[ו\u0006האם \u0005סבור]\u0006 \u0003רב\u0004 שהמתנה לבטל דבר הכתוב בתורה \u0003תנאו קיים? והא איתמר\u0004 \u0005[והרי נאמר]\u0006 שנחלקו אמוראים בשאלה הבאה: \u0003האומר לחבירו \"\u0004הרי אני מוכר לך דבר \u0003על מנת שאין לך עלי אונאה\",\u0004 שאף שאסור להונות, מכל מקום אתה מוותר לי על ההונאה. \u0003רב אמר: יש לו עליו אונאה,\u0004 וחייב המוכר להחזיר לקונה את מה שאונהו, משום שאינו יכול בתנאי לבטל את איסור התורה \"ולא תונו איש את עמיתו\" (ויקרא כה, יז). \u0003ושמואל אמר: אין לו עליו אונאה.\u0004 משמע שלדעת רב אי אפשר להתנות כדי לבטל דבר הכתוב בתורה!","\u0003אלא\u0004 כך צריך להבין את דברי רב: \u0003הלכה כרבן שמעון בן גמליאל\u0004 ש\u0003אמר\u0004 שכל \u0003המתנה על מה שכתוב בתורה תנאו בטל, ולאו מטעמיה\u0004 \u0005[ולא מטעמו],\u0006 אלא מטעם אחר, ש\u0003אילו רבן שמעון בן גמליאל סבר\u0004 \u0005[סבור]\u0006 שאם \u0003מתה\u0004 האשה — \u0003יירשנה, ורב\u0004 הרי \u0003סבר\u0004 \u0005[סבור]\u0006 שאם \u0003מתה — לא יירשנה,\u0004 שלדעתו ירושת הבעל מדברי סופרים היא, ואין בהתנאה משום מתנה על מה שכתוב בתורה והתנאי קיים. ואף לא עשו חכמים חיזוק לדבריהם שיהיה תוקפם יותר משל תורה.","אולם אם אתה מפרש כך הרי אתה הופך את הדברים שכן \u0003האי מטעמיה\u0004 \u0005[זה מטעמו]\u0006 \u0003ולא כהילכתיה\u0004 \u0005[כהלכתו]\u0006 \u0003הוא,\u0004 היפך דברי רב שאמר: כהלכתו ולא מטעמו!","\u0003אלא\u0004 כך צריך לפרש: \u0003הלכה כרבן שמעון בן גמליאל\u0004 ש\u0003אמר אם מתה יירשנה, ולאו מטעמיה\u0004 \u0005[ולא מטעמו],\u0006 ש\u0003אילו רבן שמעון בן גמליאל סבר\u0004 \u0005[סבור]\u0006 כי \u0003בדאורייתא\u0004 \u0005[ב\u0006דבר שהוא מ\u0005דברי תורה]\u0006 \u0003תנאו בטל,\u0004 ומכאן נבין — \u0003הא בדרבנן\u0004 \u0005[הרי ב\u0006תנאי על דבר שהוא \u0005מדברי סופרים]\u0006 \u0003תנאו קיים. ורב סבר\u0004 \u0005[סבור]\u0006 ש\u0003אפילו בדרבנן\u0004 \u0005[בדברי סופרים]\u0006 אם מתנה כנגד דבריהם — \u0003תנאו בטל.\u0004","אולם גם פה יש לשאול: אם כן הרי \u0003האי כטעמיה וכהילכתיה\u0004 \u0005[זה כטעמו וכהלכתו]\u0006 \u0003הוא, ורב\u0004 רק \u0003מוסיף הוא\u0004 עוד פרט בהלכה שלא אמר אותו רבן שמעון בן גמליאל!","\u0003אלא\u0004 יש לחזור גם מפירוש זה, וצריך לומר: \u0003הלכה כרבן שמעון בן גמליאל\u0004 ש\u0003אמר אם מתה יירשנה, ולאו מטעמיה\u0004 \u0005[ולא מטעמו],\u0006 ש\u0003אילו רבן שמעון בן גמליאל סבר\u0004 \u0005[סבור]\u0006 כי \u0003ירושת הבעל דאורייתא\u0004 \u0005[מן התורה\u0006 היא\u0005]\u0006 \u0003וכל המתנה על מה שכתוב בתורה — תנאו בטל. ו\u0004אילו \u0003רב סבר\u0004 \u0005[סבור]\u0006 כי \u0003ירושת הבעל דרבנן\u0004 \u0005[מדברי סופרים]\u0006 היא, \u0003ו\u0004בכל זאת תנאו בטל כי \u0003חכמים עשו חיזוק לדבריהם כשל תורה\u0004 שלא יוכלו לבטל את תקנתם.","ושואלים: \u0003ו\u0004האם \u0003רב סבר\u0004 \u0005[סבור]\u0006 כי \u0003ירושת הבעל דרבנן\u0004 \u0005[מדברי סופרים\u0006 היא\u0005]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יוחנן בן ברוקא אומר: היורש את אשתו, יחזיר\u0004 את הנכסים \u0003לבני משפחה\u0004 של האשה בשנת היובל, \u0003וינכה להן מן הדמים,\u0004 שאינו גובה מהם כל שווי הנכסים אלא רק חלק ממנו.","\u0003והוינן\u0004 \u0005[והיינו עוסקים\u0006 ומקשים\u0005]\u0006 \u0003בה\u0004 בהלכה זו: \u0003מאי קסבר\u0004 \u0005[מה סבור]\u0006 ר' יוחנן בן ברוקא? \u0003אי קסבר\u0004 \u0005[אם סבור הוא]\u0006 ש\u0003ירושת הבעל דאורייתא\u0004 \u0005[מן התורה\u0006 היא\u0005],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003יחזיר?\u0004 שהרי ירושה אינה חוזרת ביובל. \u0003ואי דרבנן\u0004 \u0005[ואם\u0006 סבור הוא שהיא רק \u0005מדברי סופרים],\u0006 אם כן \u0003דמים מאי עבידתייהו\u0004 \u0005[מה מעשיהם]?\u0006 שאם חוזרים להלכה הבסיסית, כדין תורה, הרי הנכסים שייכים למשפחת האשה, ואין הם צריכים לשלם לו כלל!","\u0003ואמר רב: לעולם קסבר\u0004 \u0005[סבור הוא]\u0006 ש\u0003ירושת הבעל דאורייתא\u0004 \u0005[מן התורה\u0006 היא\u0005],\u0006 \u0003וכגון שהורישתו אשתו בית הקברות\u0004 של המשפחה, ו\u0003משום פגם משפחה,\u0004 שלא יהיו בני משפחה זו קבורים בנחלת אחרים, \u0003אמור רבנן לישקול דמי וליהדר\u0004 \u0005[אמרו חכמים שיקח כסף\u0006 מהם \u0005ויחזיר\u0006 להם\u0005]\u0006 את בית הקברות.","\u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"ינכה להן מן הדמים\"\u0004 — הכוונה היא \u0003דמי קבר אשתו.\u0004 שהרי את אשתו הוא צריך לקבור בנחלתו על חשבונו, ואם קבר אותה באותה נחלה ינכה להם את דמי הקבר מדמי הנחלה. \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003המוכר קברו,\u0004 או את ה\u0003דרך\u0004 אל \u0003קברו, מעמדו\u0004 (המקום שבו היו עומדים לנחם את האבלים), או \u0003מקום הספידו — באין בני משפחה וקוברין אותו\u0004 בנחלת אבותיו \u0003בעל כרחו\u0004 של הקונה, \u0003משום פגם משפחה,\u0004 שלא יהיה אחד מהם קבור בנחלת זרים. ומכל מקום, אפשר ללמוד מכאן שרב סבור שירושת הבעל היא מן התורה, ולא כפי שניסינו להוכיח!","ומשיבים: מכאן אין הוכחה, כי אפשר לומר ש\u0003רב לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 של \u0003ר' יוחנן בן ברוקא קאמר\u0004 \u0005[אומר],\u0006 שהסביר מה טעמו של תנא זה, \u0003וליה לא סבירא ליה\u0004 \u0005[והוא\u0006 עצמו \u0005אינו סבור\u0006 כן\u0005].\u0006","\u0003מי שמת והניח אשה ובעל חוב\u0004 הנושה בו, \u0003ויורשין, והיה לו פקדון או מלוה ביד אחרים\u0004 וכל אלה תובעים את הרכוש הזה — \u0003ר' טרפון אומר: ינתנו\u0004 הפקדון או המלוה \u0003לכושל\u0004 (לחלש) \u0003שבהן,\u0004 שהוא זקוק יותר לתמיכה. \u0003ר' עקיבא אומר: אין מרחמין בדין,\u0004 שאם דין הוא — צריך לנהוג לפי הדין, ואין לערב כאן שיקול של רחמים. \u0003אלא\u0004 לפי הדין \u0003ינתנו ליורשין, ש\u0004כן \u0003כולן צריכין שבועה,\u0004 שכל הרוצה להיפרע מיתומים צריך להישבע, \u0003ואין היורשין צריכין שבועה\u0004 ולכן כוחם ברכוש האב רב משל כל האחרים.","ואם \u0003הניח\u0004 הנפטר \u0003פירות תלושין מן הקרקע — כל הקודם בהן,\u0004 האשה, בעל החוב, או היורשים, ולקח את חלקו — \u0003זכה בהן\u0004 בפירות התלושים. ואם \u0003זכתה\u0004 ה\u0003אשה\u0004 בפירות אלה ולקחה \u0003יותר מ\u0004דמי \u0003כתובתה,\u0004 או שזכה בהם \u0003בעל חוב\u0004 ולקח \u0003יותר על חובו,\u0004 מה יעשו בכסף \u0003המותר? ר' טרפון אומר: ינתנו לכושל שבהן,\u0004 בעל החוב או האשה, לפי הענין. \u0003ר' עקיבא אומר: אין מרחמין בדין, אלא ינתנו\u0004 הפירות הנותרים \u0003ליורשין,\u0004 מן הטעם שאמר; \u0003שכולם צריכין שבועה, ואין היורשין צריכין שבועה.\u0004","על לשון המשנה שואלים: \u0003למה לי למיתני\u0004 \u0005[לשנות]\u0006 דין זה ב\u0003מלוה, למה לי למיתני\u0004 \u0005[לשנות]\u0006 גם ב\u0003פקדון?\u0004 די היה לו להביא דוגמא אחת בלבד! ומסבירים: \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שני הדברים; \u0003דאי תנא\u0004 \u0005[שאילו\u0006 היה \u0005שונה]\u0006 \u0003מלוה\u0004 בלבד, היינו אומרים: \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003ר' טרפון\u0004 שינתנו לכושל שבהם \u0003משום\u0004 ש\u0003מלוה להוצאה ניתנה\u0004 ובעצם אין כאן רכוש הקיים בפועל אלא התחייבות בלבד, ובכגון זה אפשר לתת אותו למי שזקוק לכך, \u0003אבל פקדון דאיתיה בעיניה\u0004 \u0005[שישנו בעינו]\u0006 \u0003אימא מודי ליה\u0004 \u0005[אמור שמודה לו]\u0006 \u0003לר' עקיבא\u0004 שהוא בחזקת היורשים.","ולהיפך, \u0003ואי תנא הא\u0004 \u0005[ואילו\u0006 היה \u0005שונה זו]\u0006 בפקדון בלבד, היינו אומרים: \u0003בהא קאמר\u0004 \u0005[בזו\u0006 דווקא \u0005אמר]\u0006 \u0003ר' עקיבא\u0004 שיינתן ליורשים, \u0003אבל בהך\u0004 \u0005[באחרת,\u0006 במלוה\u0005]\u0006 \u0003אימא מודי\u0004 \u0005[אמור\u0006 ש\u0005מודה]\u0006 \u0003לר' טרפון\u0004 שיינתנו לכושל שבהן, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שני הדברים.","שנינו במשנה שלדעת ר' טרפון יינתנו לכושל שבהם. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"לכושל\"? ר' יוסי בר' חנינא אומר: לכושל שבראיה,\u0004 כלומר, לזה שהשטר שלו מאוחר ביותר, שהראיה שבידו כושלת ביותר, שהרי הוא אינו יכול לטרוף מאחרים, ושאר התובעים יכולים לטרוף מנכסים שנמכרו קודם. \u0003ר' יוחנן אמר:\u0004 הכוונה היא \u0003לכתובת אשה, משום חינא\u0004 \u0005[חן]\u0006 שעשו חכמים תקנות לטובת האשה בכתובתה, כדי שיהא חן לגברים בעיניהן, שידעו שיש להן בטחון בנישואיהן ושאינן צריכות לחשוש להפסד כתובתן.","ומעירים: בעיה זו היא \u0003כתנאי\u0004 \u0005[כתנאים]\u0006 שנחלקו בנושא זה, ש\u0003ר' בנימין אומר: לכושל שבראיה, והוא כשר,\u0004 כלומר, כך כשר וראוי לעשות. \u0003ר' אלעזר אומר: לכתובת אשה, משום חינא\u0004 \u0005[חן].\u0006","שנינו במשנה שאם \u0003הניח פירות התלושין\u0004 וקדם אחד התובעים ונטלם — זכה בהם, אלא שנחלקו למי יינתן המותר. ושואלים: \u0003ור' עקיבא מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע הוא דן\u0005]\u0006 דווקא ב\u0003מותר?\u0004 הלא \u0003כולהו נמי\u0004 \u0005[הכל גם כן]\u0006 של ה\u0003יורשין הוו\u0004 \u0005[הם],\u0006 שהרי לשיטתו כל הרכוש שייך בראשונה ליורשים, ולאחרים אין זכות בהם אפילו אם קדמו ונטלו? ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כך\u0006 הוא \u0005גם כן]\u0006 הדין לשיטתו, שלדעתו ודאי שאין לחלק בין פקדון לפירות תלושים, אלא \u0003ואיידי\u0004 \u0005[ועל ידי,\u0006 מתוך\u0005],\u0006 ש\u0003אמר ר' טרפון\u0004 דבריו בענין ה\u0003מותר, תנא איהו נמי\u0004 \u0005[שנה הוא גם כן]\u0006 בענין ה\u0003מותר,\u0004 אבל לדעתו — הוא הדין לגבי הפירות כולם."],["\u0003ו\u0004לדעת \u0003ר' עקיבא\u0004 האם \u0003תפיסה\u0004 שאדם תופס דבר, עבור חוב שחייבים לו למרות שיש לאחרים זכות קודמת בו, \u0003לא מהניא\u0004 \u0005[מועילה]\u0006 \u0003כלל? אמר רבא אמר רב נחמן:\u0004 גם ר' עקיבא מודה שתפיסה מועילה, \u0003ו\u0004אולם דבר זה \u0003הוא\u0004 דווקא כ\u0003שתפס מחיים,\u0004 כלומר, בחייו של החייב, אבל לאחר מותו כבר זכו בהם היורשים ולכך אין מועילה בזה תפיסה.","ושואלים: \u0003ולר' טרפון\u0004 שאמר כי בפירות תלושים כל הקודם ליטול אותם זכה בהם ולאו דווקא היורשים, \u0003דמנחי היכא\u0004 \u0005[היכן היו\u0006 הפירות הללו \u0005מונחים]\u0006 בשעת מיתה, שעליהם אמר כי כל הקודם זכה בהם? \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003והוא שצבורין ומונחין ברשות הרבים,\u0004 שרשות הרבים אינה מקום הראוי לקנין ולכך לא זכו בהם היורשים, ולכן אפשר שכל אחד יטול אותם משם ויזכה בהם, \u0003אבל\u0004 אם היו מונחים \u0003בסימטא,\u0004 פינה הסמוכה לרשות הרבים שאין הרבים מצויים בה — \u0003לא,\u0004 משום שסימטא היא מקום הראוי לקנין, ולכן מה שנמצא שם נקנה מיד ליורשים. \u0003ור' יוחנן וריש לקיש דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003אפילו\u0004 התופס \u0003בסימטא\u0004 זוכה.","מסופר: \u0003דון דייני\u0004 \u0005[דנו דיינים]\u0006 במקרה כגון זה \u0003כ\u0004דעת \u0003ר' טרפון, ואהדריה\u0004 \u0005[והחזירו]\u0006 \u0003ריש לקיש לעובדא מינייהו\u0004 \u0005[את המעשה מהם],\u0006 שריש לקיש ביטל את החלטת הדיינים והחזיר את הכספים ליורשים משום שסבור הוא שהלכה כר' עקיבא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן: עשית\u0004 את שיטת ר' עקיבא \u0003כ\u0004אילו היתה דין \u0003של\u0004 דברי \u0003תורה,\u0004 שאם טעו בו הדיינים מחזירים את מעשה בית הדין, ובאמת רק מלכתחילה אומרים אנו שהלכה כמותו, ואולם אם עשו כבר מעשה בניגוד לדבריו, אין לחזור.","ומציעים: \u0003לימא בהא קמיפלגי\u0004 \u0005[\u0006האם \u0005לומר\u0006 ש\u0005בכך הם חלוקים]\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ריש לקיש, \u0005סבור]\u0006 כי מי ש\u0003טעה בדבר\u0004 הכתוב ב\u0003משנה — חוזר\u0004 הדין, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יוחנן, \u0005סבור]\u0006 כי \u0003טעה בדבר משנה — אינו חוזר?\u0004","ודוחים: \u0003לא,\u0004 אפשר לומר \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003טעה בדבר משנה — חוזר. והכא בהא קמיפלגי\u0004 \u0005[וכאן ב\u0006נושא \u0005זה\u0006 הם \u0005חלוקים]\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוחנן, \u0005סבור]\u0006 כי הכלל ש\u0003הלכה כר' עקיבא\u0004 בכל מקום בו חלוק עליו אחר, הרי זה דווקא במחלוקתו \u0003מחבירו, ולא\u0004 במחלוקת \u0003מרבו,\u0004 ור' טרפון היה רבו של ר' עקיבא. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ריש לקיש, \u0005סבור]\u0006 ש\u0003הלכה\u0004 כמותו \u0003אפילו מרבו.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003הלכה כר' עקיבא מחבירו ולא מרבו. והכא בהא קמיפלגי\u0004 \u0005[וכאן בזה\u0006 הם \u0005חלוקים]:\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יוחנן, \u0005סבור]\u0006 ש\u0003ר' טרפון רבו\u0004 של ר' עקיבא \u0003הוה\u0004 \u0005[היה],\u0006 \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ריש לקיש, \u0005סבור]\u0006 כי \u0003חבירו הוה\u0004 \u0005[היה].\u0006","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 ר' טרפון \u0003חבירו\u0004 של ר' עקיבא \u0003הוה\u0004 \u0005[היה],\u0006 \u0003והכא בהא קמיפלגי\u0004 \u0005[וכאן בזה\u0006 הם \u0005חלוקים]:\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ריש לקיש, \u0005סבור]\u0006 כי \u0003הלכה איתמר\u0004 \u0005[נאמר],\u0006 כלומר, יש פסק הלכה ברור כר' עקיבא מחבירו. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' יוחנן, \u0005סבור]\u0006 ש\u0003מטין איתמר\u0004 \u0005[נאמר].\u0006 כלומר, כך נוהגים בפועל לכתחילה, אבל אין זה פסק הלכה מוחלט, ולכן אם פסקו דיינים כנגד הנחיה זו של \"הלכה כרבי עקיבא מחבירו\" — אין מבטלין את דינם.","מסופר: \u0003קריביה\u0004 \u0005[קרוביו]\u0006 של \u0003ר' יוחנן תפוס\u0004 \u0005[תפסו]\u0006 \u0003פרה דיתמי\u0004 \u0005[של יתומים]\u0006 \u0003מסימטא,\u0004 משום שהיה אבי היתומים חייב להם סכום כסף. \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003ר' יוחנן\u0004 לדין בענין זה, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003שפיר תפסתוה\u0004 \u0005[יפה תפסתם אותה],\u0006 וזכיתם בה, כדעת ר' טרפון. \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003ר' שמעון בן לקיש, אמר להו\u0004 \u0005[להם]:\u0006 \u0003זילו אהדור\u0004 \u0005[לכו החזירו]\u0006 את הפרה ליתומים, שהלכה כר' עקיבא שאין בתפיסה שלאחר מיתה ולא כלום. \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003ר' יוחנן\u0004 להתלונן שריש לקיש אמר להם להחזיר, כנגד דברי ר' יוחנן. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מה אעשה? שכנגדי,\u0004 כלומר, אדם כמותי, בשיעור הקומה שלי, \u0003חלוק עלי,\u0004 ואיני יכול לבטל את דבריו.","מסופר: \u0003ההוא בקרא דיתמי דתפסי תורא מיניה\u0004 \u0005[אחד, שומר הבקר של יתומים ש\u0006בעלי חוב \u0005תפסו שור ממנו]\u0006 כדי להיפרע בו חוב של המת, אבי היתומים. \u0003בעל חוב אמר: מחיים\u0004 של הנפטר \u0003תפיסנא ליה\u0004 \u0005[תפסתי אותו],\u0006 וכפי שאמרנו שתפיסה זו מועילה אף לדעת ר' עקיבא. \u0003ובקרא\u0004 \u0005[ושומר הבקר]\u0006 \u0003אמר: לאחר מיתה תפסיה\u0004 \u0005[תפס אותו].\u0006 \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רב נחמן\u0004 בדין זה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן לשומר הבקר: \u0003אית\u0004 \u0005[יש]\u0006 \u0003לך סהדי דתפסיה\u0004 \u0005[עדים שתפס]\u0006 את השור ממך? \u0003אמר ליה\u0004 \u0005[לו]\u0006 השומר: \u0003לאו\u0004 \u0005[לא].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 אם כן, \u0003מגו\u0004 \u0005[מתוך]\u0006 ש\u0003יכול\u0004 התופס \u0003למימר\u0004 \u0005[לומר]\u0006 \u0003\"לקוח\u0004 (קנוי) \u0003הוא בידי\",\u0004 שהרי אין ראיה שהגיע השור לידיו שלא כדין, \u0003יכול נמי למימר\u0004 \u0005[גם כן לומר]\u0006 ש\u0003\"מחיים\u0004 של הנפטר \u0003תפיסנא ליה\u0004 \u0005[תפסתי אותו]\u0006\u0003\".\u0004","ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ריש לקיש: הגודרות\u0004 (צאן) \u0003אין להן חזקה,\u0004 שעצם החזקה בהן אינה הוכחה על בעלות עליהן, ואין תפיסה מועילה בהן, מפני שהן נודדות ממקום למקום, וקל לתופסן, כך שלתפיסה זו אין ערך כחזקה, והוא הדין אם כן לבקר! ומשיבים: \u0003שאני תורא דמסירה\u0004 \u0005[שונה\u0006 \u0005השור\u0006 מן הצאן לפי \u0005ש\u0006הוא \u0005מסור]\u0006 \u0003לרועה\u0004 ואינו משוטט בכל מקום, ולכן יש בו דין תפיסה.","ועוד מסופר: \u0003דבי נשיאה תפוס אמתא דיתמי\u0004 \u0005[\u0006בני \u0005בית הנשיא\u0006 בארץ ישראל \u0005תפסו שפחה של יתומים]\u0006 \u0003מסימטא,\u0004 לפרעון חוב שהיה אבי יתומים חייב להם. \u0003יתיב\u0004 \u0005[ישבו]\u0006 \u0003ר' אבהו ור' חנינא בר פפי ור' יצחק נפחא,\u0004 כדיינים, \u0003ויתיב\u0004 \u0005[וישב]\u0006 \u0003ר' אבא גבייהו\u0004 \u0005[אצלם].\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 ר' אבהו: \u0003שפיר\u0004 \u0005[יפה]\u0006 \u0003תפסתוה\u0004 והדין עמכם וזכיתם בה. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003ר' אבא\u0004 לדיינים: \u0003משום דבי נשיאה נינהו מחנפיתו להו\u0004 \u0005[ש\u0006בני \u0005בית הנשיא הם אתם מחניפים להם]\u0006 ופוסקים שלא כדין? \u0003והא דון דייני\u0004 \u0005[והרי דנו דיינים]\u0006 \u0003כ\u0004שיטת \u0003ר' טרפון, ואהדריה\u0004 \u0005[והחזיר]\u0006 \u0003ריש לקיש עובדא מינייהו\u0004 \u0005[\u0006את \u0005המעשה מהם],\u0006 משמע שאין הלכה כר' טרפון כלל.","ועוד מסופר: איש אחר ושמו \u0003יימר בר חשו הוה מסיק ביה זוזי בההוא גברא\u0004 \u0005[היה נושה בו כסף באדם אחד],\u0006 \u0003שכיב ושביק ארבא\u0004 \u0005[מת\u0006 האיש \u0005והניח אניה].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 יימר בר חשו \u0003לשלוחיה\u0004 \u0005[לשלוחו]:\u0006 \u0003זיל, תפסה ניהליה\u0004 \u0005[לך, תפוס אותה עבורי].\u0006 \u0003אזל\u0004 \u0005[הלך]\u0006 השליח \u0003תפסה. פגעו ביה\u0004 \u0005[פגשו בו]\u0006 \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע, אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003את,\u0004 אתה השליח, במעשיך \u0003תופס לבעל חוב במקום שחב לאחרים.\u0004 שאמנם תפסת עבור בעל חוב, אבל יש עוד בעלי חוב אחרים שנושים באותו אדם, \u0003ו\u0004בכגון זה \u0003אמר ר' יוחנן: התופס לבעל חוב, במקום ש\u0004האיש \u0003חב\u0004 גם \u0003לאחרים\u0004"],["\u0003לא קנה.\u0004 שאין הוא יכול לחייב אחרים בלא רצונם, וכיון שתפיסתו היא לחובת הנושים האחרים — אין לה תוקף. וכיון שהם עצמם גם כן היו נושים באותו אדם, \u0003תפסוה,\u0004 את האניה, \u0003אינהו\u0004 \u0005[הם],\u0006 וכל אחד מהם רצה לתפסה לעצמו. \u0003רב פפא מימלח מלוחי\u0004 \u0005[היה נוהג\u0006 אותה \u0005במשוט].\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע ממתח לה באשלא\u0004 \u0005[היה מושך אותה בחבל].\u0006 \u0003מר\u0004 \u0005[חכם\u0006 זה\u0005]\u0006 \u0003אמר: אנא קנינא לה לכולה\u0004 \u0005[אני קניתי אותה כולה]\u0006 \u0003ומר\u0004 \u0005[וחכם\u0006 זה\u0005]\u0006 \u0003אמר: אנא קנינא לה לכולה\u0004 \u0005[אני קניתי אותה כולה].\u0006","\u0003פגע בהו\u0004 \u0005[פגש אותם]\u0006 \u0003רב פנחס בר אמי, אמר להו\u0004 \u0005[להם]:\u0006 \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 שתפיסה זו מועילה \u0003ו\u0004אולם דבר זה \u0003הוא\u0004 דווקא כ\u0003שצבורין ומונחין ברשות הרבים,\u0004 והרי האניה לא היתה ברשות הרבים אלא בשפת הנהר שהיא כסימטא שהיא ראויה לקנין וממילא זכו בה כבר היורשים! \u0003אמר להו\u0004 \u0005[אמרו לו]:\u0006 \u0003אנן נמי מחריפותא דנהרא תפיסנא\u0004 \u0005[אנחנו גם כן מאמצע הנהר תפסנו]\u0006 ודינו כרשות הרבים.","\u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רבא\u0004 לשאול מי מהם זכה באניה, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003קאקי חיורי\u0004 \u0005[אווזים לבנים],\u0006 שקרא להם כך משום שהיו שניהם כבר בעלי זקן לבן. \u0003משלחי גלימי דאינשי\u0004 \u0005[פושטי גלימות אנשים]!\u0006 כלומר, מעיקרו של דבר לא עשיתם כדין. \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב נחמן:\u0004 אמנם תפיסה של בעל חוב מועילה — \u0003והוא\u0004 דווקא \u0003שתפסה מחיים,\u0004 וכאן היתה התפיסה לאחר מיתת הלווה וכבר זכו בה היורשים.","ומסופר עוד: \u0003אבימי בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' אבהו הוו מסקי ביה זוזי\u0004 \u0005[היו נושים בו זוזים,\u0006 כסף\u0005]\u0006 אנשים מ\u0003בי חוזאי\u0004 שהוא מקום רחוק, \u0003שדרינהו\u0004 \u0005[שלחם,\u0006 את הזוזים\u0005]\u0006 \u0003ביד חמא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה בר אבהו. אזל פרעינהו\u0004 \u0005[הלך\u0006 ו\u0005פרע אותם\u0006 כספים\u0005]\u0006 שהיה חייב. \u0003אמר להו\u0004 \u0005[להם]\u0006 חמא: \u0003הבו\u0004 \u0005[תנו,\u0006 החזירו\u0005]\u0006 \u0003לי שטרא\u0004 \u0005[\u0006את \u0005שטר\u0006 החוב\u0005]\u0006 המעיד על כך שמשלחי היה חייב לכם. \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 אלה, \u0003סיטראי נינהו\u0004 \u0005[\u0006חובות \u0005מן הצד הם],\u0006 כלומר, המשלח אותך היה חייב לנו כסף אחר, שאינו כתוב בשטר, ואנו גובים עכשיו את החוב ההוא, ואת השטר לא נחזיר לך, שהחוב שבשטר טרם נפרע.","\u0003אתא לקמיה\u0004 \u0005[בא\u0006 הדין \u0005לפני]\u0006 \u0003ר' אבהו. אמר ליה\u0004 \u0005[לו]\u0006 לחמא: \u0003אית\u0004 \u0005[יש]\u0006 \u0003לך סהדי דפרעתינהו\u0004 \u0005[עדים שפרעת להם]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא. אמר ליה\u0004 \u0005[לו]\u0006 ר' אבהו: \u0003מיגו\u0004 \u0005[מתוך]\u0006 ש\u0003יכולין\u0004 הם \u0003לומר \"לא היו דברים מעולם\",\u0004 שבכלל לא פרעת חוב כלשהו, אם כן \u0003יכולין נמי למימר\u0004 \u0005[גם כן לומר]\u0006 \u0003\"סיטראי נינהו\u0004 \u0005[\u0006חובות \u0005מן הצד הם]\u0006 \u0003\"\u0004 ואי אפשר להוציא מהם את השטר.","ושואלים: \u0003לענין שלומי\u0004 \u0005[תשלומי]\u0006 ה\u0003שליח מאי\u0004 \u0005[מה\u0006 הדין\u0005],\u0006 האם צריך השליח לפצות את המשלח על שגרם לו לאבד את כספו בכך שנתן את הכסף לפני שקיבל מהם את השטר? \u0003אמר רב אשי: חזינן\u0004 \u0005[רואין אנו],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 המשלח \u0003\"שקול שטרא והב זוזי\u0004 \u0005[קח\u0006 מהם את \u0005השטר ותן\u0006 להם \u0005כסף]\u0006 \u0003\",\u0004 והשליח לא עשה כן אלא נתן את הכסף לפני שקיבל את השטר — \u0003משלם\u0004 השליח, ששינה מן השליחות. ואם אמר לו \u0003\"הב זוזי ושקול שטרא\u0004 \u0005[תן כסף וקח שטר]\u0006 \u0003\"\u0004\u0005—\u0006 \u0003לא משלם,\u0004 שהרי אף המשלח לא אמר לו לדקדק בזה.","ומוסיפים: \u0003ולא היא\u0004 (ואין הדבר כן) כדברי רב אשי, אלא \u0003בין כך ובין כך משלם\u0004 השליח. \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 המשלח: \u0003\"לתקוני שדרתיך\u0004 \u0005[לתקן שלחתי אותך]\u0006 \u0003ולא לעוותי\u0004 \u0005[לקלקל]\u0006\u0003\",\u0004 שחובתו של שליח למלא את תפקידו בצורה הטובה ביותר.","מסופר: \u0003ההיא איתתא דהוו מיפקדי גבה מלוגא דשטרי\u0004 \u0005[אשה אחת שהיו מופקדים אצלה תיק מלא שטרות]\u0006 שהפקיד אצלה אבי יתומים טרם מותו. \u0003אתו\u0004 \u0005[באו]\u0006 ה\u0003יורשים קא תבעי ליה מינה\u0004 \u0005[\u0006ו\u0005תבעו אותו ממנה].\u0006 \u0003אמרה להו\u0004 \u0005[להם]:\u0006 כבר \u0003מחיים\u0004 של הנפטר \u0003תפיסנא להו\u0004 \u0005[תפסתי אותם],\u0006 שאף אני נושה בו כסף. \u0003אתאי לקמיה\u0004 \u0005[באה לפני]\u0006 \u0003רב נחמן\u0004 לדין. \u0003אמר לה\u0004 לאשה המחזיקה: \u0003אית ליך סהדי דתבעוה מיניך\u0004 \u0005[\u0006האם \u0005יש לך עדים שתבעו\u0006 את התיק \u0005ממך]\u0006 עוד \u0003מחיים\u0004 של הנפטר \u0003ולא יהבית ניהליה\u0004 \u0005[נתת לו]?\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003לא,\u0004 אין לי עדים על כך. אמר לה: \u0003אם כן, הוי\u0004 \u0005[הרי היא]\u0006 \u0003תפיסה\u0004 ש\u0003לאחר מיתה, ותפיסה\u0004 ש\u0003לאחר מיתה — לא כלום היא,\u0004 כפי שאמרנו שאין תפיסה מועילה להוציא מן היתומים אלא בחיי החייב.","מסופר: \u0003ההיא איתתא דאיחייבא\u0004 \u0005[אשה אחת שהתחייבה]\u0006 \u0003שבועה\u0004 כדי להיפטר מתשלום ב\u0003בי דינא\u0004 \u0005[\u0006ב\u0005בית הדין]\u0006 של \u0003רבא. אמרה ליה\u0004 \u0005[לו]\u0006 לרבא \u0003בת רב חסדא\u0004 אשתו: \u0003ידענא\u0004 \u0005[יודעת אני]\u0006 \u0003בה\u0004 שהיא \u0003חשודה\u0004 על ה\u0003שבועה.\u0004 ואין לסמוך על שבועתה. \u0003אפכה\u0004 \u0005[הפכה]\u0006 \u0003רבא\u0004 את חובת ה\u0003שבועה\u0004 על הצד \u0003שכנגדה,\u0004 שישבע שהאשה חייבת לו ויטול, כדרך שעושים באדם שמוכח שאינו נאמן על שבועה.","ומסופר: \u0003זימנין הוו יתבי קמיה\u0004 \u0005[פעם\u0006 אחרת \u0005ישבו לפניו],\u0006 לפני רבא, \u0003רב פפא ורב אדא בר מתנא, אייתו ההוא שטרא גביה\u0004 \u0005[הביאו שטר אחד אליו]\u0006 לבית הדין, כדי שידון בו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא\u0004 לרבא: \u0003ידענא ביה דשטרא פריעא\u0004 \u0005[יודע אני בו,\u0006 בשטר זה, \u0005ששטר פרוע]\u0006 \u0003הוא. אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003איכא איניש אחרינא בהדיה דמר\u0004 \u0005[\u0006האם \u0005יש אדם אחר עם אדוני]\u0006 שיוכל אף הוא להעיד על כך? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא,\u0004 רק אני לבדי יודע. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אף על גב דאיכא מר\u0004 \u0005[אף על פי שיש כאן\u0006 את \u0005אדוני]\u0006 ואומר אתה זאת, מכל מקום עדות \u0003עד אחד לאו\u0004 \u0005[לא]\u0006 \u0003כלום הוא.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר מתנא\u0004 לרבא: \u0003ו\u0004כי \u0003לא יהא רב פפא\u0004 נאמן כמו \u0003בת רב חסדא\u0004 שהיא אשה ופסולה לעדות? ענה לו רבא: \u0003בת רב חסדא קים לי בגווה\u0004 \u0005[מוחזק אני בה]\u0006 שהיא אומרת תמיד אמת, \u0003מר לא קים לי בגוויה\u0004 \u0005[\u0006ב\u0005אדוני אין אני מוחזק בו\u0006 כך\u0005],\u0006 ואיני יכול לעשות על פי עד אחד כאשר אין לי בטחון גמור בדבר.","\u0003אמר רב פפא,\u0004 והסיק מכאן: \u0003השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003אמר מר\u0004 \u0005[החכם,\u0006 רבא\u0005]\u0006 \u0003\"קים לי בגוויה\"\u0004 \u0005[מוחזק אני בו]\u0006 שהוא דובר אמת \u0003\" מילתא היא\u0004 \u0005[דבר הוא],\u0006 כלומר, אם הדיין יודע שאדם מסויים אומר אמת למרות שבדרך כלל אי אפשר לסמוך עליו בתורת עדות, יש לדבריו תוקף משפטי מסויים, \u0003כגון אבא מר ברי\u0004 \u0005[בני]\u0006 \u0003דקים\u0004 \u0005[שמוחזק]\u0006 \u0003לי בגוויה\u0004 \u0005[בו]\u0006 שהוא דובר אמת, \u0003קרענא שטרא אפומיה\u0004 \u0005[אני\u0006 יכול \u0005לקרוע שטר על פיו]\u0006 אם יאמר לי ששטר זה הוא פרוע.","ותוהים: \u0003קרענא סלקא דעתך\u0004 \u0005[קורע אני\u0006 על פיו \u0005עלה על דעתך]?!\u0006 איך אפשר לקרוע שטר על סמך עדותו של עד אחד בלבד?! \u0003אלא\u0004 כך צריך לומר: \u0003מרענא שטרא אפומיה\u0004 \u0005[אני מרע את השטר על פיו],\u0006 שאיני מחשיבו לגבות בו, עד שתהיה הוכחה נוספת.","\u0003ההיא איתתא דאיחייבא\u0004 \u0005[אשה אחת שהתחייבה]\u0006 \u0003שבועה\u0004 ב\u0003בי דינא\u0004 \u0005[בבית הדין]\u0006 של \u0003רב ביבי בר אביי. אמר להו\u0004 \u0005[להם]\u0006 לדיינים \u0003ההוא\u0004 \u0005[אותו]\u0006 \u0003בעל דין: תיתי ותישתבע במתא\u0004 \u0005[\u0006ש\u0005תבוא ותישבע ב\u0006תוך \u0005העיר],\u0006 \u0003אפשר דמיכספא ומודיא\u0004 \u0005[שתתבייש\u0006 בשקר שהיא משקרת \u0005ותודה].\u0006 \u0003אמרה להו\u0004 \u0005[להם]\u0006 לדיינים: \u0003כתבו לי זכוותא\u0004 \u0005[כתב זכויות],\u0006 \u0003דכי משתבענא יהבי\u0004 \u0005[שכאשר אשבע יתנו]\u0006 \u0003לי\u0004 אותו ואז אני מוכנה להישבע אפילו בעיר. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב ביבי בר אביי: כתבו לה.\u0004","\u0003אמר רב פפי: משום דאתיתו ממולאי אמריתו מילי מוליתא\u0004 \u0005[שאתם,\u0006 בני משפחתכם, \u0005באים מאנשים אומללים, אומרים אתם דברים אומללים]?!\u0006 כי רב ביבי בא ממשפחת בית עלי, שהיו בניה מתים בקיצור שנים, ואמר לו שהדברים הללו שאמר אומללים, שאינם ראויים להיאמר. ומדוע?","— \u0003הא\u0004 \u0005[הרי]\u0006 כבר \u0003אמר רבא: האי אשרתא דדייני דמיכתבא מקמי דנחוו סהדי אחתימות ידייהו\u0004 \u0005[קיום דיינים\u0006 על שטר, \u0005שנכתב לפני שרואים עדים\u0006 ומעידים \u0005על חתימת ידם] —\u0006 \u0003פסולה,\u0004 אף על פי שהעידו אחר כך ונתקבלה עדותם. \u0003אלמא מיחזי כשיקרא\u0004 \u0005[הרי\u0006 שהוא \u0005נראה כשקר],\u0006 שאם כתבו וחתמו לפני שהעדות נגמרה בפניהם — נראה הדבר כאישור של שקר, \u0003הכי נמי מיחזי כשיקרא\u0004 \u0005[כאן גם כן\u0006 הרי זה \u0005נראה כשקר],\u0006 שאי אפשר לכתוב לה שטר זכויות לפני שתישבע, ואז יכתבו לה שטר.","ומעירים: \u0003וליתא\u0004 \u0005[ואין]\u0006 הלכה זו של רבא מקויימת, \u0003מ\u0004שום דברי \u0003רב נחמן.\u0004 ש\u0003אמר רב נחמן, אומר היה ר' מאיר:\u0004 גט, \u0003אפילו מצאו באשפה\u0004 והיו בו שמות כשמו ושם אשתו \u0003וחתמו\u0004 עליו עדים \u0003ונתנו לה\u0004 לאשתו — הרי זה \u0003כשר.\u0004 והוסיף רב נחמן: \u0003ואפילו רבנן\u0004 \u0005[חכמים]\u0006 \u0003לא פליגי עליה\u0004 \u0005[אינם חולקים עליו]\u0006 על \u0003ר' מאיר\u0004 בענין זה, \u0003אלא בגיטי נשים,\u0004 ומדוע? \u0003דבעינן\u0004 \u0005[שצריכים אנו]\u0006 לדעת חכמים שתהיה \u0003כתיבה\u0004 של הגט \u0003לשמה\u0004 של האשה המתגרשת, \u0003אבל בשאר שטרות — מודו ליה\u0004 \u0005[מודים לו]\u0006 שאין הבדל מתי נכתב השטר.","וראיה לדבר — ש\u0003אמר רב אסי אמר ר' יוחנן: שטר שלוה בו\u0004 פעם אחת \u0003ופרעו — אינו חוזר ולוה בו.\u0004 למרות שחוזר אותו אדם ולווה מאותו מלוה סכום זהה. ומדוע? \u0003שכבר נמחל שיעבודו,\u0004 כי כאשר נפרע השטר הראשון בטל כוח השעבוד שהיה בשטר זה. ולכן אם ימסור שטר זה למלווה, אינו שטר שיש לו כוח שעבוד, אלא כעין הלוואה בעל פה, ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003נמחל שיעבודו,\u0004 ולכן אין משתמשים עוד בשטר זה, \u0003אבל למיחזי\u0004"],["\u0003כשיקרא לא חיישינן\u0004 \u0005[לנראה כשקר אין אנו חוששים]\u0006 אם תוכן הדברים הוא אמת. ולכן אף כאן — אין לחשוש אם כתבו הדיינים את השטר לפני המעשה.","כאן עוברת הגמרא לדון במקרים בהם יש ויכוח על נכסי המת, ומסופר: \u0003ההוא גברא דאפקיד שב מרגניתא דציירי בסדינא בי\u0004 \u0005[אדם אחד הפקיד שבע מרגליות ש\u0006היו \u0005צרורות בסדין\u0006 ב\u0005בית]\u0006 \u0003ר' מיאשא בר בריה\u0004 \u0005[בן בנו]\u0006 של \u0003ר' יהושע בן לוי. שכיב\u0004 \u0005[מת]\u0006 \u0003ר' מיאשא ולא פקיד\u0004 \u0005[ציווה]\u0006 בשעת מותו לאנשי ביתו, דבר אודות אותן מרגליות, שלא אמר למי הן שייכות. \u0003אתו לקמיה\u0004 \u0005[באו\u0006 המפקיד ובני הבית \u0005לפני]\u0006 \u0003ר' אמי\u0004 לדון בענין המרגליות, \u0003אמר להו\u0004 \u0005[להם]:\u0006 של הטוען הוא, \u0003חדא, דידענא ביה\u0004 \u0005[\u0006סיבה \u0005אחת, שיודע אני בו]\u0006 \u0003בר' מיאשא בר בריה\u0004 \u0005[בן בנו]\u0006 של \u0003ר' יהושע בן לוי\u0004 שהוא \u0003לא אמיד\u0004 \u0005[עשיר]\u0006 עד כדי שיהיו מרגליות אלה שלו. \u0003ועוד, הא קא יהיב סימנא\u0004 \u0005[הרי\u0006 המפקיד \u0005נותן סימן]\u0006 שהם שבע ושהן צרורות בסדין.","ומעירים: \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 שסימן כזה מועיל \u0003אלא כ\u0004שהאיש הטוען \u0003לא רגיל דעייל ונפיק להתם\u0004 \u0005[שנכנס ויוצא לשם],\u0006 לבית בו נמצאים החפצים עליהם הוא טוען, \u0003אבל\u0004 אם אדם זה \u0003רגיל דעייל ונפיק להתם\u0004 \u0005[שנכנס ויוצא לשם],\u0006 \u0003אימא איניש אחרינא אפקיד ואיהו מיחזא חזא\u0004 \u0005[אמור\u0006 שמא \u0005אדם אחר הפקיד והוא\u0006 רק \u0005ראה\u0006 ונתן סימנים\u0005]\u0006 בדבר שאינו שלו.","עוד מסופר: \u0003ההוא גברא דאפקיד כסא דכספא בי\u0004 \u0005[אדם אחד שהפקיד כוס כסף\u0006 ב\u0005בית]\u0006 החכם \u0003חסא. שכיב\u0004 \u0005[מת]\u0006 \u0003חסא\u0004 בפתאומיות, שטבע בנהר (ראה להלן קכא, ב) \u0003ולא פקיד\u0004 \u0005[ציווה]\u0006 בשעת מותו דבר אודות אותה כוס כסף. \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רב נחמן\u0004 ונתן המפקיד בכוס סימן, \u0003אמר להו\u0004 \u0005[להם]\u0006 רב נחמן ליורשים: \u0003ידענא ביה\u0004 \u0005[יודע אני בו]\u0006 \u0003בחסא\u0004 שהוא \u0003לא אמיד\u0004 \u0005[עשיר]\u0006 וכוס זו לא לפי ערך רכושו היתה. \u0003ועוד, הא קא יהיב סימנא\u0004 \u0005[הרי\u0006 הוא \u0005נותן סימן].\u0006 \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 שסימן כזה מועיל \u0003אלא כ\u0004שהאיש הטוען \u0003לא רגיל דעייל ונפיק להתם\u0004 \u0005[שנכנס ויוצא לשם],\u0006 לבית בו נמצאים החפצים עליהם הוא טוען, \u0003אבל\u0004 אם אדם זה \u0003רגיל דעייל ונפיק להתם\u0004 \u0005[שנכנס ויוצא לשם],\u0006 \u0003אימא איניש אחרינא אפקיד ואיהו מיחזא חזא\u0004 \u0005[אמור\u0006 שמא \u0005אדם אחר הפקיד והוא\u0006 רק \u0005ראה\u0006 ונתן סימנים\u0005]\u0006 בדבר שאינו שלו.","וכן מסופר: \u0003ההוא דאפקיד מטכסא בי\u0004 \u0005[\u0006אדם \u0005אחד שהפקיד משי\u0006 ב\u0005בית]\u0006 \u0003רב דימי אחוה\u0004 \u0005[אחיו]\u0006 של \u0003רב ספרא, שכיב\u0004 \u0005[מת]\u0006 \u0003רב דימי ולא פקיד\u0004 \u0005[ציווה]\u0006 דבר לגבי משי זה. \u0003אתא לקמיה\u0004 \u0005[בא\u0006 המפקיד \u0005לפני]\u0006 \u0003ר' אבא, אמר להו\u0004 \u0005[להם]:\u0006 של הטוען הוא, \u0003חדא, דידענא ביה\u0004 \u0005[\u0006סיבה \u0005אחת, שיודע אני בו]\u0006 \u0003ברב דימי\u0004 שהוא \u0003לא אמיד\u0004 \u0005[עשיר],\u0006 \u0003ועוד, הא קא יהיב סימנא\u0004 \u0005[הרי\u0006 הוא \u0005נותן סימן].\u0006 \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 שסימן כזה מועיל \u0003אלא כ\u0004שהאיש הטוען \u0003לא רגיל דעייל ונפיק להתם\u0004 \u0005[שנכנס ויוצא לשם],\u0006 לבית בו נמצאים החפצים עליהם הוא טוען, \u0003אבל\u0004 אם אדם זה \u0003רגיל דעייל ונפיק להתם\u0004 \u0005[שנכנס ויוצא לשם],\u0006 \u0003אימא איניש אחרינא אפקיד ואיהו מיחזא חזא\u0004 \u0005[אמור\u0006 שמא \u0005אדם אחר הפקיד והוא\u0006 רק \u0005ראה\u0006 ונתן סימנים\u0005]\u0006 בדבר שאינו שלו.","\u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 לנוכחים לפני מותו: \u0003נכסיי\u0004 יהיו \u0003לטוביה\u0004 ולא פירש לאיזה טוביה. \u0003שכיב\u0004 \u0005[מת]\u0006 אותו האיש, \u0003אתא\u0004 \u0005[ובא]\u0006 \u0003טוביה\u0004 לתבוע. \u0003אמר ר' יוחנן: הרי בא טוביה,\u0004 ואין אנו צריכים לחשוש שמא התכוון לטוביה אחר.","ומוסיפים: אם \u0003אמר\u0004 הנפטר \u0003\"\u0004נכסיי ל\u0003טוביה\", ואתא\u0004 \u0005[ובא]\u0006 \u0003רב טוביה\u0004 — אנו אומרים שאינו אותו אדם שאליו התכוון, כי \u0003\"לטוביה\" אמר \"לרב טוביה\" לא אמר. ואי איניש דגיס ביה\u0004 \u0005[ואם\u0006 הוא \u0005אדם שרגיל בו\u0006 הנפטר\u0005]\u0006 — \u0003הא גיס ביה\u0004 \u0005[הרי רגיל בו]\u0006 ולכן אינו קורא לו בתוארו, אלא בשמו בלבד, וגם אם הוא רב טוביה, מן הסתם אליו התכוון. אם \u0003אתו\u0004 \u0005[באו]\u0006 \u0003שני\u0004 אנשים ששמם \u0003טוביה\u0004 לתבוע. אחד מהם היה \u0003שכן\u0004 של הנפטר ואחד \u0003תלמיד חכם\u0004 ואינו שכן — \u0003תלמיד חכם קודם,\u0004 שמן הסתם רצה להנות דווקא את התלמיד חכם כדי להטות את דינו לאחר מותו לכף זכות. וכן \u0003קרוב ותלמיד חכם — תלמיד חכם קודם.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 אם שניהם בעלי אותו שם, ואחד מהם \u0003שכן ו\u0004אחד \u0003קרוב, מאי\u0004 \u0005[מה]\u0006 הדין? \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר שנאמר: \u0003\"טוב שכן קרוב מאח רחוק\"\u0004 (משלי כז, י). והוסיפו לברר: אם \u0003שניהם קרובים,\u0004 או \u0003שניהם שכנים,\u0004 או \u0003שניהם חכמים,\u0004 מי מהם נוטל את נכסיו? ואמרו: אין דרך עקרונית להכריע בזה ולכן יש לעשות \u0003שודא דדייני\u0004 \u0005[השלכת,\u0006 הכרעת, \u0005הדיינים]\u0006 לפי ראות עיניהם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לבריה\u0004 \u0005[לבנו]\u0006 של \u0003רב חייא בר אבין: תא אימא\u0004 \u0005[בוא אומר]\u0006 \u0003לך מילתא מעליותא דהוה אמר אבוך\u0004 \u0005[דבר טוב שהיה אומר אביך]:\u0006 \u0003הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 ש\u0003אמר שמואל\u0004 ש\u0003המוכר שטר חוב לחבירו, וחזר\u0004 המוכר \u0003ומחלו\u0004 ללווה — הרי שטר חוב זה \u0003מחול,\u0004 משום שההתחייבות שבשטר היתה רק כלפי מי שכתוב בשטר ולא כלפי כל מי שמחזיק בשטר. \u0003ו\u0004לא זו בלבד, אלא \u0003אפילו יורש\u0004 של המלוה שמכר את השטר \u0003מוחל\u0004 את שטר החוב הזה — על כך אמר רב חייא בר אבין: \u0003מודה שמואל ב\u0004אשה ה\u0003מכנסת שטר חוב,\u0004 שמישהו חייב לה, \u0003לבעלה, וחזרה ומחלתו\u0004 ללווה — \u0003שאינו מחול.\u0004 ומדוע? — \u0003מפני שידו כידה,\u0004 שלאחר שנישאה זכות הבעל בנכסיה שווה לזכותה שלה, ולכן אין עוד בידה כוח למחול.","מסופר: \u0003קריבתיה\u0004 \u0005[קרובתו]\u0006 של \u0003רב נחמן זבינתה\u0004 \u0005[מכרה]\u0006 את \u0003כתובתה בטובת הנאה,\u0004 כלומר, שקיבלה תשלום מסויים עבור הסיכוי, שאם תתגרש ותהיה זכאית לקבל כתובה מבעלה — יעבור סכום הכתובה אותו היא אמורה לקבל, לקונה, ולאחר מכן \u0003איגרשה\u0004 \u0005[התגרשה]\u0006 מבעלה, \u0003ושכיבה\u0004 \u0005[ומתה]\u0006 ואת הזכות על סכום הכתובה ירשה בתה של אותה אשה שלא היו לה בנים . \u0003אתו קא תבעי לה לברתה\u0004 \u0005[באו\u0006 הקונים ו\u0005תבעו את בתה]\u0006 שתשלם להם את הכתובה, שהרי האם מכרה את הכתובה בחייה. \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב נחמן\u0004 לסובבים אותו: \u0003ליכא דליסבא\u0004 \u0005[\u0006האם \u0005אין\u0006 מי \u0005שיתן]\u0006 \u0003לה\u0004 לבת \u0003עצה?!\u0004 —"]]};
